// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"paclitaxel":{"wirkmechanismus":"Hemmt die Zellteilung, indem es das Zellskelett der Krebszellen «einfriert». Paclitaxel bindet an die β-Tubulin-Untereinheit der Mikrotubuli und stabilisiert sie, sodass sie nicht mehr abgebaut werden können. Die Mitosespindel verliert ihre Funktion, die Zellen bleiben in der G2/M-Phase stehen und sterben ab. Bei Abraxane ist Paclitaxel an Albumin-Nanopartikel gebunden und kommt ohne das allergieauslösende Lösungsmittel Macrogolglycerolricinoleat (Rizinusöl-Derivat) aus.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung: Neutropenie, Anämie, Thrombozytopenie, Blutungen","Infektionen (v. a. Harn- und obere Atemwege)","Periphere Neuropathie (Kribbeln, Taubheit in Händen und Füssen)","Leichte Überempfindlichkeitsreaktionen (Hautrötung, Ausschlag)","Blutdruckabfall","Übelkeit, Erbrechen, Durchfall, Mukositis (Schleimhautentzündung)","Haarausfall","Gelenk- und Muskelschmerzen"],"haeufig":["Bradykardie (langsamer Puls)","Vorübergehende Nagel- und Hautveränderungen","Reaktionen an der Injektionsstelle","Erhöhte Leberwerte (AST, alkalische Phosphatase)"],"gelegentlich":["Schwere Überempfindlichkeitsreaktionen (Blutdruckabfall, Atemnot, Angioödem, generalisierte Nesselsucht)","Septischer Schock","Herzrhythmusstörungen, AV-Block, Synkope, Herzinfarkt, Kardiomyopathie","Bluthochdruck, Thrombose, Thrombophlebitis","Stark erhöhtes Bilirubin"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Pneumonie, Sepsis, febrile Neutropenie","Herzschwäche","Interstitielle Pneumonie, Lungenfibrose, Lungenembolie","Darmverschluss, Darmperforation, ischämische Kolitis, Pankreatitis","Motorische Neuropathie (Muskelschwäche)"],"sehrSelten":["Akute myeloische Leukämie, myelodysplastisches Syndrom","Autonome Neuropathie (Darmlähmung, Blutdruckabfall beim Aufstehen), Krampfanfälle, Enzephalopathie","Sehnerv- und Sehstörungen, Hörverlust, Tinnitus","Vorhofflimmern","Lebernekrose, hepatische Enzephalopathie","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme"],"unbekannt":["Tumorlyse-Syndrom","Makulaödem (Netzhautschwellung), Lichtblitze","Sklerodermie-artige Hautverhärtung","Kutaner Lupus erythematodes","Disseminierte intravasale Gerinnung (Verbrauchskoagulopathie)"]},"schwangerschaft":"Im Tierversuch fruchtschädigend; in der Schwangerschaft nur bei zwingender Indikation. Frauen und Männer müssen während und je nach Präparat mehrere Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert – während der Behandlung nicht stillen.","hinweise":["Vor konventionellem Paclitaxel ist eine Vorbehandlung mit Kortikosteroid und Antihistaminika nötig; Abraxane braucht keine und ist mit konventionellem Paclitaxel nicht austauschbar.","Die konventionelle Infusionslösung enthält Alkohol: nach der Infusion nicht Auto fahren, bis die Wirkung abgeklungen ist.","Kribbeln oder Taubheit in Händen und Füssen früh melden – eine Dosisanpassung kann bleibende Nervenschäden verhindern.","Blutbild vor jedem Zyklus; bei Fieber sofort ärztliche Hilfe holen."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung","Pulver zur Herstellung einer Infusionssuspension (an Albumin gebunden)"]},"palbociclib":{"wirkmechanismus":"Bremst die Teilung hormonempfindlicher Brustkrebszellen. Palbociclib hemmt selektiv die Cyclin-abhängigen Kinasen 4 und 6 (CDK4/6), die zusammen mit Cyclin D das Retinoblastom-Protein (Rb) phosphorylieren. Ohne diese Phosphorylierung bleibt der Zellzyklus in der G1-Phase stehen, und die Zelle kann die DNA-Synthese nicht beginnen. Zusammen mit einer antihormonellen Therapie verstärkt sich die wachstumshemmende Wirkung.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Leukopenie, Anämie, Thrombozytopenie","Infektionen","Stomatitis, Übelkeit, Durchfall, Erbrechen","Appetitlosigkeit","Haarausfall, Hautausschlag, trockene Haut","Müdigkeit, Schwäche (Asthenie), Fieber"],"haeufig":["Febrile Neutropenie","Geschmacksstörungen","Verschwommenes Sehen, vermehrter Tränenfluss, trockene Augen","Nasenbluten","Interstitielle Lungenerkrankung, Pneumonitis","Erhöhte Leberwerte (ALT, AST)"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen müssen während und mindestens 3 Wochen nach der Behandlung sicher verhüten, Männer mit Partnerin im gebärfähigen Alter während und noch etwa 3 Monate danach.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Einnahme an 21 Tagen, danach 7 Tage Pause; täglich etwa zur gleichen Zeit. Kapseln mit einer Mahlzeit, Tabletten mit oder ohne Mahlzeit unzerkaut schlucken.","Grapefruit und Grapefruitsaft meiden; Johanniskraut ist nicht erlaubt.","Das Blutbild wird regelmässig kontrolliert; Fieber oder Infektzeichen sofort melden."],"darreichung":["Kapseln","Filmtabletten"]},"paliperidon":{"wirkmechanismus":"Dämpft Wahn und Halluzinationen, indem es die Wirkung von Dopamin und Serotonin im Gehirn hemmt. Paliperidon (9-Hydroxy-Risperidon) ist der aktive Metabolit von Risperidon und blockiert Dopamin-D2- und Serotonin-5-HT2A-Rezeptoren sowie Alpha-1- und Histamin-H1-Rezeptoren. Es wird kaum in der Leber abgebaut und überwiegend unverändert über die Niere ausgeschieden. Das Depot (Paliperidonpalmitat) gibt den Wirkstoff über Wochen bis Monate gleichmässig ab.","nebenwirkungen":{"sehrHaeufig":["Schlaflosigkeit","Kopfschmerzen"],"haeufig":["Parkinsonismus, Sitzunruhe (Akathisie), Dystonie, Dyskinesien, Zittern","Schläfrigkeit, Schwindel","Erhöhtes Prolaktin, Gewichtszunahme, erhöhter Blutzucker","Angst, Unruhe, Depression","Herzrasen, Bluthochdruck","Übelkeit, Erbrechen, Verstopfung, Durchfall, Bauchschmerzen","Atemwegs- und Harnwegsinfekte","Reaktionen an der Injektionsstelle, Schwäche, Fieber"],"gelegentlich":["QT-Verlängerung, Bradykardie, AV-Block","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen), Ohnmacht","Krampfanfälle, Spätdyskinesien","Diabetes","Milchfluss, Ausbleiben der Regel, sexuelle Funktionsstörungen","Neutropenie, Anämie"],"selten":["Malignes neuroleptisches Syndrom","Venöse Thromboembolie","Darmverschluss, Pankreatitis","Priapismus","Floppy-Iris-Syndrom bei Operation des Grauen Stars"],"unbekannt":["Agranulozytose","Anaphylaxie, Angioödem","Entzugssymptome und Bewegungsstörungen beim Neugeborenen"]},"schwangerschaft":"Begrenzte Erfahrungen; nur anwenden, wenn der Nutzen das Risiko überwiegt. Nach Anwendung im letzten Drittel sind beim Neugeborenen Bewegungsstörungen und Entzugssymptome möglich; das Depot wirkt noch Monate nach.","stillzeit":"Paliperidon geht in die Muttermilch über. Während der Behandlung nicht stillen.","hinweise":["Retardtabletten morgens ganz schlucken; die leere Tablettenhülle kann im Stuhl erscheinen – das ist normal.","Termine für die Depotspritze einhalten; eine verpasste Injektion ärztlich nachholen lassen.","Gewicht, Blutzucker und Blutfette regelmässig kontrollieren.","Langsam aufstehen; Alkohol meiden, Fahrtüchtigkeit kann beeinträchtigt sein."],"darreichung":["Retardtabletten","Depot-Injektionssuspension"]},"palivizumab":{"wirkmechanismus":"Schützt Säuglinge mit fertigen Antikörpern vor dem RS-Virus (passive Immunisierung). Palivizumab ist ein humanisierter monoklonaler IgG1-Antikörper, der an das Fusionsprotein (F-Protein, antigene Stelle A) des RS-Virus bindet. Dadurch wird das Virus neutralisiert und kann nicht mit den Zellen der Atemwege verschmelzen. Weil der Antikörper abgebaut wird, sind während der RSV-Saison monatliche Injektionen nötig.","nebenwirkungen":{"sehrHaeufig":["Fieber","Hautausschlag"],"haeufig":["Reaktionen an der Einstichstelle","Apnoe (Atemaussetzer)"],"gelegentlich":["Krampfanfälle","Thrombozytopenie (Mangel an Blutplättchen)","Nesselsucht"],"unbekannt":["Anaphylaxie, anaphylaktischer Schock"]},"schwangerschaft":"Nicht zutreffend: Palivizumab ist nur für Säuglinge und Kleinkinder bestimmt.","stillzeit":"Nicht zutreffend: Palivizumab ist nur für Säuglinge und Kleinkinder bestimmt.","hinweise":["Während der ganzen RSV-Saison monatlich injizieren; Termine einhalten, sonst sinkt der Schutz.","Andere Impfungen können normal weitergeführt werden.","Bei Atemnot, Schwellungen oder Ausschlag nach der Injektion sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung (intramuskulär)"]},"palonosetron":{"wirkmechanismus":"Verhindert den durch Chemotherapie ausgelösten Brechreiz über mehrere Tage. Palonosetron blockiert selektiv und mit sehr hoher Bindungsstärke die Serotonin-5-HT3-Rezeptoren an den Vagusnerv-Endigungen im Darm und in der Brechreizzone des Hirnstamms. Im Unterschied zu älteren Setronen bindet es zusätzlich allosterisch, führt zur Internalisierung der Rezeptoren und hat eine lange Halbwertszeit von rund 40 Stunden; deshalb genügt meist eine Einzeldosis pro Chemotherapie-Zyklus.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schwindel","Obstipation (Verstopfung)","Durchfall"],"gelegentlich":["Schlaflosigkeit oder Schläfrigkeit, Angst","Missempfindungen (Kribbeln), periphere Nervenstörungen","Herzrhythmusstörungen (Herzrasen, langsamer Puls, Extrasystolen), QT-Verlängerung im EKG","Blutdruckabfall oder Blutdruckanstieg","Bauchschmerzen, Verdauungsbeschwerden, Mundtrockenheit, Blähungen","Elektrolytstörungen (z. B. erhöhtes Kalium, tiefes Calcium), erhöhter Blutzucker","Erhöhte Leberwerte und Bilirubin","Müdigkeit, Schwäche, grippeähnliche Beschwerden"],"sehrSelten":["Anaphylaxie und andere Überempfindlichkeitsreaktionen","Reaktionen an der Injektionsstelle (Brennen, Schmerzen, Rötung)"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; in der Schwangerschaft nur anwenden, wenn es klar notwendig ist.","stillzeit":"Nicht bekannt, ob Palonosetron in die Muttermilch übergeht; während der Behandlung soll nicht gestillt werden.","hinweise":["Wird in der Regel einmalig etwa 30 Minuten vor Beginn der Chemotherapie gespritzt; weitere Gaben innerhalb von 7 Tagen nicht empfohlen.","Verstopfung ist häufig: ausreichend trinken und bei anhaltenden Beschwerden die Behandlungsteams informieren."],"darreichung":["Injektionslösung","Kapseln (Kombination mit Netupitant)"]},"pamidronsaeure":{"wirkmechanismus":"Hemmt den Knochenabbau. Pamidronsäure bindet stark an das Knochenmineral und wird von den knochenabbauenden Zellen (Osteoklasten) aufgenommen. Als stickstoffhaltiges Bisphosphonat hemmt sie dort das Enzym Farnesylpyrophosphat-Synthase, wodurch Funktion und Überleben der Osteoklasten gestört werden. Dadurch sinken Knochenabbau, Calciumfreisetzung aus dem Knochen und das Risiko für Knochenkomplikationen.","nebenwirkungen":{"sehrHaeufig":["Fieber und grippeähnliche Beschwerden, teils mit Schüttelfrost und Müdigkeit","Hypokalzämie (tiefes Calcium)","Hypophosphatämie (tiefes Phosphat)"],"haeufig":["Kopfschmerzen, Schlaflosigkeit, Schläfrigkeit","Übelkeit, Erbrechen, Appetitlosigkeit, Bauchschmerzen, Durchfall oder Verstopfung","Vorübergehende Knochen-, Gelenk- und Muskelschmerzen","Reaktionen an der Infusionsstelle (Schmerz, Rötung, Schwellung, Venenentzündung)","Anämie, Thrombozytopenie, Lymphozytopenie (Blutbildveränderungen)","Hypokaliämie, Hypomagnesiämie","Bindehautentzündung, Bluthochdruck, Hautausschlag","Anstieg des Kreatinins (Nierenwert)"],"gelegentlich":["Allergische Reaktionen, Bronchospasmus, Angioödem","Krampfanfälle, Unruhe, Schwindel","Augenentzündungen (Uveitis, Iritis)","Blutdruckabfall","Muskelkrämpfe","Akutes Nierenversagen","Veränderte Leberwerte"],"selten":["Nierenschäden mit Eiweissverlust (fokal-segmentale Glomerulosklerose, nephrotisches Syndrom)","Verwirrtheit, optische Halluzinationen","Herzinsuffizienz durch Flüssigkeitsüberladung","Atypische Oberschenkelbrüche"],"sehrSelten":["Anaphylaktischer Schock","Reaktivierung von Herpes-Infektionen","Akutes Atemnotsyndrom, interstitielle Lungenerkrankung","Osteonekrose des äusseren Gehörgangs"],"unbekannt":["Kiefernekrose (Absterben von Kieferknochen)","Vorhofflimmern"]},"schwangerschaft":"Nicht anwenden, ausser bei lebensbedrohlicher Hyperkalzämie; Pamidronsäure kann die Knochenentwicklung des Ungeborenen beeinträchtigen.","stillzeit":"Kontraindiziert; vor Beginn der Behandlung abstillen.","hinweise":["Wird immer als langsame Infusion gegeben, nie als rasche Injektion; vorher ausreichend Flüssigkeit.","Gute Zahnpflege und regelmässige Zahnkontrollen; Zahnärztin oder Zahnarzt über die Behandlung informieren.","Nach der Infusion wegen möglicher Schläfrigkeit oder Schwindel nicht selbst Auto fahren.","Calcium, Phosphat, Magnesium und Nierenwerte werden regelmässig kontrolliert."],"darreichung":["Konzentrat bzw. Pulver zur Herstellung einer Infusionslösung"]},"panitumumab":{"wirkmechanismus":"Blockiert eine Antenne für Wachstumssignale auf Darmkrebszellen. Panitumumab ist ein vollständig humaner IgG2-Antikörper, der mit hoher Affinität an den epidermalen Wachstumsfaktor-Rezeptor (EGFR) bindet und dessen Aktivierung durch EGF und TGF-alpha verhindert. Dadurch werden Zellwachstum und -überleben gehemmt und der Zelltod gefördert. Bei RAS-Mutation ist der Signalweg unterhalb des Rezeptors dauerhaft eingeschaltet, deshalb wirkt Panitumumab nur bei RAS-Wildtyp-Tumoren.","nebenwirkungen":{"sehrHaeufig":["Hautreaktionen (akneartiger Ausschlag, Rötung, Juckreiz, Hautrisse, trockene Haut)","Paronychie (Nagelbettentzündung)","Hypomagnesiämie, Hypokaliämie (Magnesium- und Kaliummangel)","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Verstopfung","Stomatitis (Mundschleimhautentzündung)","Müdigkeit, Fieber, Ödeme","Konjunktivitis (Bindehautentzündung)","Atemnot, Husten"],"haeufig":["Infusionsreaktionen","Hypokalzämie (Calciummangel)","Dehydratation (Flüssigkeitsverlust)","Lungenembolie, tiefe Venenthrombose","Haarveränderungen, Haarausfall","Kopfschmerzen, Schwindel","Nasenbluten","Hautgeschwüre und Hautinfektionen"],"gelegentlich":["Keratitis (Hornhautentzündung)","Interstitielle Lungenerkrankung","Schwere Infusionsreaktionen, Anaphylaxie"],"unbekannt":["Hautnekrose, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse"]},"schwangerschaft":"Nicht anwenden, ausser der Nutzen überwiegt klar: EGFR ist für die Entwicklung des Ungeborenen wichtig. Frauen im gebärfähigen Alter verhüten während der Behandlung und 2 Monate danach.","stillzeit":"Während der Behandlung und 2 Monate nach der letzten Dosis nicht stillen.","hinweise":["Sonne meiden, Sonnenschutz und Feuchtigkeitscreme verwenden: Hautreaktionen sind sehr häufig und werden durch Sonne verstärkt.","Starken Durchfall, Augenschmerzen oder -rötung, Atemnot oder Husten sofort melden.","Magnesium, Calcium und Kalium werden regelmässig kontrolliert, auch einige Wochen nach Behandlungsende.","Vor Beginn wird der RAS-Status des Tumors bestimmt."],"darreichung":["Infusionskonzentrat"]},"pankreatin":{"wirkmechanismus":"Ersetzt die Verdauungsenzyme, die eine geschwächte Bauchspeicheldrüse nicht mehr ausreichend bildet. Pankreatin wird aus der Bauchspeicheldrüse von Schweinen gewonnen und enthält Lipase (spaltet Fett), Amylase (spaltet Stärke) und Proteasen (spalten Eiweiss). Magensaftresistent überzogene Mikropellets schützen die Enzyme vor der Magensäure, mischen sich mit dem Speisebrei und geben die Enzyme erst im Zwölffingerdarm frei. Dadurch bessern sich Fettstühle, Blähungen und Gewichtsverlust, und fettlösliche Vitamine werden besser aufgenommen; die Enzyme wirken nur im Darm und werden nicht ins Blut aufgenommen.","nebenwirkungen":{"sehrHaeufig":["Bauchschmerzen"],"haeufig":["Übelkeit, Erbrechen","Verstopfung (Obstipation)","Blähbauch","Durchfall"],"gelegentlich":["Hautausschlag"],"unbekannt":["Fibrosierende Kolonopathie (Verengungen am Übergang Dünn-/Dickdarm und im Dickdarm), v. a. bei hohen Dosen und zystischer Fibrose","Überempfindlichkeitsreaktionen bis Anaphylaxie","Juckreiz, Nesselsucht"]},"schwangerschaft":"Die Enzyme werden nicht aufgenommen; bei Bedarf kann Pankreatin in der Schwangerschaft angewendet werden, um eine ausreichende Ernährung sicherzustellen.","stillzeit":"Anwendung in der Stillzeit möglich.","hinweise":["Zu jeder Mahlzeit und Zwischenmahlzeit einnehmen; Kapseln unzerkaut mit Flüssigkeit schlucken.","Bei Schluckproblemen Kapsel öffnen und die Pellets mit einer sauren, weichen Speise (z. B. Apfelmus) einnehmen – nicht zerkauen und nicht in heisse Speisen mischen (Reizung der Mundschleimhaut, Wirkungsverlust).","Ausreichend trinken, besonders bei zystischer Fibrose (beugt Verstopfung vor).","Enthält Eiweiss vom Schwein."],"darreichung":["Kapseln mit magensaftresistenten Mikropellets"]},"pantoprazol":{"wirkmechanismus":"Senkt die Bildung von Magensäure stark und anhaltend. Pantoprazol wird in den sauren Belegzellen der Magenschleimhaut in seine aktive Form umgewandelt und blockiert dort irreversibel die Protonenpumpe (H+/K+-ATPase), den letzten Schritt der Säurebildung. Da neue Pumpen erst nachgebildet werden müssen, hält die Wirkung länger an, als der Wirkstoff im Blut vorhanden ist. Pantoprazol wird über CYP2C19 und CYP3A4 abgebaut, hemmt diese Enzyme aber kaum und hat daher weniger Wechselwirkungen als Omeprazol.","nebenwirkungen":{"haeufig":["Gutartige Drüsenpolypen im Magen (Fundusdrüsenpolypen)"],"gelegentlich":["Kopfschmerzen, Schwindel","Schlafstörungen","Durchfall, Verstopfung, Blähungen, Bauchschmerzen","Übelkeit, Erbrechen, Mundtrockenheit","Erhöhte Leberwerte","Hautausschlag, Juckreiz","Knochenbrüche (Hüfte, Handgelenk, Wirbelsäule)","Schwäche, Müdigkeit, Unwohlsein"],"selten":["Agranulozytose (starker Mangel an weissen Blutkörperchen)","Überempfindlichkeitsreaktionen bis zum anaphylaktischen Schock, Angioödem, Nesselsucht","Depression, Geschmacksstörungen, Sehstörungen","Erhöhte Blutfette, Gewichtsveränderungen","Gelenk- und Muskelschmerzen","Gynäkomastie (Brustvergrösserung beim Mann), Fieber, Wassereinlagerungen"],"sehrSelten":["Thrombozytopenie, Leukopenie, Panzytopenie (Mangel an Blutzellen)","Desorientierung"],"unbekannt":["Hyponatriämie (Natriummangel) und Hypomagnesiämie (Magnesiummangel)","Halluzinationen, Verwirrtheit","Mikroskopische Kolitis","Leberzellschädigung, Gelbsucht, Leberversagen","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme, DRESS","Subakuter kutaner Lupus erythematodes, Lichtempfindlichkeit","Tubulointerstitielle Nephritis (Nierenentzündung)","Muskelkrämpfe"]},"schwangerschaft":"Erfahrungen sind begrenzt; vorsichtshalber in der Schwangerschaft nur nach ärztlicher Abwägung anwenden.","stillzeit":"Pantoprazol geht in die Muttermilch über; nur nach ärztlicher Nutzen-Risiko-Abwägung anwenden.","hinweise":["Tablette unzerkaut mit etwas Wasser etwa 1 Stunde vor einer Mahlzeit, meist vor dem Frühstück, einnehmen.","Rezeptfreie Selbstbehandlung (20 mg) höchstens 4 Wochen; tritt nach 2 Wochen keine Besserung ein, ärztlich abklären.","Nach längerer Einnahme nicht abrupt absetzen: vorübergehend vermehrte Säurebildung (Rebound) möglich.","Bei Langzeitbehandlung regelmässig die Notwendigkeit sowie Magnesium und Vitamin B12 überprüfen lassen."],"darreichung":["Magensaftresistente Tabletten","Pulver zur Herstellung einer Injektionslösung"]},"paracetamol":{"wirkmechanismus":"Lindert Schmerzen und senkt Fieber, ohne Magen und Blutplättchen wesentlich zu beeinflussen. Paracetamol hemmt vorwiegend im Zentralnervensystem die Bildung von Prostaglandinen und beeinflusst schmerzhemmende Bahnen, unter anderem über serotonerge Mechanismen; entzündungshemmend wirkt es kaum. In der Leber entsteht in kleinen Mengen das giftige Abbauprodukt NAPQI, das normalerweise durch Glutathion entgiftet wird. Bei Überdosierung oder Glutathionmangel kann es die Leber schwer schädigen; Gegenmittel ist Acetylcystein.","nebenwirkungen":{"selten":["Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht)","Erhöhte Leberwerte","Blutdruckabfall, Unwohlsein (Infusion)"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion), Angioödem","Thrombozytopenie, Leukopenie, Agranulozytose (Blutbildveränderungen)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP)","Bronchospasmus bei Analgetika-Asthma"],"unbekannt":["Leberschaden bis Leberversagen bei Überdosierung oder Risikofaktoren","Metabolische Azidose mit hoher Anionenlücke bei Risikofaktoren","Schmerzen oder Brennen an der Infusionsstelle"]},"schwangerschaft":"Gilt als Schmerz- und Fiebermittel der Wahl in der Schwangerschaft; dennoch nur bei Bedarf, in der niedrigsten wirksamen Dosis und so kurz wie möglich einnehmen.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; in üblicher Dosierung ist Stillen möglich.","hinweise":["Höchstdosis beachten: Erwachsene in der Regel höchstens 4 g pro Tag, bei Lebererkrankung, regelmässigem Alkoholkonsum oder Körpergewicht unter 50 kg weniger; Kinder nach Körpergewicht dosieren.","Viele Kombinations-, Grippe- und Erkältungsmittel enthalten ebenfalls Paracetamol – nicht doppelt einnehmen.","Bei Verdacht auf Überdosierung sofort ärztliche Hilfe holen, auch ohne Beschwerden – das Gegenmittel wirkt nur früh.","Ohne ärztlichen Rat nicht länger als 5 Tage gegen Schmerzen bzw. 3 Tage gegen Fieber einnehmen."],"darreichung":["Tabletten","Filmtabletten","Brausetabletten","Schmelztabletten","Sirup","Zäpfchen","Infusionslösung"]},"paracetamol-codein":{"wirkmechanismus":"Kombiniert zwei unterschiedlich wirkende Schmerzmittel, die sich ergänzen. Paracetamol hemmt vor allem im Zentralnervensystem die Bildung von Prostaglandinen und wirkt schmerzlindernd und fiebersenkend. Codein ist eine Vorstufe (Prodrug): Es wird in der Leber durch das Enzym CYP2D6 zu Morphin umgewandelt, das an μ-Opioidrezeptoren die Schmerzweiterleitung hemmt. Bei «ultraschnellen Metabolisierern» entsteht ungewöhnlich viel Morphin, bei «langsamen Metabolisierern» wirkt Codein kaum.","nebenwirkungen":{"haeufig":["Obstipation (Verstopfung)","Übelkeit, Erbrechen","Schläfrigkeit, Benommenheit, Schwindel"],"selten":["Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht)","Erhöhte Leberwerte"],"sehrSelten":["Thrombozytopenie, Agranulozytose (Mangel an Blutplättchen bzw. weissen Blutkörperchen)","Anaphylaxie (schwere allergische Reaktion)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP)","Bronchospasmus bei Analgetika-Asthma"],"unbekannt":["Atemdepression, besonders bei ultraschnellen CYP2D6-Metabolisierern","Kopfschmerzen, Juckreiz","Abhängigkeit bei längerem Gebrauch","Leberschaden bis Leberversagen bei Überdosierung","Metabolische Azidose mit hoher Anionenlücke bei Risikofaktoren"]},"schwangerschaft":"Nur nach ärztlicher Abwägung, so kurz und niedrig dosiert wie möglich. Im letzten Drittel und unter der Geburt meiden (Atemdepression und Entzugssymptome beim Neugeborenen).","stillzeit":"Kontraindiziert: Codein wird zu Morphin umgewandelt, das in die Muttermilch übergeht; bei ultraschnellen Metabolisiererinnen ist eine lebensbedrohliche Vergiftung des Säuglings möglich.","hinweise":["Höchstdosis von Paracetamol nicht überschreiten (Erwachsene in der Regel 4 g pro Tag, bei Risikofaktoren weniger); keine weiteren paracetamolhaltigen Mittel gleichzeitig.","Kein Alkohol; die Fahrtüchtigkeit kann eingeschränkt sein.","Bei Atembeschwerden, starker Schläfrigkeit oder Verwirrtheit sofort ärztliche Hilfe holen.","Nicht länger als nötig einnehmen (Gefahr von Abhängigkeit und Kopfschmerz durch Übergebrauch)."],"darreichung":["Filmtabletten","Brausetabletten"]},"paracetamol-phenylephrin-pheniramin":{"wirkmechanismus":"Lindert Schmerzen und Fieber, lässt die geschwollene Nasenschleimhaut abschwellen und dämpft Niesreiz und Nasenlaufen. Paracetamol wirkt schmerzlindernd und fiebersenkend über eine Hemmung der Prostaglandinbildung vorwiegend im zentralen Nervensystem. Phenylephrin ist ein Alpha-1-Sympathomimetikum, das die Blutgefässe der Nasenschleimhaut verengt. Pheniramin blockiert Histamin-H1-Rezeptoren und wirkt zusätzlich anticholinerg und dämpfend.","nebenwirkungen":{"sehrSelten":["Überempfindlichkeitsreaktionen bis Anaphylaxie (schwere allergische Reaktion)","Thrombozytopenie, Agranulozytose (Mangel an Blutplättchen bzw. weissen Blutkörperchen)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Bronchospasmus (Verkrampfung der Atemwege) bei Analgetika-Asthma"],"unbekannt":["Schläfrigkeit, Müdigkeit, Benommenheit","Mundtrockenheit","Herzklopfen, Herzrasen, Blutdruckanstieg","Nervosität, Schlaflosigkeit","Harnverhalt (Schwierigkeiten beim Wasserlassen)","Sehstörungen (Akkommodationsstörungen)","Übelkeit, Magenbeschwerden","Erhöhte Leberwerte; Leberschäden bei Überdosierung"]},"schwangerschaft":"In der Schwangerschaft nicht anwenden; falls nötig, ist Paracetamol allein nach ärztlichem Rat vorzuziehen.","stillzeit":"In der Stillzeit nicht anwenden (Phenylephrin und Pheniramin gehen in die Muttermilch über; Säuglinge reagieren empfindlich).","hinweise":["Nicht gleichzeitig mit anderen paracetamolhaltigen Mitteln einnehmen und die Höchstdosis der Packungsbeilage einhalten – eine Überdosierung kann die Leber schwer schädigen.","Macht müde: kein Alkohol, Vorsicht beim Autofahren und Bedienen von Maschinen.","Ohne ärztlichen Rat nur wenige Tage anwenden; bei hohem oder anhaltendem Fieber ärztlich abklären lassen."],"darreichung":["Pulver zur Herstellung einer Trinklösung (Beutel)"]},"paraffin-dickfluessig":{"wirkmechanismus":"Macht den Stuhl weich und gleitfähig. Dickflüssiges Paraffin ist ein unverdauliches Mineralöl, das im Darm kaum aufgenommen wird. Es umhüllt den Darminhalt, vermindert den Wasserentzug aus dem Stuhl und erleichtert so dessen Passage (Gleitmittel-Laxans).","nebenwirkungen":{"unbekannt":["Austritt von Öl aus dem After, Juckreiz und Reizung im Analbereich","Durchfall und Bauchkrämpfe bei zu hoher Dosis","Verminderte Aufnahme fettlöslicher Vitamine bei Langzeitgebrauch","Lipidpneumonie (Lungenentzündung durch eingeatmetes Öl)","Fremdkörperreaktionen (Paraffinome) in Darmwand und Lymphknoten bei Langzeitgebrauch"]},"schwangerschaft":"Nur kurzfristig und nach ärztlicher Rücksprache anwenden; längerer Gebrauch kann die Aufnahme fettlöslicher Vitamine (v. a. Vitamin K) vermindern.","stillzeit":"Wird kaum ins Blut aufgenommen; eine kurzfristige Anwendung nach Rücksprache ist vertretbar.","hinweise":["Nicht im Liegen und nicht unmittelbar vor dem Schlafengehen einnehmen (Gefahr des Einatmens).","Mindestens 2 Stunden Abstand zu anderen Medikamenten einhalten.","Ohne ärztlichen Rat nur kurzfristig anwenden; ballaststoffreiche Ernährung, ausreichend Flüssigkeit und Bewegung sind die Grundlage."],"darreichung":["Emulsion zum Einnehmen"]},"parecoxib":{"wirkmechanismus":"Lindert Schmerzen und Entzündung nach Operationen. Parecoxib wird in der Leber rasch zu Valdecoxib umgewandelt, das selektiv die Cyclooxygenase-2 (COX-2) hemmt und so die Bildung entzündungs- und schmerzvermittelnder Prostaglandine vermindert. Die für Magenschleimhaut und Blutplättchen wichtige COX-1 wird in therapeutischer Dosis kaum gehemmt; die Blutgerinnung wird daher nicht beeinträchtigt. Valdecoxib wird über CYP3A4 und CYP2C9 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Übelkeit"],"haeufig":["Anämie nach der Operation, Hypokaliämie (Kaliummangel)","Unruhe, Schlaflosigkeit","Bluthochdruck oder Blutdruckabfall","Bauchschmerzen, Erbrechen, Verstopfung, Dyspepsie, Blähungen","Juckreiz, vermehrtes Schwitzen","Verminderte Harnmenge, Kreatininanstieg, periphere Ödeme","Atemschwäche, Rachenentzündung","Rückenschmerzen, entzündete Zahnalveole nach Zahnextraktion"],"gelegentlich":["Herzinfarkt, Bradykardie (langsamer Puls)","Zerebrovaskuläre Ereignisse, Lungenembolie","Magen-Darm-Geschwüre","Thrombozytopenie","Wundinfektion, Blutergüsse","Hautausschlag, Nesselsucht","Erhöhte Leberwerte"],"selten":["Anaphylaktoide Reaktionen","Akutes Nierenversagen","Bauchspeicheldrüsenentzündung (Pankreatitis)"],"unbekannt":["Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme)","Herzinsuffizienz, Kreislaufkollaps","Atemnot"]},"schwangerschaft":"Im 1. und 2. Drittel nicht empfohlen; im letzten Drittel kontraindiziert.","stillzeit":"In der Stillzeit kontraindiziert.","hinweise":["Wird von medizinischen Fachpersonen gespritzt (in die Vene oder den Muskel); nur kurzfristig, in der Regel höchstens 3 Tage.","Ersetzt niedrig dosierte Acetylsalicylsäure zum Herzschutz nicht.","Hautausschlag, Schleimhautveränderungen oder Atemnot sofort melden."],"darreichung":["Pulver zur Herstellung einer Injektionslösung"]},"paricalcitol":{"wirkmechanismus":"Senkt die Ausschüttung des Nebenschilddrüsenhormons (Parathormon), das bei Nierenkranken übermässig gebildet wird. Paricalcitol ist ein synthetisches, bereits aktives Vitamin-D-Analogon und muss – anders als natürliches Vitamin D – nicht in der Niere aktiviert werden. Es bindet an Vitamin-D-Rezeptoren der Nebenschilddrüse und hemmt Bildung und Freisetzung von Parathormon. Die Aufnahme von Calcium und Phosphat aus dem Darm steigert es weniger stark als Calcitriol.","nebenwirkungen":{"haeufig":["Hyperkalzämie (erhöhtes Calcium im Blut)","Hyperphosphatämie (erhöhtes Phosphat im Blut)","Kopfschmerzen","Geschmacksstörungen","Juckreiz"],"gelegentlich":["Übelkeit, Erbrechen, Verstopfung, Durchfall","Mundtrockenheit, Appetitminderung","Schwindel","Herzklopfen","Hautausschlag, Nesselsucht","Muskelkrämpfe, Muskelschmerzen","Hypokalzämie (tiefes Calcium im Blut)","Erhöhte Leberwerte"],"unbekannt":["Angioödem (Schwellung von Gesicht, Lippen, Zunge) und Kehlkopfschwellung","Zu starke Unterdrückung des Parathormons"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen; im Tierversuch Schädigungen. Nur anwenden, wenn unbedingt erforderlich.","stillzeit":"Nicht bekannt, ob Paricalcitol beim Menschen in die Muttermilch übergeht (im Tierversuch in geringen Mengen). Ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Regelmässige Blutkontrollen von Calcium, Phosphat und Parathormon, besonders zu Beginn und nach Dosisänderungen.","Zeichen eines zu hohen Calciums melden: Müdigkeit, Übelkeit, Verstopfung, starker Durst, vermehrtes Wasserlassen, Verwirrtheit.","Keine weiteren Vitamin-D- oder Calciumpräparate ohne ärztliche Rücksprache einnehmen; Vorgaben zu Ernährung und Phosphatbindern einhalten."],"darreichung":["Weichkapseln","Injektionslösung"]},"paromomycin":{"wirkmechanismus":"Tötet Krankheitserreger direkt im Darm ab, da es kaum ins Blut aufgenommen wird. Paromomycin bindet als Aminoglykosid an die 30S-Untereinheit der Ribosomen von Bakterien und Amöben und stört so deren Eiweissbildung. Gegen Amöben im Darminneren wirkt es abtötend; bei schweren Leberkrankheiten vermindert es die Darmbakterien, die Ammoniak bilden.","nebenwirkungen":{"unbekannt":["Übelkeit, Bauchkrämpfe und Durchfall (vor allem bei hohen Dosen)","Malabsorption (gestörte Nährstoffaufnahme) mit Fettstühlen","Hautausschlag, Juckreiz","Pilzinfektionen oder Überwucherung mit resistenten Keimen","Durchfall durch Clostridioides difficile","Nieren- und Gehörschäden bei Aufnahme ins Blut"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Paromomycin wird kaum aufgenommen; Aminoglykoside können bei Aufnahme ins Blut das Gehör des Ungeborenen schädigen.","stillzeit":"Wird kaum ins Blut aufgenommen; Anwendung nach ärztlicher Abwägung.","hinweise":["Kapseln zu den Mahlzeiten einnehmen und die Behandlung wie verordnet zu Ende führen.","Bei längerer Anwendung, vor allem bei Darmgeschwüren, Nierenfunktion und Gehör kontrollieren lassen.","Schweren, anhaltenden oder blutigen Durchfall ärztlich melden."],"darreichung":["Kapseln"]},"paroxetin":{"wirkmechanismus":"Hellt die Stimmung auf und vermindert Angst und Zwänge, indem es die Menge des Botenstoffs Serotonin zwischen den Nervenzellen erhöht. Paroxetin ist ein starker, selektiver Hemmer des Serotonin-Transporters und hat zudem eine schwache anticholinerge Wirkung. Es wird über CYP2D6 abgebaut und hemmt dieses Enzym gleichzeitig stark, was zu zahlreichen Wechselwirkungen führt. Wegen der relativ kurzen Halbwertszeit (etwa 1 Tag) treten beim Absetzen häufiger Absetzsymptome auf als bei anderen SSRI.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Sexuelle Funktionsstörungen (verminderte Libido, Ejakulations- und Orgasmusstörungen)"],"haeufig":["Erhöhte Cholesterinwerte, verminderter Appetit, Gewichtszunahme","Schläfrigkeit, Schlaflosigkeit, Unruhe, ungewöhnliche Träume","Konzentrationsstörungen, Schwindel, Zittern, Kopfschmerzen","Verschwommenes Sehen","Gähnen","Verstopfung, Durchfall, Erbrechen, Mundtrockenheit","Vermehrtes Schwitzen","Schwäche (Asthenie)"],"gelegentlich":["Ungewöhnliche Blutungen, vor allem der Haut und Schleimhäute (Blutergüsse)","Verwirrtheit, Halluzinationen","Extrapyramidale Störungen (Bewegungsstörungen)","Erweiterte Pupillen, Herzrasen","Blutdruckschwankungen, Blutdruckabfall beim Aufstehen","Hautausschlag, Juckreiz","Harnverhalt, Harninkontinenz"],"selten":["Hyponatriämie (Natriummangel)","Manie, Panikattacken, Angst, Depersonalisation","Akathisie (Bewegungsunruhe), Krampfanfälle, Restless-Legs-Syndrom","Langsamer Puls (Bradykardie)","Erhöhte Leberwerte","Erhöhtes Prolaktin, Milchfluss, Menstruationsstörungen","Gelenk- und Muskelschmerzen"],"sehrSelten":["Thrombozytopenie","Anaphylaxie, Angioödem","Inadäquate ADH-Sekretion (SIADH)","Serotoninsyndrom","Akutes Glaukom","Magen-Darm-Blutungen; Leberentzündung, Gelbsucht, Leberversagen","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse), Lichtempfindlichkeit","Priapismus (Dauererektion), Wassereinlagerungen"],"unbekannt":["Suizidgedanken und suizidales Verhalten","Aggressivität, Zähneknirschen (Bruxismus)","Ohrgeräusche (Tinnitus)","Mikroskopische Kolitis (chronischer wässriger Durchfall)","Nachblutungen nach der Geburt"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit: nach Einnahme im ersten Drittel ist das Risiko für Herzfehler etwa verdoppelt (rund 2 statt 1 von 100 Kindern), bei Einnahme bis zur Geburt drohen beim Neugeborenen Anpassungsstörungen und Lungenhochdruck (PPHN). Bei Kinderwunsch die Behandlung ärztlich überprüfen lassen, nicht eigenmächtig absetzen.","stillzeit":"Paroxetin geht nur in geringen Mengen in die Muttermilch über; eine Anwendung ist nach ärztlicher Abwägung möglich.","hinweise":["Einmal täglich morgens zum Frühstück einnehmen; Tablette nicht zerkauen.","Nicht abrupt absetzen: Absetzsymptome (Schwindel, Empfindungsstörungen, Schlafstörungen, Unruhe, Übelkeit) sind häufig – über mehrere Wochen ausschleichen.","Die Wirkung setzt nach 2–4 Wochen ein; zunehmende Unruhe oder Suizidgedanken zu Beginn sofort ärztlich melden.","Kann die Fahrtüchtigkeit beeinträchtigen; Alkohol meiden."],"darreichung":["Filmtabletten"]},"pasireotid":{"wirkmechanismus":"Senkt die Ausschüttung von ACTH und Wachstumshormon aus Tumoren der Hirnanhangsdrüse. Pasireotid ist ein Somatostatin-Analogon, das an mehrere Somatostatin-Rezeptoren bindet, besonders stark an SSTR5. Bei Morbus Cushing hemmt es die ACTH-Bildung des Hypophysentumors und senkt so das Kortisol; bei Akromegalie sinken Wachstumshormon und IGF-1. Durch Hemmung von Insulin und Darmhormonen (Inkretinen) steigt häufig der Blutzucker.","nebenwirkungen":{"sehrHaeufig":["Hyperglykämie (erhöhter Blutzucker), Diabetes mellitus","Erhöhter HbA1c-Wert","Durchfall, Übelkeit, Bauchschmerzen","Gallensteine","Reaktionen an der Injektionsstelle","Müdigkeit"],"haeufig":["Kopfschmerzen, Schwindel","Sinusbradykardie (langsamer Puls), QT-Verlängerung","Niedriger Blutdruck","Nebennierenrinden-Insuffizienz (Kortisolmangel)","Erbrechen, Appetitlosigkeit","Erhöhte Leber- und Bauchspeicheldrüsenwerte","Haarausfall, Juckreiz","Muskel- und Gelenkschmerzen"],"unbekannt":["Diabetische Ketoazidose"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit. Weil die Fruchtbarkeit nach Senkung des Kortisols zurückkehren kann, Verhütung besprechen.","stillzeit":"Stillen wird während der Behandlung nicht empfohlen.","hinweise":["Vor Beginn und regelmässig Blutzucker, HbA1c, EKG, Leberwerte und Gallenblase (Ultraschall) kontrollieren.","Zeichen eines Kortisolmangels (Schwäche, Müdigkeit, Übelkeit, Erbrechen, Schwindel) sofort melden.","Bei Diabetes kann eine Anpassung oder Intensivierung der Blutzuckertherapie nötig sein."],"darreichung":["Injektionslösung (Ampullen)","Pulver und Lösungsmittel zur Herstellung einer Depot-Injektionssuspension"]},"passionsblume":{"wirkmechanismus":"Wirkt mild beruhigend und entspannend. Passionsblumenkraut enthält vor allem Flavonoide (z. B. Vitexin und Isovitexin), deren Wirkung vermutlich über eine Beeinflussung des hemmenden GABA-Systems im Gehirn vermittelt wird. Der genaue Wirkmechanismus ist nicht geklärt; die Anwendung beruht überwiegend auf langjähriger Erfahrung.","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen (z. B. Hautausschlag, Gefässentzündung)","Übelkeit","Herzrasen (Tachykardie)"]},"schwangerschaft":"Mangels ausreichender Daten nicht empfohlen.","stillzeit":"Mangels ausreichender Daten nicht empfohlen.","hinweise":["Wenn die Beschwerden länger als 2 Wochen anhalten oder sich verschlimmern, ärztlichen Rat einholen.","Kann die Reaktionsfähigkeit beeinträchtigen; besonders zusammen mit Alkohol Vorsicht beim Autofahren."],"darreichung":["Tabletten","Dragées"]},"patiromer":{"wirkmechanismus":"Bindet Kalium im Darm, das dann mit dem Stuhl ausgeschieden wird, statt ins Blut zu gelangen. Patiromer ist ein nicht resorbierbares Polymer, das Kalium-Ionen im Austausch gegen Calcium bindet, vor allem im Dickdarm, wo die Kaliumkonzentration am höchsten ist. Dadurch sinkt das Kalium im Blut; die Wirkung setzt erst nach einigen Stunden ein, weshalb Patiromer nicht zur Notfallbehandlung geeignet ist.","nebenwirkungen":{"haeufig":["Verstopfung","Durchfall","Bauchschmerzen, Blähungen","Hypomagnesiämie (Magnesiummangel)"],"gelegentlich":["Übelkeit, Erbrechen"]},"schwangerschaft":"Keine Daten beim Menschen; Patiromer wird nicht ins Blut aufgenommen. Vorsichtshalber während der Schwangerschaft möglichst vermeiden.","stillzeit":"Da Patiromer nicht ins Blut aufgenommen wird, sind keine Auswirkungen auf den Säugling zu erwarten; Anwendung nach ärztlicher Abwägung.","hinweise":["Pulver in Wasser einrühren und zu einer Mahlzeit trinken; nicht trocken einnehmen.","Andere Arzneimittel mindestens 3 Stunden vorher oder nachher einnehmen.","Kalium und Magnesium regelmässig kontrollieren lassen."],"darreichung":["Pulver zur Herstellung einer Suspension zum Einnehmen"]},"patisiran":{"wirkmechanismus":"Schaltet in der Leber gezielt die Bauanleitung für das Eiweiss Transthyretin aus, sodass weniger davon gebildet wird und sich weniger Amyloid in Nerven und Organen ablagert. Patisiran ist eine doppelsträngige kleine interferierende RNA (siRNA), die in Lipid-Nanopartikel verpackt ist und so in die Leberzellen gelangt. Dort führt sie über RNA-Interferenz zum Abbau der Boten-RNA von normalem und mutiertem Transthyretin. Der Transthyretin-Spiegel im Blut sinkt um rund 80 %; weil Transthyretin Vitamin A transportiert, sinkt auch der Vitamin-A-Spiegel im Blut.","nebenwirkungen":{"sehrHaeufig":["Infusionsbedingte Reaktionen (z. B. Rötung, Rücken-, Bauch- oder Gelenkschmerzen, Atemnot, Kopfschmerzen)","Wassereinlagerungen in Beinen und Füssen (periphere Ödeme)"],"haeufig":["Bronchitis, Nasennebenhöhlenentzündung, Schnupfen","Drehschwindel (Vertigo)","Atemnot (Dyspnoe)","Verdauungsbeschwerden (Dyspepsie)","Hautrötung (Erythem)","Gelenkschmerzen, Muskelkrämpfe"],"gelegentlich":["Austreten der Infusion ins umliegende Gewebe (Extravasation)"]},"schwangerschaft":"Nicht empfohlen. Sowohl ein zu tiefer als auch ein zu hoher Vitamin-A-Spiegel kann dem ungeborenen Kind schaden; vor Behandlungsbeginn Schwangerschaft ausschliessen.","stillzeit":"Nicht bekannt, ob Patisiran in die Muttermilch übergeht; Stillen nur nach ärztlicher Abwägung.","hinweise":["Infusion alle 3 Wochen in Spital oder Praxis, jeweils nach einer Vorbehandlung gegen Infusionsreaktionen.","Täglich Vitamin A in der empfohlenen Menge ergänzen (etwa 2500 IE).","Augenbeschwerden wie Nachtblindheit oder trockene Augen ärztlich melden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"pazopanib":{"wirkmechanismus":"Hemmt die Bildung neuer Blutgefässe, die einen Tumor mit Nährstoffen versorgen. Pazopanib blockiert mehrere Rezeptor-Tyrosinkinasen: die VEGF-Rezeptoren 1–3, die PDGF-Rezeptoren α und β sowie KIT. Dadurch werden Gefässneubildung (Angiogenese) und Tumorwachstum gebremst.","nebenwirkungen":{"sehrHaeufig":["Durchfall, Übelkeit, Erbrechen, Bauchschmerzen","Bluthochdruck","Veränderung der Haarfarbe (Aufhellung)","Appetitverlust, Geschmacksstörungen, Gewichtsabnahme","Müdigkeit","Erhöhte Leberwerte (ALT, AST)"],"haeufig":["Kopfschmerzen, Schwindel, Kribbeln (Parästhesien)","Hand-Fuss-Syndrom, Haarausfall, Hautausschlag, Aufhellung der Haut","Hypothyreose (Schilddrüsenunterfunktion)","Mangel an Blutplättchen und weissen Blutkörperchen","Nasenbluten, Bluthusten, Heiserkeit","Erhöhtes Bilirubin, Eiweiss im Urin (Proteinurie)","Abnahme der Herzpumpfunktion, Bradykardie (langsamer Puls)","Venöse Thromboembolien (z. B. Lungenembolie)"],"gelegentlich":["Herzinfarkt, Schlaganfall, transitorische ischämische Attacke (TIA)","QT-Verlängerung","Hirnblutung, Magen-Darm-Blutung","Magen-Darm-Durchbruch (Perforation), Fisteln","Pankreatitis (Bauchspeicheldrüsenentzündung)","Pneumothorax (Luft im Brustfellraum, v. a. bei Lungenmetastasen)"],"unbekannt":["Schwere Leberschäden bis Leberversagen","Torsade de pointes (lebensbedrohliche Herzrhythmusstörung)","Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Thrombotische Mikroangiopathie","Interstitielle Lungenerkrankung, Pneumonitis","Aneurysmen und Gefässwandeinrisse (Dissektionen)","Tumorlyse-Syndrom"]},"schwangerschaft":"Kann das ungeborene Kind schädigen; nur bei zwingender Notwendigkeit. Frauen müssen während der Behandlung und mindestens 2 Wochen danach zuverlässig verhüten; Männer sollen in dieser Zeit Kondome verwenden.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Nüchtern einnehmen: mindestens 1 Stunde vor oder 2 Stunden nach einer Mahlzeit; Tabletten nicht zerkleinern (Essen und Zerkleinern erhöhen die Aufnahme stark).","Keine Grapefruit, kein Johanniskraut; säurehemmende Mittel nur nach Rücksprache.","Leberwerte werden besonders in den ersten Monaten engmaschig kontrolliert; Gelbsucht, dunklen Urin oder Oberbauchschmerzen sofort melden.","Blutdruck regelmässig messen."],"darreichung":["Filmtabletten"]},"pegaspargase":{"wirkmechanismus":"Baut die Aminosäure Asparagin im Blut ab, die Leukämiezellen zum Überleben brauchen. Pegaspargase ist das Enzym L-Asparaginase aus E. coli, gekoppelt an Polyethylenglykol (PEG); es spaltet Asparagin in Aspartat und Ammoniak. Leukämische Lymphoblasten können Asparagin kaum selbst herstellen, sie können ohne Nachschub keine Eiweisse mehr bilden und sterben ab. Die PEG-Kopplung verlängert die Wirkdauer und vermindert die Bildung von Antikörpern gegen das Enzym.","nebenwirkungen":{"sehrHaeufig":["Allergische Reaktionen (Nesselsucht, Anaphylaxie)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Erhöhter Blutzucker (Hyperglykämie)","Übelkeit, Durchfall, Bauchschmerzen, Appetitlosigkeit","Erhöhte Leberwerte und erhöhtes Bilirubin","Gerinnungsstörungen (Mangel an Fibrinogen und Antithrombin, verlängerte Gerinnungszeit)"],"haeufig":["Thrombosen und Embolien","Infektionen, Sepsis (Blutvergiftung)","Febrile Neutropenie (Fieber bei Mangel an weissen Blutkörperchen), Anämie","Krampfanfälle, periphere Neuropathie (Nervenschädigung), Ohnmacht","Erbrechen, Mundschleimhautentzündung","Erhöhte Blutfette, Kaliummangel","Leberschädigung, Fettleber"],"selten":["Posteriores reversibles Enzephalopathie-Syndrom (PRES: Kopfschmerzen, Krampfanfälle, Sehstörungen)"],"unbekannt":["Leberversagen, Gelbsucht","Hyperammonämie (erhöhtes Ammoniak) mit Bewusstseinsstörung","Diabetische Ketoazidose","Hirnblutung, Schlaganfall","Nekrotisierende Pankreatitis, Pankreaspseudozyste","Toxische epidermale Nekrolyse (schwere Hautreaktion)","Akutes Nierenversagen","Osteonekrose (Absterben von Knochengewebe)"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit (im Tierversuch schädlich, kaum Erfahrungen). Frauen müssen bis mindestens 6 Monate nach der letzten Dosis zuverlässig nichthormonal verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Die Gabe erfolgt im Spital; nach jeder Gabe wird auf allergische Reaktionen überwacht.","Bei starken Bauchschmerzen (auch in den Rücken ausstrahlend), Gelbfärbung der Haut, Beinschwellung, starken Kopfschmerzen oder Blutungen sofort ärztliche Hilfe holen.","Regelmässige Kontrollen von Blutzucker, Leberwerten, Gerinnung und Bauchspeicheldrüsenwerten."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"pegcetacoplan":{"wirkmechanismus":"Hemmt das Komplementsystem bereits auf einer frühen Stufe und schützt so die roten Blutkörperchen, die bei PNH ungeschützt angegriffen werden. Pegcetacoplan ist ein an Polyethylenglykol gekoppeltes zyklisches Peptid, das an das Komplementprotein C3 und dessen Spaltprodukt C3b bindet. Damit werden sowohl die Zerstörung der roten Blutkörperchen in den Gefässen (über den Membranangriffskomplex) als auch ihr Abbau in Leber und Milz nach Markierung mit C3b (extravaskuläre Hämolyse) verhindert. Letztere wird von C5-Hemmern nicht erfasst.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Injektionsstelle (Rötung, Schwellung, Juckreiz, Bluterguss, Schmerzen)","Infektionen, u. a. der Atemwege","Durchfall","Bauchschmerzen","Müdigkeit"],"haeufig":["Durchbruchhämolyse (erneuter Blutzerfall)","Kopfschmerzen, Schwindel","Fieber","Übelkeit","Hautausschlag","Gelenk-, Rücken- und Muskelschmerzen"],"unbekannt":["Schwere Infektionen mit bekapselten Bakterien (Meningokokken, Pneumokokken, Haemophilus)"]},"schwangerschaft":"Nicht empfohlen. Frauen im gebärfähigen Alter sollen während der Behandlung und mindestens 8 Wochen nach der letzten Dosis zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Wird zweimal pro Woche mit einer Pumpe unter die Haut infundiert – keine Dosis auslassen.","Patientenkarte mitführen. Bei Fieber, starken Kopfschmerzen, Nackensteifigkeit oder Hautflecken sofort den Notfall aufsuchen.","Vor Gerinnungstests auf die Behandlung hinweisen (falsch verlängerte aPTT)."],"darreichung":["Infusionslösung zur subkutanen Anwendung"]},"pegfilgrastim":{"wirkmechanismus":"Regt das Knochenmark an, mehr infektabwehrende weisse Blutkörperchen (neutrophile Granulozyten) zu bilden. Pegfilgrastim ist Filgrastim (gentechnisch hergestellter humaner G-CSF), an das ein Polyethylenglykol-Molekül gekoppelt ist. Dadurch wird es kaum über die Niere ausgeschieden, sondern vor allem über die Neutrophilen selbst abgebaut und wirkt viel länger – eine Injektion pro Chemotherapie-Zyklus genügt.","nebenwirkungen":{"sehrHaeufig":["Knochenschmerzen","Kopfschmerzen","Übelkeit"],"haeufig":["Thrombozytopenie (Mangel an Blutplättchen)","Leukozytose (stark erhöhte weisse Blutkörperchen)","Muskel- und Gelenkschmerzen, Rücken- und Gliederschmerzen","Schmerzen an der Einstichstelle","Brustschmerzen (nicht vom Herzen)"],"gelegentlich":["Milzvergrösserung und Milzriss (Milzruptur)","Sichelzellkrisen","Überempfindlichkeitsreaktionen bis Anaphylaxie (schwere allergische Reaktion)","Kapillarlecksyndrom","ARDS (akutes Lungenversagen), Lungeninfiltrate, Bluthusten","Sweet-Syndrom und Hautvaskulitis","Glomerulonephritis (Nierenentzündung)","Erhöhte Harnsäure, LDH und alkalische Phosphatase"],"selten":["Aortitis (Entzündung der Hauptschlagader)","Lungenblutung","Stevens-Johnson-Syndrom (schwere Hautreaktion)"],"unbekannt":["Myelodysplastisches Syndrom oder akute myeloische Leukämie (bei Brust- und Lungenkrebspatienten beschrieben)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; während der Schwangerschaft nicht empfohlen, ausser nach strenger ärztlicher Abwägung.","stillzeit":"Ein Übergang in die Muttermilch ist nicht auszuschliessen; Entscheid über Stillen oder Therapie ärztlich abwägen.","hinweise":["Bei Schmerzen im linken Oberbauch oder in der linken Schulterspitze sofort ärztliche Hilfe holen (möglicher Milzriss).","Bei Atemnot, Husten mit Fieber oder plötzlichen Schwellungen mit Schwindel umgehend ärztlich abklären lassen.","Knochenschmerzen lassen sich meist mit einfachen Schmerzmitteln wie Paracetamol lindern.","Im Kühlschrank lagern, nicht einfrieren."],"darreichung":["Injektionslösung (Fertigspritze)"]},"peginterferon-alfa-2a":{"wirkmechanismus":"Stärkt die körpereigene Abwehr gegen Viren. Peginterferon alfa-2a ist Interferon alfa-2a mit einem grossen, gebundenen Polyethylenglykol-Molekül; dadurch wird es langsamer abgebaut und muss nur einmal pro Woche gespritzt werden. Es bindet an den Typ-I-Interferonrezeptor und schaltet über den JAK-STAT-Signalweg antivirale Gene ein, die die Vermehrung von Hepatitis-B- und -C-Viren hemmen. Zusätzlich fördert es die zelluläre Immunantwort gegen infizierte Leberzellen.","nebenwirkungen":{"sehrHaeufig":["Grippeähnliche Beschwerden: Fieber, Schüttelfrost, Müdigkeit, Muskel- und Gelenkschmerzen","Kopfschmerzen, Schwindel, Konzentrationsstörungen","Depression, Angst, Reizbarkeit, Schlaflosigkeit","Appetitlosigkeit, Übelkeit, Durchfall, Bauchschmerzen","Haarausfall, Juckreiz, trockene Haut, Hautentzündung","Atemnot, Husten","Reaktionen an der Injektionsstelle"],"haeufig":["Anämie (Blutarmut), Thrombozytopenie (Mangel an Blutplättchen), Lymphknotenschwellung","Schilddrüsenunter- oder -überfunktion","Gedächtnisstörungen, Stimmungsschwankungen, Aggressivität","Verschwommenes Sehen, Augenschmerzen","Herzrasen, Herzklopfen, Hitzewallungen","Nasenbluten, Erbrechen, Verdauungsbeschwerden, Mundgeschwüre","Gewichtsabnahme"],"gelegentlich":["Suizidgedanken, Halluzinationen","Diabetes mellitus","Netzhautblutung","Periphere Neuropathie (Nervenschädigung)","Bluthochdruck","Magen-Darm-Blutung","Leberfunktionsstörung","Lungenentzündung"],"selten":["Suizid, Psychosen","Krampfanfälle, Koma, Hirnblutung","Herzinfarkt, Herzschwäche, Herzrhythmusstörungen, Herzbeutelentzündung","Interstitielle Lungenentzündung, Lungenembolie","Leberversagen, Pankreatitis (Bauchspeicheldrüsenentzündung)","Sarkoidose, Lupus erythematodes, rheumatoide Arthritis","Anaphylaxie (schwere allergische Reaktion)","Schädigung von Sehnerv oder Netzhaut"],"sehrSelten":["Aplastische Anämie, thrombozytopenische Purpura","Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse (schwere Hautreaktionen)","Angioödem"],"unbekannt":["Erythroblastopenie (Ausfall der roten Blutbildung)","Abstossung von Leber- oder Nierentransplantaten","Pulmonale arterielle Hypertonie (Lungenhochdruck)","Manie, bipolare Störung","Netzhautablösung, Vogt-Koyanagi-Harada-Syndrom","Rhabdomyolyse (Muskelzerfall)"]},"schwangerschaft":"Nur anwenden, wenn der Nutzen das Risiko für das Kind rechtfertigt. In Kombination mit Ribavirin kontraindiziert; Frauen müssen dann bis 4 Monate, Partnerinnen behandelter Männer bis 7 Monate nach Behandlungsende zuverlässig verhüten.","stillzeit":"Nicht bekannt, ob der Wirkstoff in die Muttermilch übergeht; während der Behandlung nicht stillen.","hinweise":["Regelmässige Kontrollen von Blutbild, Leber- und Schilddrüsenwerten sowie Blutzucker.","Grippeähnliche Beschwerden lassen sich mit Injektion am Abend und einem ärztlich empfohlenen Fiebermittel lindern.","Bei Stimmungsveränderungen, Suizidgedanken oder Sehstörungen sofort ärztliche Hilfe holen.","Alkohol meiden, da er die Leber zusätzlich belastet."],"darreichung":["Injektionslösung im Fertigpen","Injektionslösung in Fertigspritze"]},"peginterferon-beta-1a":{"wirkmechanismus":"Dämpft die fehlgeleitete Entzündung, mit der das Immunsystem bei Multipler Sklerose die Nervenhüllen angreift. Peginterferon beta-1a ist Interferon beta-1a mit einem gebundenen Polyethylenglykol-Molekül, das den Abbau verlangsamt, sodass eine Injektion alle zwei Wochen genügt. Es bindet an den Typ-I-Interferonrezeptor und verschiebt das Gleichgewicht von entzündungsfördernden zu entzündungshemmenden Botenstoffen; zudem vermindert es die Einwanderung von Entzündungszellen ins Gehirn. Der genaue Wirkmechanismus bei MS ist nicht vollständig geklärt.","nebenwirkungen":{"sehrHaeufig":["Grippeähnliche Beschwerden: Fieber, Schüttelfrost, Schwäche","Kopfschmerzen","Muskel- und Gelenkschmerzen","Rötung, Schmerz und Juckreiz an der Injektionsstelle"],"haeufig":["Depression","Übelkeit, Erbrechen","Haarausfall, Juckreiz","Schwellung, Wärme, Bluterguss oder Entzündung an der Injektionsstelle","Erhöhte Leberwerte (ALT, AST, GGT)","Verminderte weisse Blutkörperchen und vermindertes Hämoglobin","Erhöhte Körpertemperatur, Schmerzen"],"gelegentlich":["Thrombozytopenie (Mangel an Blutplättchen)","Krampfanfälle","Nesselsucht","Überempfindlichkeitsreaktionen","Suizidgedanken"],"selten":["Thrombotische Mikroangiopathie (Gerinnsel in kleinen Gefässen mit Blutzerfall)","Nephrotisches Syndrom","Nekrose (Gewebeuntergang) an der Injektionsstelle"],"unbekannt":["Pulmonale arterielle Hypertonie (Lungenhochdruck)","Anaphylaxie (schwere allergische Reaktion)","Schwere Leberschädigung, Autoimmunhepatitis"]},"schwangerschaft":"Kann nach ärztlicher Abwägung angewendet werden, wenn es klinisch nötig ist; Daten zu Interferon beta zeigen kein erhöhtes Risiko für schwere Fehlbildungen.","stillzeit":"Geht kaum in die Muttermilch über; Stillen ist nach ärztlicher Abwägung möglich.","hinweise":["Injektionsstelle bei jeder Gabe wechseln; Hautveränderungen ärztlich zeigen.","Grippeähnliche Beschwerden lassen sich mit einem ärztlich empfohlenen Fiebermittel vor und nach der Injektion lindern.","Regelmässige Kontrollen von Blutbild und Leberwerten.","Bei Niedergeschlagenheit oder Suizidgedanken sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung im Fertigpen","Injektionslösung in Fertigspritze"]},"pegunigalsidase-alfa":{"wirkmechanismus":"Ersetzt ein fehlendes Enzym, damit sich ein Fettstoff nicht mehr in Gefässen, Nieren, Herz und Nerven ablagert. Pegunigalsidase alfa ist eine in Pflanzenzellen (Tabakzellkultur) hergestellte Alpha-Galactosidase A, deren zwei Untereinheiten über Polyethylenglykol (PEG) vernetzt sind. Dadurch ist sie stabiler und bleibt deutlich länger im Blut als bisherige Enzympräparate. In den Lysosomen spaltet sie Globotriaosylceramid (Gb3) und senkt Lyso-Gb3 im Blut.","nebenwirkungen":{"sehrHaeufig":["Infusionsbedingte Reaktionen"],"haeufig":["Überempfindlichkeitsreaktionen","Kopfschmerzen, Schwindel","Übelkeit, Bauchschmerzen, Durchfall","Juckreiz, Ausschlag","Schüttelfrost, Müdigkeit, Schwäche, Schmerzen","Gliederschmerzen"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Membranoproliferative Glomerulonephritis (Nierenentzündung)"]},"schwangerschaft":"Keine Erfahrungen beim Menschen. Nur anwenden, wenn eindeutig nötig.","stillzeit":"Nicht bekannt, ob Pegunigalsidase alfa in die Muttermilch übergeht. Entscheid über Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird alle 2 Wochen als Infusion in eine Vene gegeben; nach Schulung ist eine Heiminfusion möglich.","Atemnot, Schwellungen oder Ausschlag während oder nach der Infusion sofort melden.","Nierenwerte, Urin und Antikörper werden regelmässig kontrolliert."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"pegvisomant":{"wirkmechanismus":"Blockiert die Wirkung des überschüssigen Wachstumshormons im Körper. Pegvisomant ist ein gentechnisch verändertes, pegyliertes Analogon des Wachstumshormons, das an den Wachstumshormon-Rezeptor bindet, ihn aber nicht aktiviert. Dadurch sinkt die Bildung von IGF-1, das die meisten Beschwerden der Akromegalie verursacht. Die Ausschüttung von Wachstumshormon und das Wachstum des Hypophysentumors werden nicht gehemmt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Durchfall","Gelenkschmerzen"],"haeufig":["Reaktionen an der Injektionsstelle, Lipohypertrophie (Fettgewebsverdickung)","Erhöhte Leberwerte","Übelkeit, Erbrechen, Verstopfung, Blähungen","Erhöhter oder erniedrigter Blutzucker, erhöhtes Cholesterin","Bluthochdruck","Schläfrigkeit, Schwindel, Zittern","Muskelschmerzen","Grippeähnliche Beschwerden, Müdigkeit, periphere Ödeme"],"gelegentlich":["Thrombozytopenie, Leukopenie (Mangel an Blutplättchen bzw. weissen Blutkörperchen)","Überempfindlichkeitsreaktionen","Panikattacken, Gedächtnisstörungen","Nesselsucht, Gesichtsschwellung","Eiweiss oder Blut im Urin"],"unbekannt":["Anaphylaxie, Angioödem, Kehlkopfkrampf (Laryngospasmus)"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit; die Erfahrungen sind sehr begrenzt.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Täglich unter die Haut spritzen; Einstichstellen wechseln.","Leberwerte vor Beginn und in den ersten 6 Monaten regelmässig kontrollieren.","Die Wirkung wird mit dem IGF-1-Wert überwacht; Wachstumshormon-Werte sind unter Pegvisomant nicht aussagekräftig.","Bei Diabetes den Blutzucker engmaschig kontrollieren."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"pelargonium-sidoides-wurzelextrakt":{"wirkmechanismus":"Unterstützt die körpereigene Abwehr bei Atemwegsinfekten. Der Extrakt EPs 7630 enthält unter anderem Polyphenole (Proanthocyanidine) und Cumarine. In Laborstudien hemmt er das Anheften bestimmter Viren und Bakterien an Schleimhautzellen, regt die Bildung von Abwehrstoffen wie Interferon an und steigert die Schlagfrequenz der Flimmerhärchen, was den Schleimabtransport fördert. Welche Mechanismen klinisch entscheidend sind, ist nicht abschliessend geklärt.","nebenwirkungen":{"gelegentlich":["Magen-Darm-Beschwerden (Magenschmerzen, Sodbrennen, Übelkeit, Durchfall)"],"selten":["Leichtes Zahnfleisch- oder Nasenbluten","Überempfindlichkeitsreaktionen der Haut (Ausschlag, Nesselsucht, Juckreiz)"],"sehrSelten":["Schwere Überempfindlichkeitsreaktionen mit Gesichtsschwellung, Atemnot und Blutdruckabfall"],"unbekannt":["Leberschädigung, erhöhte Leberwerte"]},"schwangerschaft":"Mangels ausreichender Daten vorsichtshalber nicht anwenden.","stillzeit":"Mangels ausreichender Daten vorsichtshalber nicht anwenden.","hinweise":["Bessern sich die Beschwerden nach einer Woche nicht oder treten hohes Fieber, Atemnot oder blutiger Auswurf auf, ärztlich abklären.","Bei Zeichen einer Leberschädigung (Gelbfärbung von Haut oder Augen, dunkler Urin, Oberbauchschmerzen) sofort absetzen.","Die Tropfen enthalten Alkohol."],"darreichung":["Tropfen (Lösung zum Einnehmen)","Filmtabletten","Sirup"]},"pembrolizumab":{"wirkmechanismus":"Löst eine Bremse des Immunsystems, sodass körpereigene Abwehrzellen Krebszellen wieder erkennen und angreifen. Pembrolizumab ist ein humanisierter IgG4-Antikörper gegen den Rezeptor PD-1 auf T-Lymphozyten. Er verhindert, dass die vom Tumor gebildeten Liganden PD-L1 und PD-L2 an PD-1 binden und die T-Zellen abschalten. Weil diese Immunbremse auch gesundes Gewebe schützt, können immunvermittelte Entzündungen in praktisch allen Organen auftreten.","nebenwirkungen":{"sehrHaeufig":["Hypothyreose (Schilddrüsenunterfunktion)","Appetitlosigkeit","Kopfschmerzen","Husten, Atemnot","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Verstopfung","Juckreiz, Hautausschlag","Muskel-, Knochen- und Gelenkschmerzen","Müdigkeit, Schwäche, Ödeme, Fieber, Anämie"],"haeufig":["Hyperthyreose (Schilddrüsenüberfunktion)","Pneumonitis (Lungenentzündung durch Immunreaktion), Pneumonie","Kolitis (Dickdarmentzündung), Mundtrockenheit","Hepatitis, erhöhte Leberwerte","Infusionsreaktionen","Schwere Hautreaktionen, Vitiligo (Weissfleckenkrankheit), trockene Haut, Haarausfall","Herzrhythmusstörungen (inkl. Vorhofflimmern), Bluthochdruck","Hyponatriämie, Hypokaliämie, Thrombozytopenie, Neutropenie, Myositis, Arthritis"],"gelegentlich":["Nebenniereninsuffizienz, Hypophysitis (Hirnanhangdrüsenentzündung), Thyreoiditis","Typ-1-Diabetes","Nephritis (Nierenentzündung)","Pankreatitis, Magen-Darm-Geschwüre","Uveitis (Augenentzündung)","Perikarderguss, Perikarditis","Psoriasis, lichenoide Hautveränderungen"],"selten":["Myokarditis (Herzmuskelentzündung)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Guillain-Barré-Syndrom, Myasthenie-Syndrom, Enzephalitis, Myelitis","Immunthrombozytopenie, hämolytische Anämie, hämophagozytische Lymphohistiozytose (HLH)","Sklerosierende Cholangitis, Dünndarmperforation","Sarkoidose, Vaskulitis"],"unbekannt":["Abstossung transplantierter Organe"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Indikation (der Antikörper gelangt zum Kind). Frauen müssen während und mindestens 4 Monate nach der letzten Dosis sicher verhüten.","stillzeit":"Unbekannt, ob Pembrolizumab in die Muttermilch übergeht; ein Risiko für das Kind ist nicht auszuschliessen – nach ärztlicher Abwägung entscheiden.","hinweise":["Neue oder stärkere Beschwerden – Durchfall, Bauchschmerzen, Husten, Atemnot, Hautausschlag, Gelbsucht, starke Müdigkeit, Kopfschmerzen, Sehstörungen – sofort melden, auch Wochen bis Monate nach der letzten Gabe.","Die Patientenkarte immer mitführen und bei jedem Arztbesuch zeigen.","Schilddrüsen-, Leber- und Nierenwerte sowie der Blutzucker werden regelmässig kontrolliert."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"pemetrexed":{"wirkmechanismus":"Hemmt die Teilung von Krebszellen, indem es den Folsäure-Stoffwechsel blockiert. Pemetrexed hemmt als Mehrfach-Folsäureantagonist die Enzyme Thymidylat-Synthase, Dihydrofolat-Reduktase und Glycinamid-Ribonukleotid-Formyltransferase, die für die Bildung von DNA-Bausteinen (Thymidin und Purine) nötig sind. In der Zelle wird es zu Polyglutamaten umgebaut, die länger in den Tumorzellen verbleiben und stärker wirken. Die vorbeugende Gabe von Folsäure und Vitamin B12 schützt gesunde Zellen und senkt die Toxizität.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Leukopenie, Anämie (Blutbildveränderungen)","Übelkeit, Erbrechen, Appetitlosigkeit","Entzündung von Mund- und Rachenschleimhaut","Durchfall","Müdigkeit","Hautausschlag, Schuppung der Haut"],"haeufig":["Thrombozytopenie","Infektionen, Fieber bei Neutropenie","Flüssigkeitsmangel (Dehydratation)","Verstopfung, Bauchschmerzen, Verdauungsbeschwerden","Geschmacksstörung, Nervenschädigung mit Kribbeln (sensorische Neuropathie)","Bindehautentzündung, trockene oder tränende Augen","Erhöhte Leberwerte","Haarausfall, Juckreiz","Nierenfunktionsstörung bis Nierenversagen"],"gelegentlich":["Sepsis (Blutvergiftung)","Herzinfarkt, Angina pectoris, Schlaganfall, Herzrhythmusstörungen","Lungenembolie","Interstitielle Pneumonitis (Lungenentzündung)","Magen-Darm-Blutungen, Darmdurchbruch, Kolitis","Panzytopenie (Mangel aller Blutzellen)"],"selten":["Autoimmunhämolytische Anämie (Blutzerfall)","Anaphylaktischer Schock","Hepatitis (Leberentzündung)","Strahlenreaktion in früher bestrahlter Haut (Radiation recall)"],"sehrSelten":["Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse","Blasenbildende Hauterkrankungen (z. B. Pemphigoid)"],"unbekannt":["Nephrogener Diabetes insipidus","Schädigung der Nierenkanälchen (Tubulusnekrose)"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit (fruchtschädigend). Frauen und Männer müssen während und einige Monate nach der Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Vorbehandlung zwingend: Folsäure täglich ab etwa 1 Woche vor der ersten Infusion, Vitamin-B12-Spritzen alle 9 Wochen und Dexamethason rund um jede Infusion – senkt schwere Blutbild- und Hautreaktionen.","Schmerzmittel wie Ibuprofen nur nach Rücksprache mit dem Behandlungsteam einnehmen.","Regelmässige Kontrollen von Blutbild und Nierenwerten; Fieber, Atemnot oder starken Durchfall sofort melden."],"darreichung":["Pulver zur Herstellung eines Infusionslösungskonzentrats","Konzentrat zur Herstellung einer Infusionslösung"]},"pemigatinib":{"wirkmechanismus":"Bremst das Wachstum von Krebszellen, die durch ein verändertes Wachstumssignal angetrieben werden. Pemigatinib hemmt selektiv die Tyrosinkinasen der Fibroblasten-Wachstumsfaktor-Rezeptoren FGFR1, FGFR2 und FGFR3. Bei Tumoren mit FGFR2-Fusionen oder -Umlagerungen, die den Rezeptor dauerhaft aktivieren, werden so Zellteilung und Überleben der Krebszellen gehemmt. Die FGFR-Hemmung beeinflusst auch den Phosphathaushalt, deshalb steigt häufig das Phosphat im Blut.","nebenwirkungen":{"sehrHaeufig":["Hyperphosphatämie (erhöhtes Phosphat), aber auch Hypophosphatämie (zu tiefes Phosphat)","Haarausfall","Durchfall, Übelkeit, Verstopfung, Erbrechen, Bauchschmerzen","Stomatitis (Entzündung der Mundschleimhaut), Mundtrockenheit","Nagelveränderungen (Nagelablösung, Nagelbettentzündung)","Geschmacksstörungen, Appetitverlust","Trockene Augen, trockene Haut, Hand-Fuss-Syndrom","Müdigkeit, Gelenk- und Rückenschmerzen"],"haeufig":["Seröse Netzhautablösung (Flüssigkeitsansammlung unter der Netzhaut)"]},"schwangerschaft":"Kann das ungeborene Kind schädigen; nicht anwenden, ausser der Zustand erfordert es zwingend. Frauen und Männer müssen während der Behandlung und bis 1 Woche nach der letzten Dosis zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 1 Woche nach der letzten Dosis nicht stillen.","hinweise":["Einnahme meist in Zyklen (14 Tage Einnahme, 7 Tage Pause), täglich etwa zur gleichen Zeit, unzerkaut, mit oder ohne Mahlzeit.","Keine Grapefruit und kein Johanniskraut.","Phosphat im Blut wird regelmässig kontrolliert; phosphatreiche Ernährung einschränken.","Augenärztliche Kontrollen vor Beginn und regelmässig während der Behandlung; Sehstörungen sofort melden."],"darreichung":["Tabletten"]},"penciclovir":{"wirkmechanismus":"Hemmt die Vermehrung von Herpesviren in den befallenen Hautzellen. Penciclovir wird nur in virusinfizierten Zellen durch die virale Thymidinkinase und anschliessend durch zelleigene Enzyme zu Penciclovir-Triphosphat umgewandelt. Dieses hemmt die virale DNA-Polymerase und damit die Bildung neuer Viren; gesunde Zellen bleiben weitgehend unbeeinflusst. Penciclovir ist auch der Wirkmetabolit von Famciclovir-Tabletten.","nebenwirkungen":{"haeufig":["Reaktionen an der Anwendungsstelle wie Brennen, Stechen, Schmerzen oder Taubheitsgefühl"],"unbekannt":["Allergische Reaktionen (Hautausschlag, Juckreiz, Nesselsucht, Schwellung)","Kontaktdermatitis, Rötung"]},"schwangerschaft":"Nach Auftragen auf die Lippe gelangt nur sehr wenig Penciclovir ins Blut; trotzdem nur nach ärztlicher Rücksprache anwenden.","stillzeit":"Nur nach ärztlicher Rücksprache; Kontakt des Kindes mit der behandelten Stelle vermeiden.","hinweise":["So früh wie möglich beginnen, schon beim ersten Kribbeln oder Spannungsgefühl.","Vor und nach dem Auftragen Hände waschen; Bläschen nicht aufkratzen und die Creme nicht mit anderen teilen.","Nicht auf Schleimhäute im Mund oder in die Nähe der Augen auftragen.","Ansteckend: solange Bläschen bestehen, auf Küssen und Oralverkehr verzichten."],"darreichung":["Creme"]},"penicillamin":{"wirkmechanismus":"Bindet Schwermetalle wie Kupfer und Blei und fördert ihre Ausscheidung mit dem Urin. Penicillamin bildet als Chelatbildner lösliche Komplexe mit Kupfer und anderen Metallen. Bei Cystinurie entsteht mit Cystin ein besser lösliches Disulfid, sodass sich keine Steine bilden. Bei rheumatoider Arthritis wirkt es über einen nicht genau geklärten immunmodulierenden Mechanismus langsam, mit Wirkungseintritt nach Wochen bis Monaten.","nebenwirkungen":{"sehrHaeufig":["Geschmacksstörungen","Appetitlosigkeit, Übelkeit","Proteinurie (Eiweiss im Urin)"],"haeufig":["Hautausschlag, Juckreiz","Thrombozytopenie und Leukopenie","Erbrechen, Durchfall, Mundschleimhautentzündung"],"selten":["Agranulozytose, aplastische Anämie","Myasthenie-Syndrom (Muskelschwäche, Doppelbilder)","Nephrotisches Syndrom","Pemphigus (blasenbildende Hauterkrankung)"],"unbekannt":["Lupus-ähnliches Syndrom, Goodpasture-Syndrom (Lungen-Nieren-Erkrankung)","Bronchiolitis obliterans (Entzündung der kleinen Atemwege)","Leberschäden mit Gallenstau (Cholestase)","Hautveränderungen bei Langzeitbehandlung (z. B. brüchige Haut, Elastose), verzögerte Wundheilung","Haarausfall","Vitamin-B6-Mangel"]},"schwangerschaft":"Bei rheumatoider Arthritis kontraindiziert (fruchtschädigend, z. B. Bindegewebsschäden). Bei Morbus Wilson und Cystinurie wird die Behandlung in möglichst niedriger Dosis unter ärztlicher Kontrolle fortgesetzt.","stillzeit":"Nicht empfohlen; bei Morbus Wilson nur nach strenger ärztlicher Abwägung.","hinweise":["Nüchtern einnehmen: mindestens 1 Stunde vor oder 2 Stunden nach einer Mahlzeit; mindestens 2 Stunden Abstand zu Eisen, Antazida, Zink und Milchprodukten.","Blutbild und Urin müssen regelmässig kontrolliert werden.","Fieber, Halsschmerzen, Blutergüsse, Blutungen, Hautausschlag oder Muskelschwäche sofort melden.","Bei Morbus Wilson die Behandlung lebenslang und nicht eigenmächtig unterbrechen."],"darreichung":["Filmtabletten"]},"pentamidin":{"wirkmechanismus":"Tötet bestimmte einzellige Krankheitserreger ab. Pentamidin stört die Bildung von Erbsubstanz und Eiweissen der Erreger, unter anderem durch Bindung an die DNA – besonders an die Mitochondrien-DNA (Kinetoplasten) – und durch Hemmung von Enzymen wie der Topoisomerase. Der genaue Mechanismus ist nicht vollständig geklärt. Bei Inhalation gelangt der Wirkstoff gezielt in die Lunge und nur wenig in den Blutkreislauf.","nebenwirkungen":{"sehrHaeufig":["Anstieg der Nierenwerte bis akutes Nierenversagen","Reaktionen an der Injektionsstelle (Schmerz, Verhärtung, Abszess, Gewebeschaden bei Spritze in den Muskel)"],"haeufig":["Blutdruckabfall, Schwindel, Ohnmacht","Unterzuckerung (Hypoglykämie)","Verminderung von weissen Blutkörperchen und Blutplättchen, Blutarmut","Übelkeit, Erbrechen, Geschmacksstörungen","Erhöhte Leberwerte","Hautausschlag","Husten, Atemnot, Bronchospasmus (bei Inhalation)","Hypokalzämie (Calciummangel)"],"selten":["QT-Verlängerung"],"unbekannt":["Torsade de pointes (lebensbedrohliche Herzrhythmusstörung)","Bauchspeicheldrüsenentzündung (Pankreatitis)","Überzuckerung bis Diabetes mellitus","Hypomagnesiämie (Magnesiummangel)","Hyperkaliämie (erhöhtes Kalium)","Anaphylaxie","Stevens-Johnson-Syndrom"]},"schwangerschaft":"Nur bei zwingender Indikation, wenn der Nutzen für die Mutter das Risiko für das Kind überwiegt.","stillzeit":"Während der Behandlung nicht stillen, ausser es ist nach ärztlicher Abwägung unbedingt nötig.","hinweise":["Infusion oder Spritze im Liegen; Blutdruck, Blutzucker, Blutbild, Nieren- und Leberwerte, Elektrolyte und EKG werden überwacht.","Bei Inhalation kann vorher ein bronchienerweiterndes Spray gegen Husten und Atemnot nötig sein.","Zittern, Schwitzen oder Heisshunger (Zeichen einer Unterzuckerung) auch noch Tage nach der Behandlung sofort melden."],"darreichung":["Pulver zur Herstellung einer Injektions-, Infusions- oder Inhalationslösung"]},"pentavalenter-impfstoff-dtpa-ipv-hib":{"wirkmechanismus":"Regt das Immunsystem an, gleichzeitig Abwehrstoffe gegen fünf Krankheiten zu bilden. Der Impfstoff enthält unschädlich gemachte Gifte (Toxoide) der Diphtherie- und Tetanusbakterien, gereinigte Bestandteile des Keuchhustenerregers (azellulär), abgetötete Polioviren der Typen 1–3 und den an ein Trägereiweiss gekoppelten Kapselzucker von Haemophilus influenzae Typ b. Er enthält keine lebenden Erreger.","nebenwirkungen":{"sehrHaeufig":["Schmerzen, Rötung und Schwellung an der Einstichstelle","Fieber ab 38 °C","Reizbarkeit, Unruhe, ungewöhnliches Schreien","Schläfrigkeit","Appetitlosigkeit"],"haeufig":["Erbrechen, Durchfall","Fieber über 39,5 °C","Verhärtung oder grössere Schwellung (über 5 cm) an der Einstichstelle"],"gelegentlich":["Infekte der oberen Atemwege","Ausgedehnte Schwellung der ganzen Gliedmasse, v. a. nach Auffrischimpfungen","Müdigkeit"],"unbekannt":["Fieberkrämpfe und Krampfanfälle ohne Fieber","Kollaps oder schockähnlicher Zustand (hypoton-hyporesponsive Episode)","Atempausen (Apnoe) bei sehr unreif geborenen Säuglingen","Anaphylaxie (schwere allergische Reaktion), Angioödem","Thrombozytopenie (Mangel an Blutplättchen)","Lymphknotenschwellung","Hautausschlag, Nesselsucht"]},"schwangerschaft":"Nicht zutreffend – der Impfstoff ist nur für Säuglinge und Kleinkinder bestimmt.","stillzeit":"Nicht zutreffend – der Impfstoff ist nur für Säuglinge und Kleinkinder bestimmt.","hinweise":["In der Schweiz wird für die Basisimpfung meist der 6-fach-Impfstoff (zusätzlich Hepatitis B) verwendet; der 5-fach-Impfstoff z. B. für Nachholimpfungen.","Fieber und Reizbarkeit in den ersten 1–2 Tagen sind häufig; bei Fieberkrämpfen in der Vorgeschichte fiebersenkende Mittel nach ärztlichem Rat.","Eine starke Schwellung des ganzen Arms oder Beins nach Auffrischimpfungen bildet sich meist innert Tagen zurück, sollte aber ärztlich beurteilt werden."],"darreichung":["Pulver und Suspension zur Herstellung einer Injektionssuspension (Fertigspritze)"]},"pentosanpolysulfat":{"wirkmechanismus":"Lagert sich an die Blasenschleimhaut an und stärkt deren Schutzschicht. Pentosanpolysulfat ist ein halbsynthetisches, heparinähnliches Polysaccharid, das nach Ausscheidung in den Urin die geschädigte Glykosaminoglykan-Schicht der Blasenwand ergänzt. Dadurch gelangen reizende Urinbestandteile weniger an das darunterliegende Gewebe, was Schmerzen und Harndrang vermindert. Zusätzlich wirkt es schwach gerinnungshemmend und fibrinolytisch.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Übelkeit, Durchfall, Verdauungsbeschwerden, Bauchschmerzen, Blähbauch","Blut im Stuhl (rektale Blutung)","Haarausfall","Rückenschmerzen, Beckenschmerzen","Periphere Ödeme (Wassereinlagerungen), Schwäche","Infektionen, Grippe"],"gelegentlich":["Blutarmut, Blutergüsse, Blutungen","Thrombozytopenie, Leukopenie (Mangel an Blutplättchen bzw. weissen Blutkörperchen)","Lichtempfindlichkeit","Appetitlosigkeit, Gewichtsveränderungen","Kribbeln oder Überempfindlichkeit der Haut","Tränenfluss, Sehschwäche","Hautausschlag","Muskel- und Gelenkschmerzen"],"unbekannt":["Pigmentäre Makulopathie (Netzhautschädigung mit Sehstörungen, v. a. bei Langzeitanwendung)","Blutgerinnungsstörungen","Allergische Reaktionen","Leberfunktionsstörungen"]},"schwangerschaft":"Keine ausreichenden Daten; Anwendung nicht empfohlen.","stillzeit":"Keine Daten; Anwendung nicht empfohlen.","hinweise":["Kapseln mit Wasser mindestens 1 Stunde vor oder 2 Stunden nach einer Mahlzeit einnehmen.","Vor Beginn und regelmässig während der Behandlung die Netzhaut augenärztlich kontrollieren lassen; Sehveränderungen sofort melden.","Die Wirkung tritt verzögert ein; nach 6 Monaten wird der Nutzen ärztlich beurteilt.","Vor Operationen die Einnahme angeben (leicht erhöhte Blutungsneigung)."],"darreichung":["Hartkapseln"]},"pentoxifyllin":{"wirkmechanismus":"Verbessert die Fliesseigenschaften des Blutes und damit die Durchblutung kleiner Gefässe. Pentoxifyllin ist ein Xanthinderivat, das Phosphodiesterasen hemmt; es erhöht die Verformbarkeit der roten Blutkörperchen, senkt Blutviskosität und Fibrinogen und hemmt die Zusammenlagerung von Blutplättchen und weissen Blutkörperchen. Ein Teil der Wirkung geht auf aktive Abbauprodukte zurück.","nebenwirkungen":{"haeufig":["Magen-Darm-Beschwerden wie Magendruck, Völlegefühl, Übelkeit, Erbrechen, Durchfall"],"gelegentlich":["Hitzegefühl mit Gesichtsrötung (Flush)","Schwindel, Kopfschmerzen, Zittern","Herzrasen (Tachykardie)","Überempfindlichkeitsreaktionen der Haut (Juckreiz, Rötung, Nesselsucht)"],"selten":["Angina pectoris (Brustenge)","Blutdruckabfall","Blutungen (Haut, Schleimhaut, Magen-Darm-Trakt)","Thrombozytopenie (Mangel an Blutplättchen)"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Gallenstau und Anstieg der Leberwerte","Hypoglykämie (Unterzuckerung)","Aseptische Hirnhautentzündung"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; in der Schwangerschaft nicht anwenden.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; nur nach strenger ärztlicher Abwägung.","hinweise":["Retardtabletten unzerkaut nach dem Essen mit reichlich Flüssigkeit einnehmen.","Bei gleichzeitiger Einnahme von Blutverdünnern die Gerinnungswerte häufiger kontrollieren lassen und Blutungszeichen ärztlich melden.","Gehtraining und Rauchstopp bleiben die wichtigsten Massnahmen bei Schaufensterkrankheit."],"darreichung":["Retardtabletten"]},"perampanel":{"wirkmechanismus":"Bremst die Erregungsübertragung zwischen Nervenzellen im Gehirn. Perampanel blockiert nicht-kompetitiv den AMPA-Rezeptor, über den der erregende Botenstoff Glutamat wirkt. Dadurch wird die Ausbreitung von Anfallsaktivität gehemmt.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Schläfrigkeit"],"haeufig":["Verminderter oder gesteigerter Appetit, Gewichtszunahme","Aggressivität, Wut, Angst, Verwirrtheit, Reizbarkeit","Gangunsicherheit (Ataxie), Gleichgewichtsstörungen, undeutliche Sprache","Doppelbilder, verschwommenes Sehen","Drehschwindel (Vertigo)","Übelkeit","Rückenschmerzen","Müdigkeit, Stürze"],"gelegentlich":["Suizidgedanken, Suizidversuch"],"unbekannt":["DRESS (Arzneimittelreaktion mit Fieber, Ausschlag und Organbeteiligung)","Stevens-Johnson-Syndrom (schwere Hautreaktion)","Psychotische Störungen, Gewaltgedanken"]},"schwangerschaft":"Nicht empfohlen. Frauen im gebärfähigen Alter sollen zuverlässig verhüten (bei 12 mg pro Tag zusätzlich nicht-hormonal).","stillzeit":"Nicht bekannt, ob Perampanel in die Muttermilch übergeht; Stillen nur nach ärztlicher Abwägung.","hinweise":["Einmal täglich vor dem Schlafengehen einnehmen.","Alkohol meiden; Reaktionsvermögen und Fahrtüchtigkeit können deutlich beeinträchtigt sein.","Stimmungs- und Verhaltensänderungen (Aggressivität, Wut) umgehend ärztlich melden.","Nicht eigenmächtig absetzen."],"darreichung":["Filmtabletten","Suspension zum Einnehmen"]},"perindopril":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Bildung des gefässverengenden Hormons Angiotensin II blockiert. Perindopril ist ein Prodrug, das im Körper zu Perindoprilat aktiviert wird; dieses hemmt das Angiotensin-Konversionsenzym (ACE). Angiotensin II und Aldosteron sinken, die Gefässe weiten sich und die Niere scheidet mehr Salz und Wasser aus, was Herz und Gefässe entlastet. Weil ACE auch Bradykinin abbaut, steigt dessen Spiegel – das erklärt Reizhusten und Angioödeme.","nebenwirkungen":{"haeufig":["Schwindel, Kopfschmerzen, Kribbeln (Parästhesien), Drehschwindel","Sehstörungen, Ohrensausen (Tinnitus)","Hypotonie (tiefer Blutdruck)","Trockener Reizhusten, Atemnot","Bauchschmerzen, Verstopfung, Durchfall, Übelkeit, Erbrechen, Verdauungsstörungen, Geschmacksstörung","Juckreiz, Hautausschlag","Muskelkrämpfe","Schwäche (Asthenie)"],"gelegentlich":["Hyperkaliämie (erhöhtes Kalium), Hyponatriämie (Natriummangel), Hypoglykämie (Unterzuckerung)","Stimmungsschwankungen, Schlafstörungen, Depression, Schläfrigkeit","Synkope (Ohnmacht), Herzklopfen, beschleunigter Puls","Bronchospasmus (Verkrampfung der Atemwege)","Angioödem (Schwellung von Gesicht, Lippen, Zunge, Rachen), Nesselsucht, Lichtempfindlichkeit","Niereninsuffizienz, Anstieg von Harnstoff und Kreatinin","Erektionsstörungen","Mundtrockenheit, Gelenk- und Muskelschmerzen, Brustschmerzen, Ödeme, Fieber, Stürze"],"selten":["Akutes Nierenversagen","Verschlechterung einer Psoriasis","Anstieg von Leberwerten und Bilirubin","SIADH (Syndrom der inadäquaten ADH-Sekretion)","Flush (Hautrötung)"],"sehrSelten":["Agranulozytose, Panzytopenie, Leukopenie, Thrombozytopenie","Hämolytische Anämie bei G6PD-Mangel","Verwirrtheit","Herzrhythmusstörungen, Angina pectoris, Herzinfarkt oder Schlaganfall (infolge starken Blutdruckabfalls bei Risikopatienten)","Eosinophile Pneumonie, Schnupfen","Pankreatitis, Hepatitis","Erythema multiforme"],"unbekannt":["Raynaud-Syndrom"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen; im 2. und 3. Drittel kontraindiziert, da fruchtschädigend (Nierenschäden, Fruchtwassermangel, verzögerte Schädelverknöcherung). Bei Kinderwunsch oder festgestellter Schwangerschaft rasch ärztlich auf ein anderes Mittel umstellen.","stillzeit":"Nicht empfohlen, da Daten fehlen; besser untersuchte Alternativen wählen, besonders bei Neugeborenen und Frühgeborenen.","hinweise":["Am besten morgens vor dem Frühstück einnehmen.","Bei Schwellung von Gesicht, Lippen, Zunge oder Rachen oder bei Atemnot sofort den Notruf wählen (Angioödem, auch nach langer Einnahme möglich).","Ein anhaltender trockener Reizhusten ist eine typische Nebenwirkung – ärztlich besprechen, nicht eigenmächtig absetzen.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel nur nach ärztlicher Rücksprache. Bei starkem Durchfall oder Erbrechen ärztlich klären, ob die Einnahme pausiert werden soll."],"darreichung":["Filmtabletten"]},"peritonealdialyseloesung":{"wirkmechanismus":"Übernimmt bei Nierenversagen einen Teil der Nierenfunktion: Die Lösung wird über einen Katheter in die Bauchhöhle eingefüllt und verbleibt dort einige Stunden. Das gut durchblutete Bauchfell (Peritoneum) wirkt als Filtermembran, durch die Harnstoff, Kreatinin, Kalium und andere Stoffe aus dem Blut in die Lösung übertreten. Glucose (osmotisch), Icodextrin (kolloidosmotisch, auch über lange Verweilzeiten) oder Aminosäuren ziehen zusätzlich Wasser aus dem Körper (Ultrafiltration). Ein Puffer (Laktat und/oder Bicarbonat) gleicht die Übersäuerung des Blutes aus.","nebenwirkungen":{"haeufig":["Hypokaliämie (Kaliummangel)","Überwässerung mit Ödemen (Wassereinlagerungen)","Hautausschlag und Juckreiz (unter Icodextrin)"],"unbekannt":["Peritonitis (Bauchfellentzündung), auch nicht-infektiös (aseptisch) mit trüber Auslaufflüssigkeit","Bauchschmerzen, Völlegefühl, Übelkeit","Dehydratation (Austrocknung) mit Blutdruckabfall und Schwindel","Hyperglykämie und Gewichtszunahme durch Glucoseaufnahme","Störungen des Calcium- und Magnesiumspiegels","Hernien (Brüche) und Lecks am Katheter","Enkapsulierende Peritonealsklerose","Schwere Haut- und Überempfindlichkeitsreaktionen (Icodextrin)"]},"schwangerschaft":"Keine ausreichenden Daten; eine notwendige Dialyse wird unter fachärztlicher Betreuung fortgeführt.","stillzeit":"Keine ausreichenden Daten; Anwendung nach ärztlicher Abwägung.","hinweise":["Beutelwechsel streng hygienisch nach Schulung durchführen; trübe Auslaufflüssigkeit, Fieber oder Bauchschmerzen sofort dem Dialysezentrum melden.","Unter Icodextrin (Extraneal) bei jedem Spitaleintritt auf die Behandlung hinweisen: Blutzucker nur mit glucosespezifischen Methoden messen.","Lösung vor dem Einfüllen nur mit trockener Wärme auf Körpertemperatur bringen (keine Mikrowelle, kein Wasserbad).","Täglich Gewicht, Blutdruck und Auslaufmenge protokollieren."],"darreichung":["Lösung zur intraperitonealen Anwendung (Beutel)"]},"permethrin":{"wirkmechanismus":"Wirkt als Nervengift auf Milben und Läuse. Permethrin verzögert das Schliessen der spannungsabhängigen Natriumkanäle in den Nervenzellen der Parasiten; die Dauererregung führt zu Lähmung und Tod. Über die Haut wird beim Menschen nur sehr wenig aufgenommen und rasch zu unwirksamen Stoffen abgebaut.","nebenwirkungen":{"haeufig":["Brennen, Stechen oder Kribbeln der Haut (Parästhesien)","Juckreiz","Hautrötung"],"unbekannt":["Allergische Hautreaktionen (Kontaktekzem)","Trockene Haut","Reizung der Kopfhaut (Läusemittel)"]},"schwangerschaft":"Skabies-Creme im ersten Schwangerschaftsdrittel kontraindiziert, danach nur nach ärztlicher Abwägung. Läusemittel nur nach ärztlicher Rücksprache.","stillzeit":"Nach Behandlung mit der Skabies-Creme 5 Tage nicht stillen. Läusemittel nur nach ärztlicher Rücksprache.","hinweise":["Krätze: Creme dünn auf den ganzen Körper vom Hals bis zu den Zehen auftragen (auch Handflächen, Fusssohlen, unter den Nägeln, Genitalbereich), mindestens 8 Stunden einwirken lassen, dann abwaschen; bei Kleinkindern und älteren Menschen auch Gesicht und Kopfhaut, aber nicht um Augen und Mund.","Alle Kontaktpersonen gleichzeitig behandeln; Wäsche, Bettwäsche und Handtücher bei mindestens 60 °C waschen oder 3 Tage luftdicht verpacken.","Der Juckreiz kann nach erfolgreicher Behandlung noch 2–4 Wochen anhalten und ist kein Zeichen eines Therapieversagens.","Bei Kopfläusen nach 8–10 Tagen kontrollieren und gemäss Packungsbeilage nachbehandeln; Nissen mit einem Läusekamm entfernen."],"darreichung":["Creme","Haarlösung gegen Kopfläuse"]},"pertuzumab":{"wirkmechanismus":"Blockiert ein Wachstumssignal auf der Oberfläche bestimmter Brustkrebszellen. Pertuzumab ist ein humanisierter IgG1-Antikörper, der an die Dimerisierungsdomäne (Subdomäne II) des HER2-Rezeptors bindet und verhindert, dass sich HER2 mit HER3 und anderen HER-Rezeptoren zusammenlagert. Dadurch werden die Signalwege MAPK und PI3K gebremst, was das Zellwachstum stoppt und den Zelltod auslöst; zusätzlich vermittelt er eine antikörperabhängige zelluläre Zytotoxizität. Weil er an einer anderen Stelle als Trastuzumab bindet, ergänzen sich die beiden Antikörper.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Haarausfall (durch die Chemotherapie)","Übelkeit, Erbrechen","Müdigkeit","Neutropenie, febrile Neutropenie, Anämie","Hautausschlag, Nagelveränderungen","Mukositis (Schleimhautentzündung)","Infusionsbedingte Reaktionen"],"haeufig":["Linksventrikuläre Dysfunktion (verminderte Pumpleistung des Herzens)","Paronychie (Nagelbettentzündung)","Pleuraerguss (Flüssigkeit im Brustfell)","Überempfindlichkeitsreaktionen"],"gelegentlich":["Herzinsuffizienz (Herzschwäche)","Interstitielle Lungenerkrankung","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Nicht anwenden: Anti-HER2-Antikörper können beim Ungeborenen zu Fruchtwassermangel, Nierenschäden und Fehlbildungen führen. Zuverlässige Verhütung während der Behandlung und bis 7 Monate nach der letzten Dosis (Kombination mit Trastuzumab).","stillzeit":"Während der Behandlung und bis 7 Monate nach der letzten Dosis nicht stillen.","hinweise":["Die Herzfunktion wird vor und regelmässig während der Behandlung mit Herzultraschall kontrolliert; Atemnot, Beinschwellungen oder Herzklopfen melden.","Starken oder anhaltenden Durchfall früh melden und behandeln.","Nach der Infusion folgt eine Beobachtungszeit wegen möglicher Infusionsreaktionen.","Phesgo enthält Pertuzumab und Trastuzumab in fixer Kombination zur Injektion unter die Haut."],"darreichung":["Infusionskonzentrat","Injektionslösung zur Anwendung unter die Haut (Phesgo)"]},"pertuzumab-trastuzumab":{"wirkmechanismus":"Bremst das Wachstum von Brustkrebszellen, die zu viel vom Wachstumsrezeptor HER2 tragen. Pertuzumab bindet an die Dimerisierungsdomäne (Subdomäne II) von HER2 und verhindert die Paarbildung mit anderen HER-Rezeptoren, vor allem HER3; Trastuzumab bindet an die Subdomäne IV und hemmt die ligandenunabhängige HER2-Signalübertragung. Beide Antikörper lösen zudem eine antikörperabhängige zelluläre Zytotoxizität (ADCC) aus und ergänzen sich in ihrer Wirkung. Die enthaltene Hyaluronidase macht das Unterhautgewebe vorübergehend durchlässiger und ermöglicht so die Gabe als Spritze unter die Haut.","nebenwirkungen":{"sehrHaeufig":["Haarausfall","Durchfall","Übelkeit, Erbrechen","Neutropenie (Mangel an weissen Blutkörperchen, auch mit Fieber) und Anämie (Blutarmut)","Müdigkeit, Schwäche","Hautausschlag","Periphere Neuropathie (Kribbeln, Taubheit in Händen und Füssen)","Reaktionen an der Injektionsstelle (Schmerz, Rötung)"],"haeufig":["Linksventrikuläre Dysfunktion (verminderte Pumpleistung des Herzens)","Überempfindlichkeitsreaktionen","Paronychie (Nagelbettentzündung)","Schüttelfrost"],"gelegentlich":["Herzinsuffizienz (Herzschwäche)","Interstitielle Lungenerkrankung"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Oligohydramnion (zu wenig Fruchtwasser) bei Anwendung in der Schwangerschaft"]},"schwangerschaft":"Nicht anwenden: Trastuzumab kann beim ungeborenen Kind zu Fruchtwassermangel mit Lungen- und Nierenschäden führen, Pertuzumab ist im Tierversuch fruchtschädigend. Während der Behandlung und bis 7 Monate nach der letzten Dosis sicher verhüten.","stillzeit":"Vom Stillen wird während der Behandlung und bis 7 Monate nach der letzten Dosis abgeraten.","hinweise":["Herzfunktion (Herzultraschall) vor Beginn und etwa alle 3 Monate kontrollieren lassen.","Nach der Injektion folgt eine Überwachung (nach der ersten Dosis etwa 30 Minuten, danach etwa 15 Minuten).","Atemnot, Herzklopfen, rasche Gewichtszunahme oder geschwollene Beine sofort melden."],"darreichung":["Injektionslösung zur subkutanen Anwendung"]},"pestwurz-extrakt":{"wirkmechanismus":"Lindert Heuschnupfen-Beschwerden, indem es die Freisetzung entzündungsfördernder Botenstoffe hemmt. Der standardisierte Extrakt Ze 339 enthält Petasine, die die Bildung von Leukotrienen hemmen und die Ausschüttung von Histamin und anderen Entzündungsstoffen vermindern. Er stammt aus einer speziellen Züchtung und ist weitgehend frei von leberschädigenden Pyrrolizidinalkaloiden.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden wie Aufstossen, Übelkeit oder Durchfall","Allergische Hautreaktionen","Erhöhte Leberwerte"]},"schwangerschaft":"Keine Untersuchungen; vorsichtshalber nicht anwenden bzw. nur nach Rücksprache mit Ärztin, Arzt oder Apotheke.","stillzeit":"Keine Untersuchungen; vorsichtshalber nicht anwenden bzw. nur nach Rücksprache mit Ärztin, Arzt oder Apotheke.","hinweise":["Bei Gelbfärbung von Haut oder Augen, dunklem Urin oder Oberbauchschmerzen die Einnahme beenden und ärztlich abklären lassen.","Nur geprüfte, pyrrolizidinfreie Pestwurz-Präparate verwenden, keine selbst hergestellten Tees oder Extrakte."],"darreichung":["Filmtabletten"]},"pethidin":{"wirkmechanismus":"Lindert starke Schmerzen, indem es die Schmerzweiterleitung und -wahrnehmung im Nervensystem dämpft. Pethidin ist ein Agonist am µ-Opioidrezeptor und etwa zehnmal schwächer und kürzer wirksam als Morphin. Zusätzlich hat es anticholinerge und schwach lokalanästhetische Eigenschaften und hemmt die Wiederaufnahme von Serotonin. In der Leber entsteht das langlebige Abbauprodukt Norpethidin, das sich vor allem bei eingeschränkter Nierenfunktion anreichert und Unruhe, Zittern und Krampfanfälle auslösen kann.","nebenwirkungen":{"unbekannt":["Übelkeit, Erbrechen","Schwindel, Benommenheit, Müdigkeit","Schwitzen, Mundtrockenheit, Hautrötung","Obstipation (Verstopfung), Harnverhalt","Atemdepression (abgeflachte Atmung)","Blutdruckabfall, Herzrasen","Unruhe, Zittern, Krampfanfälle (durch Norpethidin)","Abhängigkeit und Entzugssymptome bei wiederholter Anwendung"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Gabe kurz vor oder während der Geburt kann beim Neugeborenen eine Atemdepression auftreten; längere Anwendung kann beim Neugeborenen Entzugssymptome auslösen.","stillzeit":"Pethidin und Norpethidin gehen in die Muttermilch über und können sich beim Säugling anreichern (Schläfrigkeit, Trinkschwäche) – wiederholte Gaben in der Stillzeit vermeiden; Vorgehen ärztlich besprechen.","hinweise":["Kein Alkohol und keine anderen Beruhigungs- oder Schlafmittel ohne ärztliche Rücksprache (Gefahr einer Atemlähmung).","Nach der Anwendung nicht Auto fahren und keine Maschinen bedienen.","Wegen der Anreicherung von Norpethidin nur kurzzeitig und nicht zur Dauerbehandlung einsetzen.","Untersteht dem Betäubungsmittelgesetz."],"darreichung":["Injektionslösung"]},"pfefferminzoel":{"wirkmechanismus":"Entspannt die verkrampfte Darmmuskulatur und lindert so Krämpfe und Blähungen. Der Hauptbestandteil Menthol hemmt den Calciumeinstrom in die glatten Muskelzellen der Darmwand (calciumantagonistische Wirkung) und wirkt dadurch krampflösend. Die magensaftresistente Hülle sorgt dafür, dass das Öl erst im Dünn- und Dickdarm freigesetzt wird und nicht schon im Magen Sodbrennen auslöst.","nebenwirkungen":{"unbekannt":["Sodbrennen","Brennen in der Analgegend (perianales Brennen)","Übelkeit, Erbrechen","Allergische Reaktionen auf Menthol (Hautausschlag, Kopfschmerzen, Muskelzittern)","Verschwommenes Sehen","Brennen beim Wasserlassen, Mentholgeruch von Urin und Stuhl","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Zur Anwendung in der Schwangerschaft liegen keine ausreichenden Daten vor; nicht empfohlen.","stillzeit":"Menthol kann in die Muttermilch übergehen; die Anwendung in der Stillzeit wird nicht empfohlen.","hinweise":["Kapseln unzerkaut mit etwas Wasser schlucken, nicht öffnen oder zerbeissen (sonst Reizung von Mund und Speiseröhre).","Vor den Mahlzeiten einnehmen, nicht zusammen mit Essen oder Säurebindern.","Bessern sich die Beschwerden nicht innerhalb von zwei Wochen, ärztlichen Rat einholen."],"darreichung":["Magensaftresistente Kapseln"]},"phenazon-procain":{"wirkmechanismus":"Lindert Ohrenschmerzen direkt im Gehörgang. Phenazon ist ein Schmerz- und Fiebermittel aus der Gruppe der Pyrazolone, das die Bildung von Prostaglandinen hemmt und entzündungsbedingte Schmerzen dämpft. Procain ist ein Lokalanästhetikum vom Ester-Typ, das Natriumkanäle in den Nervenfasern blockiert und so die Schmerzweiterleitung örtlich unterbricht.","nebenwirkungen":{"unbekannt":["Allergische Reaktionen am Ohr (Juckreiz, Rötung, Schwellung, Ausschlag)","Örtliche Reizung im Gehörgang"]},"schwangerschaft":"Keine ausreichenden Daten; nur nach ärztlicher Rücksprache anwenden.","stillzeit":"Keine ausreichenden Daten; nur nach ärztlicher Rücksprache anwenden.","hinweise":["Fläschchen vor Gebrauch in der Hand auf Körpertemperatur anwärmen – kalte Tropfen im Ohr können Schwindel auslösen.","Nur ins Ohr träufeln; die Pipette nicht mit dem Ohr in Berührung bringen.","Bei Ausfluss aus dem Ohr nicht anwenden, sondern ärztlich abklären lassen (mögliche Trommelfellverletzung)."],"darreichung":["Ohrentropfen"]},"pheniramin":{"wirkmechanismus":"Lindert Schnupfen und Niesreiz, indem es die Wirkung von Histamin blockiert. Pheniramin ist ein H1-Rezeptor-Antagonist der 1. Generation aus der Gruppe der Alkylamine. Seine anticholinerge Wirkung vermindert die Sekretion der Nasenschleimhaut; da es ins Gehirn gelangt, macht es müde.","nebenwirkungen":{"unbekannt":["Müdigkeit, Schläfrigkeit","Mundtrockenheit","Schwindel","Sehstörungen (Akkommodationsstörungen)","Harnverhalt","Verstopfung","Paradoxe Erregung, vor allem bei Kindern","Allergische Hautreaktionen"]},"schwangerschaft":"Nicht empfohlen; nur nach ärztlicher Abwägung.","stillzeit":"Pheniramin kann in die Muttermilch übergehen; in der Stillzeit nicht empfohlen.","hinweise":["Kann müde machen: Vorsicht im Strassenverkehr, keinen Alkohol trinken.","Bei Kombinationspräparaten mit Paracetamol keine weiteren Paracetamol-haltigen Mittel einnehmen (Überdosierungsgefahr).","Erkältungsmittel nur wenige Tage anwenden; bei hohem Fieber oder anhaltenden Beschwerden ärztlich abklären lassen."],"darreichung":["Pulver zur Herstellung einer Trinklösung"]},"phenobarbital":{"wirkmechanismus":"Dämpft die Erregbarkeit der Nervenzellen und verhindert so die Ausbreitung von Krampfanfällen. Phenobarbital verstärkt die hemmende Wirkung des Botenstoffs GABA am GABA-A-Rezeptor, indem es die Öffnungsdauer der Chloridkanäle verlängert; in höheren Konzentrationen öffnet es die Kanäle auch direkt und hemmt erregende Glutamat-Wirkungen. Wegen der sehr langen Halbwertszeit (etwa 3–4 Tage) stellt sich ein gleichmässiger Spiegel erst nach 2–3 Wochen ein. Es ist ein starker Induktor zahlreicher Leberenzyme (u. a. CYP3A4, CYP2C9, CYP1A2) und von P-Glykoprotein und beschleunigt den Abbau vieler Arzneimittel.","nebenwirkungen":{"unbekannt":["Müdigkeit, Benommenheit, verlangsamtes Denken","Gangunsicherheit (Ataxie), Schwindel, Augenzittern","Paradoxe Erregung und Reizbarkeit (v. a. bei Kindern und älteren Menschen), Depression","Gedächtnis- und Lernstörungen","Abhängigkeit; Entzugskrampfanfälle beim abrupten Absetzen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Megaloblastäre Anämie (Folsäuremangel), Knochenerweichung bei Langzeitbehandlung","Leberschäden; Atemdepression bei hohen Dosen"]},"schwangerschaft":"Fruchtschädigend (u. a. Herzfehler, Gaumenspalten) – nur wenn unverzichtbar, in der niedrigsten wirksamen Dosis und mit Folsäure. Beim Neugeborenen sind Entzugssymptome und eine Blutungsneigung (Vitamin-K-Mangel) möglich.","stillzeit":"Geht in erheblichen Mengen in die Muttermilch über; Stillen nur nach ärztlicher Abwägung, Säugling auf Schläfrigkeit und Trinkschwäche beobachten.","hinweise":["Nicht abrupt absetzen – Gefahr von Krampfanfällen und Entzugssymptomen.","Kein Alkohol; die Fahrtüchtigkeit ist besonders zu Beginn deutlich eingeschränkt.","Hormonale Verhütung ist unzuverlässig – nichthormonal verhüten.","Bei jedem neuen Medikament Wechselwirkungen prüfen lassen; Spiegel, Blutbild und Leberwerte werden kontrolliert."],"darreichung":["Tabletten","Injektionslösung"]},"phenoxymethylpenicillin":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand stört. Phenoxymethylpenicillin hemmt wie alle Penicilline die Penicillin-bindenden Proteine (Transpeptidasen) und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Im Gegensatz zu Benzylpenicillin ist es säurestabil und kann deshalb geschluckt werden. Das Wirkspektrum ist schmal – vor allem Streptokokken, Pneumokokken und Borrelien; Beta-Laktamase-bildende Keime wie die meisten Staphylokokken sind resistent.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen","Durchfall, Bauchschmerzen"],"gelegentlich":["Allergische Hautreaktionen (Ausschlag, Nesselsucht, Juckreiz)","Entzündung von Mundschleimhaut oder Zunge"],"selten":["Anaphylaxie (schwere allergische Reaktion) und Angioödem (Schwellung von Gesicht und Rachen)"],"sehrSelten":["Blutbildveränderungen (Neutropenie, Thrombozytopenie, hämolytische Anämie)","Pseudomembranöse Kolitis (schwere Darmentzündung)","Interstitielle Nephritis (Nierenentzündung)","Schwere Hautreaktionen (z. B. Stevens-Johnson-Syndrom)"],"unbekannt":["Pilzinfektionen (Mund, Scheide)","Schwarze Haarzunge","Jarisch-Herxheimer-Reaktion"]},"schwangerschaft":"Erlaubt; langjährige Erfahrung ohne Hinweise auf eine Schädigung des Kindes.","stillzeit":"Erlaubt; nur geringe Mengen gehen in die Muttermilch über (beim Säugling Durchfall oder Pilzbefall möglich).","hinweise":["Die Einnahmen gleichmässig über den Tag verteilen und die verordnete Behandlungsdauer einhalten, auch wenn die Beschwerden rasch abklingen – besonders bei Streptokokken-Angina.","Bei Hautausschlag, Atemnot oder Schwellungen sofort ärztlichen Rat einholen.","Schwerer oder blutiger Durchfall, auch nach Behandlungsende, muss ärztlich abgeklärt werden."],"darreichung":["Filmtabletten","Suspension oder Sirup zum Einnehmen"]},"phenprocoumon":{"wirkmechanismus":"Hemmt die Blutgerinnung, indem es die Wirkung von Vitamin K in der Leber blockiert. Phenprocoumon hemmt die Vitamin-K-Epoxid-Reduktase (VKORC1); dadurch werden die Gerinnungsfaktoren II, VII, IX und X sowie die Gerinnungshemmer Protein C und S nicht mehr funktionsfähig gebildet. Die volle Wirkung setzt erst nach einigen Tagen ein, weil die vorhandenen Faktoren zuerst abgebaut werden müssen; zu Beginn wird daher oft überlappend Heparin gegeben. Wegen der sehr langen Halbwertszeit von rund 150 Stunden hält die Wirkung nach dem Absetzen 1–2 Wochen an; die Dosis wird über den INR-Wert gesteuert, Gegenmittel ist Vitamin K.","nebenwirkungen":{"sehrHaeufig":["Blutungen unterschiedlicher Schwere – meist leicht (Zahnfleisch- und Nasenbluten, Blutergüsse, Blut im Urin), seltener schwer (Magen-Darm-Blutung, Hirnblutung)"],"gelegentlich":["Übelkeit, Appetitlosigkeit, Erbrechen, Durchfall","Vorübergehender Haarausfall","Hautausschlag, Juckreiz, Nesselsucht"],"selten":["Cumarin-Nekrose (Absterben von Hautarealen), meist in den ersten Behandlungstagen und bei Protein-C-Mangel"],"sehrSelten":["Purple-toe-Syndrom (schmerzhafte violette Verfärbung der Zehen)","Gefässentzündung (Vaskulitis)"],"unbekannt":["Leberentzündung (Hepatitis) bis hin zu schweren Leberschäden","Osteoporose bei langdauernder Anwendung","Calciphylaxie (schmerzhafte Hautgeschwüre durch Gefässverkalkung), vor allem bei Nierenkrankheit"]},"schwangerschaft":"Kontraindiziert: Phenprocoumon kann das Kind schädigen (Cumarin-Embryopathie, Blutungen). Frauen im gebärfähigen Alter müssen sicher verhüten; bei Kinderwunsch oder Schwangerschaft umgehend ärztlich auf Heparin umstellen.","stillzeit":"Geht in die Muttermilch über; Stillen nur nach ärztlicher Abwägung – das Kind erhält dann vorsorglich Vitamin K und wird auf Blutungszeichen überwacht.","hinweise":["Regelmässige INR-Kontrollen einhalten; Antikoagulationsausweis mitführen und alle Ärztinnen, Ärzte, Zahnärzte und Apotheken informieren.","Keine neuen Medikamente, auch keine rezeptfreien Schmerzmittel oder pflanzlichen Mittel (z. B. Johanniskraut), ohne Rücksprache – viele verändern den INR.","Ernährung gleichmässig halten: die Menge Vitamin-K-reicher Lebensmittel (Kohl, Spinat, Sauerkraut, grünes Blattgemüse) nicht plötzlich stark ändern; Alkohol nur in kleinen Mengen.","Wegen der langen Wirkdauer Operationen und Zahnextraktionen frühzeitig ärztlich planen; bei Zeichen einer Blutung (schwarzer Stuhl, Blut im Urin, starke Kopfschmerzen) sofort ärztliche Hilfe holen."],"darreichung":["Tabletten"]},"phenylephrin":{"wirkmechanismus":"Verengt Blutgefässe und lässt dadurch geschwollene Schleimhäute abschwellen bzw. hebt den Blutdruck. Phenylephrin stimuliert gezielt Alpha-1-Rezeptoren der glatten Muskulatur und hat kaum Wirkung auf Beta-Rezeptoren. Am Auge zieht es den Pupillenerweiterer-Muskel zusammen und erweitert so die Pupille, ohne die Naheinstellung (Akkommodation) wesentlich zu lähmen. Als Injektion erhöht es den Gefässwiderstand und damit den Blutdruck; der Puls kann reflektorisch langsamer werden.","nebenwirkungen":{"unbekannt":["Augentropfen: Brennen, vorübergehend verschwommenes Sehen, Blendempfindlichkeit, Rötung des Auges","Augentropfen (v. a. 10 %): Blutdruckanstieg, Herzklopfen","Nasenpräparate: Brennen, Trockenheit der Nasenschleimhaut, Niesen","Rebound-Schwellung und Dauerschnupfen (Rhinitis medicamentosa) bei längerer Anwendung","Bluthochdruck, Herzklopfen, Reflex-Bradykardie (verlangsamter Puls)","Herzrhythmusstörungen","Kopfschmerzen, Unruhe, Schlaflosigkeit, Zittern","Übelkeit","Harnverhalt","Allergische Reaktionen"]},"schwangerschaft":"Erkältungs- und Nasenmittel mit Phenylephrin in der Schwangerschaft möglichst meiden, besonders im ersten Drittel. Augentropfen und Injektion nur nach ärztlicher Abwägung.","stillzeit":"Orale Erkältungsmittel mit Phenylephrin in der Stillzeit nicht empfohlen. Kurzfristige Anwendung als Augen- oder Nasentropfen nach ärztlicher Rücksprache möglich.","hinweise":["Nasenpräparate höchstens 5–7 Tage ohne Unterbruch anwenden, sonst droht Dauerschnupfen.","Nach pupillenerweiternden Augentropfen ist die Sicht für einige Stunden verschwommen und blendempfindlich – nicht selbst Auto fahren.","Nicht mehrere Erkältungsmittel gleichzeitig verwenden; bei Kombipräparaten die Paracetamol-Höchstdosis beachten.","Bei Bluthochdruck oder Herzkrankheiten vor der Anwendung in der Apotheke oder ärztlich beraten lassen."],"darreichung":["Augentropfen","Nasenspray","Nasentropfen","Nasengel","Pulver zum Auflösen (Beutel)","Injektionslösung"]},"phenytoin":{"wirkmechanismus":"Stabilisiert die Nervenzellen und verhindert so, dass sich Krampfaktivität im Gehirn ausbreitet. Phenytoin blockiert spannungsabhängige Natriumkanäle bevorzugt im inaktivierten Zustand, also vor allem bei schnell und wiederholt feuernden Nervenzellen. Es wird über CYP2C9 und CYP2C19 abgebaut; weil dieser Abbau sättigbar ist, steigt der Spiegel bei höheren Dosen überproportional an (enger therapeutischer Bereich, etwa 10–20 mg/l). Zudem induziert Phenytoin stark CYP3A4 und andere Enzyme und beschleunigt so den Abbau vieler Arzneimittel.","nebenwirkungen":{"unbekannt":["Augenzittern (Nystagmus), Doppeltsehen, Gangunsicherheit, verwaschene Sprache (oft Zeichen zu hoher Spiegel)","Schwindel, Müdigkeit, Verwirrtheit","Zahnfleischwucherung (Gingivahyperplasie), vermehrte Körperbehaarung, Vergröberung der Gesichtszüge","Hautausschlag; schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Blutbildveränderungen (z. B. Agranulozytose, Thrombozytopenie, megaloblastäre Anämie)","Leberentzündung bis Leberversagen","Knochenerweichung und Knochenschwund bei Langzeitbehandlung","Injektion: Blutdruckabfall, Herzrhythmusstörungen, Gewebeschäden an der Injektionsstelle (Purple-Glove-Syndrom)"]},"schwangerschaft":"Fruchtschädigend (fetales Hydantoin-Syndrom mit Fehlbildungen sowie Wachstums- und Entwicklungsstörungen) – nur wenn unverzichtbar, mit Folsäure und Spiegelkontrollen. Beim Neugeborenen ist eine Blutungsneigung möglich (Vitamin-K-Gabe).","stillzeit":"Geht nur in geringen Mengen in die Muttermilch über; Stillen ist in der Regel möglich, Säugling auf Schläfrigkeit und Trinkschwäche beobachten.","hinweise":["Regelmässige Kontrollen von Spiegel, Blutbild und Leberwerten; schon kleine Dosisänderungen können den Spiegel stark verändern.","Gute Mundhygiene und regelmässige Zahnkontrollen (Zahnfleischwucherung).","Nicht abrupt absetzen und das Präparat nicht ohne ärztliche Rücksprache wechseln.","Bei Hautausschlag, Fieber, Halsschmerzen oder Gelbfärbung der Haut sofort ärztlich abklären."],"darreichung":["Tabletten","Injektionslösung"]},"physostigmin":{"wirkmechanismus":"Hebt die Wirkung von Giften auf, die den Nervenbotenstoff Acetylcholin blockieren. Physostigmin hemmt vorübergehend (reversibel) die Acetylcholinesterase, sodass mehr Acetylcholin zur Verfügung steht und die blockierten Muskarinrezeptoren wieder aktiviert werden. Als tertiäres Amin überwindet es die Blut-Hirn-Schranke und wirkt deshalb auch gegen die Vergiftungszeichen im Gehirn. Die Wirkung hält oft kürzer an als das Gift, sodass wiederholte Gaben nötig sein können.","nebenwirkungen":{"unbekannt":["Übelkeit, Erbrechen, Durchfall","Vermehrter Speichelfluss und Schwitzen","Pulsverlangsamung (Bradykardie), Blutdruckabfall","Bronchospasmus (Verkrampfung der Atemwege)","Pupillenverengung","Krampfanfälle (v. a. bei Überdosierung oder zu rascher Injektion)","Muskelzuckungen"]},"schwangerschaft":"Keine ausreichenden Daten; nur bei zwingender Notwendigkeit nach ärztlicher Abwägung anwenden.","stillzeit":"Keine Daten; Entscheidung nach ärztlicher Abwägung.","hinweise":["Wird nur unter Monitoring (EKG, Puls, Atmung) im Spital oder durch Notärztinnen und Notärzte verabreicht.","Atropin muss als Gegenmittel bei Überdosierung bereitliegen."],"darreichung":["Injektionslösung (Ampullen)"]},"phytomenadion":{"wirkmechanismus":"Ermöglicht der Leber die Bildung funktionsfähiger Gerinnungsfaktoren. Vitamin K1 ist der Kofaktor der Gamma-Glutamyl-Carboxylase, die die Gerinnungsfaktoren II, VII, IX und X sowie die Gerinnungshemmer Protein C und S erst aktiv macht. Vitamin-K-Antagonisten blockieren die Rückgewinnung von Vitamin K; zugeführtes Phytomenadion umgeht diese Blockade. Die Wirkung setzt nicht sofort ein, sondern erst nach einigen Stunden, weil die Faktoren neu gebildet werden müssen; bei lebensbedrohlicher Blutung werden deshalb zusätzlich Gerinnungsfaktoren (Prothrombinkomplex) gegeben.","nebenwirkungen":{"unbekannt":["Überempfindlichkeits- und anaphylaktoide Reaktionen bis Schock, Herz- und Atemstillstand (v. a. bei intravenöser Gabe)","Venenreizung oder Venenentzündung an der Injektionsstelle","Reaktionen an der Injektionsstelle (bei Neugeborenen)"]},"schwangerschaft":"Keine Hinweise auf eine Schädigung; nur bei klarer Indikation anwenden. Eine Gabe an die Schwangere zur Vorbeugung von Blutungen beim Neugeborenen wird nicht empfohlen.","stillzeit":"Nur geringe Mengen gehen in die Muttermilch über; Anwendung möglich. Gestillte Neugeborene brauchen trotzdem ihre eigene Vitamin-K-Prophylaxe.","hinweise":["Wirkt nicht gegen Heparine und direkte orale Antikoagulanzien (z. B. Rivaroxaban, Apixaban, Dabigatran).","Intravenös nur langsam spritzen; bei Erwachsenen nicht in den Muskel spritzen (Blutergussgefahr unter Gerinnungshemmung).","Nach der Aufhebung einer Vitamin-K-Antagonisten-Wirkung den INR kontrollieren lassen.","In der Schweiz erhalten Neugeborene routinemässig Vitamin K nach einem festen Schema in den ersten Lebenswochen."],"darreichung":["Injektionslösung in Ampullen (auch zum Einnehmen)"]},"pilocarpin":{"wirkmechanismus":"Ahmt die Wirkung des Botenstoffs Acetylcholin im parasympathischen Nervensystem nach. Pilocarpin ist ein direkter Agonist an Muskarinrezeptoren. Am Auge zieht es den Pupillenschliessmuskel und den Ziliarmuskel zusammen: Die Pupille wird eng, das Trabekelwerk im Kammerwinkel öffnet sich und das Kammerwasser fliesst besser ab, wodurch der Augeninnendruck sinkt. Als Tablette regt es Speichel- und Schweissdrüsen zur Sekretion an.","nebenwirkungen":{"sehrHaeufig":["Vermehrtes Schwitzen (Tabletten)"],"unbekannt":["Tabletten: Übelkeit, Durchfall, Verdauungsbeschwerden, häufiges Wasserlassen","Tabletten: Kopfschmerzen, Schwindel, Hautrötung mit Wärmegefühl (Flush), Frösteln, Schnupfen, Tränenfluss","Augentropfen: Akkommodationskrampf mit Kurzsichtigkeit sowie Kopf- und Stirnschmerzen","Schlechtes Sehen bei Dämmerung (enge Pupille), verschwommenes Sehen","Augenbrennen, Augenrötung, Augenreizung","Netzhautablösung","Vermehrter Speichelfluss, Pulsverlangsamung, Blutdruckabfall, Verengung der Atemwege"]},"schwangerschaft":"Nur anwenden, wenn klar notwendig; für die Anwendung in der Schwangerschaft liegen keine ausreichenden Daten vor.","stillzeit":"Bei Einnahme der Tabletten wird vom Stillen abgeraten; Augentropfen nur nach ärztlicher Abwägung.","hinweise":["Augentropfen: Sehschärfe und Dämmerungssehen sind nach dem Eintropfen vermindert – nachts und bei schlechtem Licht nicht Auto fahren.","Tabletten mit einem Glas Wasser zu oder direkt nach den Mahlzeiten einnehmen; bei starkem Schwitzen viel trinken.","Bei Lichtblitzen, Russregen oder Schatten im Gesichtsfeld sofort augenärztlich abklären (Netzhautablösung)."],"darreichung":["Augentropfen","Filmtabletten"]},"pimecrolimus":{"wirkmechanismus":"Dämpft die Entzündung in der Haut, ohne Kortison zu enthalten und ohne die Haut dünner zu machen. Pimecrolimus bindet an Macrophilin-12 und hemmt so das Enzym Calcineurin in T-Zellen und Mastzellen. Dadurch werden entzündungsfördernde Botenstoffe (Zytokine) und die Freisetzung von Entzündungsmediatoren gehemmt. Über die Haut gelangt nur sehr wenig in den Blutkreislauf.","nebenwirkungen":{"sehrHaeufig":["Brennen an der Auftragsstelle"],"haeufig":["Reaktionen an der Auftragsstelle (Reizung, Juckreiz, Rötung)","Hautinfektionen (Follikulitis)"],"gelegentlich":["Furunkel, Impetigo, Herpes simplex (auch Ekzema herpeticatum), Gürtelrose","Molluscum contagiosum (Dellwarzen)","Verschlechterung der Neurodermitis"],"selten":["Alkoholunverträglichkeit (Gesichtsrötung, Hautreizung nach Alkohol)","Allergische Reaktionen (Ausschlag, Nesselsucht, Angioödem), Hautverfärbung"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Lymphome und Hauttumoren (Zusammenhang nicht gesichert)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; es liegen kaum Erfahrungen vor, die Aufnahme in den Körper ist jedoch sehr gering.","stillzeit":"Nur nach ärztlicher Abwägung; nicht auf die Brust auftragen.","hinweise":["Zweimal täglich dünn auftragen; Besserung meist innert weniger Tage. Ohne Besserung nach 6 Wochen ärztlich neu beurteilen lassen.","Nicht unter luftdichten Verbänden anwenden; Kontakt mit Augen und Schleimhäuten vermeiden.","Sonnenschutz und Meiden von Solarium; Alkohol kann Gesichtsrötung auslösen."],"darreichung":["Creme"]},"pinaverium":{"wirkmechanismus":"Entspannt die verkrampfte Darmmuskulatur. Pinaverium blockiert spannungsabhängige Calciumkanäle (L-Typ) der glatten Muskelzellen im Magen-Darm-Trakt und verhindert so den Calciumeinstrom, den die Muskulatur zum Zusammenziehen braucht. Weil nur sehr wenig Wirkstoff aus dem Darm ins Blut gelangt und er grösstenteils über die Galle ausgeschieden wird, wirkt er fast nur im Verdauungstrakt und kaum auf Herz und Blutgefässe.","nebenwirkungen":{"gelegentlich":["Bauchschmerzen","Übelkeit, Erbrechen","Durchfall","Schluckbeschwerden (Dysphagie)","Hautausschlag, Rötung, Juckreiz, Nesselsucht"],"unbekannt":["Überempfindlichkeitsreaktionen bis zu Angioödem (Schwellung von Gesicht und Rachen) und Anaphylaxie","Reizung oder Schädigung der Speiseröhre bei falscher Einnahme"]},"schwangerschaft":"Nicht empfohlen: keine ausreichenden Daten. Der enthaltene Bromidanteil könnte bei Einnahme gegen Ende der Schwangerschaft beim Neugeborenen Schläfrigkeit und Muskelschwäche verursachen.","stillzeit":"Nicht empfohlen, da keine Daten zum Übergang in die Muttermilch vorliegen.","hinweise":["Tablette unzerkaut mit einem grossen Glas Wasser während einer Mahlzeit einnehmen – nicht im Liegen und nicht unmittelbar vor dem Schlafengehen (Gefahr einer Speiseröhrenreizung).","Klinisch bedeutsame Wechselwirkungen mit anderen Arzneimitteln sind nicht bekannt."],"darreichung":["Filmtabletten"]},"pindolol":{"wirkmechanismus":"Senkt den Blutdruck und entlastet das Herz, indem es die Wirkung der Stresshormone Adrenalin und Noradrenalin am Herzen abschwächt. Pindolol blockiert Beta-1- und Beta-2-Rezeptoren ohne Selektivität und besitzt zugleich eine ausgeprägte partielle agonistische Eigenwirkung (intrinsische sympathomimetische Aktivität, ISA). Deshalb sinken Ruhepuls und Herzauswurf weniger stark als unter anderen Betablockern, während der Anstieg von Puls und Blutdruck unter Belastung gedämpft wird.","nebenwirkungen":{"haeufig":["Schwindel, Müdigkeit, Kopfschmerzen","Schlafstörungen","Magen-Darm-Beschwerden (Übelkeit, Durchfall)"],"unbekannt":["Bradykardie (langsamer Puls), AV-Block","Verschlechterung einer Herzinsuffizienz","Bronchospasmus (Verkrampfung der Atemwege)","Kalte Hände und Füsse, Verschlechterung von Durchblutungsstörungen","Muskelkrämpfe, Zittern","Depressive Verstimmung, lebhafte Träume","Hautausschlag, Verschlechterung einer Psoriasis"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Betablocker können das Wachstum des Kindes vermindern und beim Neugeborenen langsamen Puls und Unterzuckerung verursachen.","stillzeit":"Pindolol geht in die Muttermilch über; nicht empfohlen bzw. nur nach strenger ärztlicher Abwägung.","hinweise":["Nicht abrupt absetzen – Gefahr von Angina-pectoris-Anfällen, Herzinfarkt und Blutdruckanstieg; über 1–2 Wochen ausschleichen.","Vor Operationen die Behandlung angeben.","Kann besonders zu Beginn und zusammen mit Alkohol die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Tabletten"]},"pioglitazon":{"wirkmechanismus":"Macht die Körperzellen wieder empfindlicher für Insulin. Pioglitazon aktiviert den Kernrezeptor PPAR-gamma (peroxisome proliferator-activated receptor gamma) vor allem im Fettgewebe, aber auch in Muskel und Leber. Dadurch werden Gene des Zucker- und Fettstoffwechsels reguliert: Die Zellen nehmen mehr Glucose auf, die Zuckerneubildung in der Leber sinkt. Die volle Wirkung entwickelt sich erst über mehrere Wochen; allein verursacht Pioglitazon keine Unterzuckerung.","nebenwirkungen":{"sehrHaeufig":["Ödeme (Wassereinlagerungen) in Kombination mit Insulin"],"haeufig":["Gewichtszunahme","Ödeme (Wassereinlagerungen) bei Behandlung ohne Insulin","Herzinsuffizienz in Kombination mit Insulin","Hypoglykämie (Unterzuckerung) in Kombination mit Insulin oder Sulfonylharnstoffen","Infektionen der oberen Atemwege","Hypästhesie (Taubheitsgefühl)","Sehstörungen","Knochenbrüche"],"gelegentlich":["Blasenkrebs","Sinusitis (Nasennebenhöhlenentzündung)","Schlaflosigkeit"],"unbekannt":["Makulaödem (Schwellung der Netzhautmitte)","Erhöhte Leberwerte, Leberentzündung","Überempfindlichkeitsreaktionen (Angioödem, Ausschlag, Nesselsucht)"]},"schwangerschaft":"Nicht anwenden; ein Diabetes in der Schwangerschaft wird mit Insulin behandelt.","stillzeit":"Nicht anwenden, da Pioglitazon in die Muttermilch übergehen kann.","hinweise":["Regelmässig wiegen: rasche Gewichtszunahme, geschwollene Beine oder Atemnot sofort ärztlich melden (mögliche Herzinsuffizienz).","Blut im Urin, Schmerzen oder plötzlicher Harndrang beim Wasserlassen ärztlich abklären lassen.","Die volle Wirkung zeigt sich erst nach einigen Wochen; die Leberwerte werden regelmässig kontrolliert."],"darreichung":["Tabletten"]},"pipamperon":{"wirkmechanismus":"Wirkt vor allem beruhigend und schlaffördernd, kaum antipsychotisch im engeren Sinn. Pipamperon blockiert vor allem Serotonin-5-HT2A- und Dopamin-D4-Rezeptoren, schwächer auch Dopamin-D2- sowie Alpha-1-Rezeptoren. Wegen der schwachen D2-Blockade treten Bewegungsstörungen seltener auf als bei hochpotenten Antipsychotika wie Haloperidol.","nebenwirkungen":{"haeufig":["Schläfrigkeit, Müdigkeit","Extrapyramidale Störungen (Zittern, Muskelsteife, Bewegungsarmut, Sitzunruhe)"],"unbekannt":["Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen), Schwindel","Herzrasen","QT-Verlängerung und Herzrhythmusstörungen","Spätdyskinesien (bleibende unwillkürliche Bewegungen)","Malignes neuroleptisches Syndrom (Fieber, Muskelsteife, Bewusstseinsstörung)","Krampfanfälle","Erhöhtes Prolaktin mit Milchfluss und Zyklusstörungen","Venöse Thromboembolie"]},"schwangerschaft":"Nur begrenzte Erfahrungen; nur nach strenger ärztlicher Abwägung. Bei Einnahme im letzten Drittel können beim Neugeborenen Bewegungsstörungen und Entzugssymptome auftreten.","stillzeit":"Ob Pipamperon in die Muttermilch übergeht, ist nicht bekannt. Während der Behandlung nicht stillen.","hinweise":["Wirkt beruhigend: Fahrtüchtigkeit beeinträchtigt; Alkohol meiden.","Langsam aufstehen, besonders nachts (Sturzgefahr durch Blutdruckabfall).","Bei hohem Fieber mit Muskelsteife sofort ärztliche Hilfe holen."],"darreichung":["Tabletten","Tropfen"]},"piperacillin-tazobactam":{"wirkmechanismus":"Tötet ein sehr breites Spektrum von Bakterien ab. Piperacillin hemmt die Penicillin-bindenden Proteine und damit den Aufbau der bakteriellen Zellwand (bakterizide Wirkung); es erfasst viele gramnegative Keime einschliesslich Pseudomonas aeruginosa sowie Anaerobier. Tazobactam hemmt zahlreiche Beta-Laktamasen und schützt Piperacillin so vor dem Abbau durch resistente Bakterien. Gegen MRSA und Carbapenemase-bildende Erreger wirkt die Kombination nicht.","nebenwirkungen":{"sehrHaeufig":["Durchfall"],"haeufig":["Candida-Infektionen (Pilzbefall)","Thrombozytopenie, Anämie","Schlaflosigkeit, Kopfschmerzen","Übelkeit, Erbrechen, Bauchschmerzen, Verstopfung, Verdauungsbeschwerden","Hautausschlag, Juckreiz","Fieber, Reaktionen an der Infusionsstelle","Anstieg von Leber- und Nierenwerten, verlängerte Gerinnungszeit, positiver Coombs-Test"],"gelegentlich":["Leukopenie (Mangel an weissen Blutkörperchen)","Hypokaliämie (Kaliummangel), tiefer Blutzucker","Blutdruckabfall, Venenentzündung, Hitzegefühl","Erythema multiforme (Hautausschlag mit kokardenförmigen Flecken)","Nesselsucht (Urtikaria)","Gelenk- und Muskelschmerzen, Schüttelfrost","Krampfanfälle (vor allem bei hohen Dosen und eingeschränkter Nierenfunktion)"],"selten":["Agranulozytose","Pseudomembranöse Kolitis (schwere Darmentzündung)","Nasenbluten, Mundschleimhautentzündung","Toxische epidermale Nekrolyse (schwere Hautablösung)"],"unbekannt":["Anaphylaxie bis zum anaphylaktischen Schock","Panzytopenie, Neutropenie, hämolytische Anämie, Eosinophilie","Leberentzündung, Gelbsucht","Stevens-Johnson-Syndrom, DRESS, AGEP","Interstitielle Nephritis, Nierenversagen","Eosinophile Pneumonie (allergische Lungenentzündung)","Hämophagozytische Lymphohistiozytose (HLH)","Delir (akute Verwirrtheit)"]},"schwangerschaft":"Nur anwenden, wenn eindeutig nötig und der Nutzen das mögliche Risiko überwiegt; beide Wirkstoffe passieren die Plazenta.","stillzeit":"Piperacillin geht in geringen Mengen in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Wird im Spital als Infusion verabreicht.","Bei längerer Behandlung werden Blutbild, Nieren- und Leberwerte sowie Kalium kontrolliert.","Hautausschlag, Atemnot, Blutungszeichen oder schweren Durchfall sofort melden."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"piracetam":{"wirkmechanismus":"Soll die Leistungsfähigkeit von Nervenzellen verbessern. Piracetam ist chemisch ein zyklisches Derivat des Botenstoffs GABA, wirkt aber nicht über GABA-Rezeptoren. Es verbessert die Fliessfähigkeit von Zellmembranen und damit die Signalübertragung zwischen Nervenzellen. Zudem macht es rote Blutkörperchen verformbarer und hemmt die Zusammenballung der Blutplättchen, was die Durchblutung kleinster Gefässe fördert. Es wird unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Nervosität","Hyperkinesie (Bewegungsunruhe)","Gewichtszunahme"],"gelegentlich":["Depression","Schläfrigkeit (Somnolenz)","Schwäche (Asthenie)"],"unbekannt":["Blutungen (hämorrhagische Störungen)","Anaphylaktoide Reaktionen, Angioödem (Schwellung von Haut und Schleimhäuten)","Unruhe, Angst, Verwirrtheit, Halluzinationen","Gleichgewichtsstörungen, Schwindel, Kopfschmerzen, Schlaflosigkeit","Verschlechterung einer Epilepsie","Bauchschmerzen, Übelkeit, Erbrechen, Durchfall","Hautausschlag, Juckreiz, Nesselsucht"]},"schwangerschaft":"Piracetam passiert die Plazenta; nur anwenden, wenn unbedingt erforderlich.","stillzeit":"Geht in die Muttermilch über; nicht anwenden oder abstillen.","hinweise":["Vor Operationen und Zahnbehandlungen die Einnahme angeben (Wirkung auf die Blutplättchen).","Bei Myoklonus nicht abrupt absetzen, sondern schrittweise nach ärztlicher Anweisung.","Kann Nervosität oder Schläfrigkeit verursachen; Vorsicht beim Autofahren."],"darreichung":["Filmtabletten","Lösung zum Einnehmen"]},"pirfenidon":{"wirkmechanismus":"Bremst das Fortschreiten der Vernarbung des Lungengewebes. Der genaue Wirkmechanismus ist nicht vollständig geklärt: Pirfenidon wirkt antifibrotisch und entzündungshemmend, vermindert die Bildung von Wachstumsfaktoren wie TGF-beta sowie die Vermehrung von Fibroblasten und die Kollagenbildung. Es verlangsamt den Rückgang der Lungenfunktion (forcierte Vitalkapazität), heilt die Fibrose aber nicht.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Durchfall, Dyspepsie (Verdauungsbeschwerden), Sodbrennen (Reflux)","Appetitlosigkeit und Gewichtsverlust","Hautausschlag","Müdigkeit","Kopfschmerzen, Schwindel","Schlaflosigkeit"],"haeufig":["Lichtempfindlichkeitsreaktionen der Haut, Sonnenbrand","Juckreiz, Hautrötung, trockene Haut","Erhöhte Leberwerte (ALT, AST, GGT)","Erbrechen, Verstopfung, Bauchschmerzen, Blähungen","Geschmacksstörungen, Schläfrigkeit","Muskel- und Gelenkschmerzen","Infektionen der oberen Atemwege, Harnwegsinfekte","Hitzewallungen"],"gelegentlich":["Arzneimittelbedingte Leberschädigung, Bilirubinanstieg mit erhöhten Leberwerten","Agranulozytose (starker Mangel an weissen Blutkörperchen)","Angioödem (Schwellung von Gesicht, Lippen, Zunge)","Hyponatriämie (Natriummangel)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; zur Vorsicht während der Schwangerschaft nicht anwenden.","stillzeit":"Geht im Tierversuch in die Milch über. Es muss entschieden werden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Mit einer Mahlzeit einnehmen – das vermindert Übelkeit und Schwindel.","Sonne und Solarium meiden; Sonnenschutz mit hohem UVA- und UVB-Schutz und schützende Kleidung tragen.","Leberwerte regelmässig kontrollieren lassen. Nicht rauchen, da Rauchen die Wirkung abschwächt.","Grapefruitsaft meiden (erhöht die Pirfenidon-Spiegel)."],"darreichung":["Filmtabletten","Kapseln"]},"piritramid":{"wirkmechanismus":"Lindert starke Schmerzen, indem es die Schmerzweiterleitung und -wahrnehmung im Nervensystem dämpft. Piritramid ist ein reiner Agonist am µ-Opioidrezeptor; 15 mg entsprechen etwa 10 mg Morphin. Es wirkt zusätzlich beruhigend und löst vergleichsweise selten Übelkeit und Erbrechen aus. Die Wirkung hält nach intravenöser Gabe etwa 4–6 Stunden an; der Abbau erfolgt in der Leber.","nebenwirkungen":{"unbekannt":["Müdigkeit, Benommenheit, Schwindel","Übelkeit, Erbrechen","Blutdruckabfall, langsamer Puls","Atemdepression (abgeflachte Atmung)","Juckreiz, Schwitzen, Hautrötung","Obstipation (Verstopfung), Harnverhalt","Allergische Reaktionen","Abhängigkeit und Entzugssymptome bei längerer Anwendung"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Gabe kurz vor oder während der Geburt kann beim Neugeborenen eine Atemdepression auftreten.","stillzeit":"Ungenügende Daten; nur nach ärztlicher Abwägung – Säugling auf Schläfrigkeit und Trinkschwäche beobachten.","hinweise":["Kein Alkohol und keine anderen Beruhigungsmittel ohne ärztliche Rücksprache (Gefahr einer Atemlähmung).","Nach der Anwendung nicht Auto fahren und keine Maschinen bedienen.","Untersteht dem Betäubungsmittelgesetz."],"darreichung":["Injektionslösung"]},"piroxicam":{"wirkmechanismus":"Lindert Schmerzen und Entzündungen, indem es die Bildung von Prostaglandinen hemmt. Piroxicam hemmt die Cyclooxygenasen COX-1 und COX-2. Wegen seiner langen Halbwertszeit von rund 50 Stunden genügt eine Einnahme pro Tag, Nebenwirkungen klingen aber auch nur langsam ab. Im Vergleich zu anderen NSAR ist das Risiko für Magen-Darm-Komplikationen und schwere Hautreaktionen erhöht.","nebenwirkungen":{"haeufig":["Appetitlosigkeit","Schwindel, Kopfschmerzen","Ohrensausen (Tinnitus), Drehschwindel","Magen-Darm-Beschwerden: Übelkeit, Bauchschmerzen, Verstopfung, Durchfall, Blähungen, Dyspepsie (Verdauungsbeschwerden)","Juckreiz, Hautausschlag","Ödeme (Wassereinlagerungen)"],"gelegentlich":["Schläfrigkeit","Verschwommenes Sehen","Herzklopfen","Entzündung der Mundschleimhaut (Stomatitis)"],"sehrSelten":["Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"],"unbekannt":["Magen-Darm-Geschwüre, -Blutungen und -Durchbrüche","Lichtempfindlichkeit (Photosensibilität), DRESS, fixes Arzneimittelexanthem","Agranulozytose, aplastische Anämie, Thrombozytopenie","Hepatitis, Gelbsucht","Nierenfunktionsstörungen bis Nierenversagen","Anaphylaxie, Bronchospasmus","Herzinsuffizienz, erhöhtes Risiko für Herzinfarkt und Schlaganfall"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach strenger ärztlicher Abwägung; ab der 20. Woche können NSAR die Nierenfunktion des Ungeborenen beeinträchtigen. Im letzten Drittel kontraindiziert.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; in der Stillzeit nicht empfohlen.","hinweise":["Höchstdosis 20 mg pro Tag; die Behandlung soll nach 14 Tagen ärztlich überprüft werden.","Mit einer Mahlzeit einnehmen; nicht mit anderen Schmerzmitteln aus der NSAR-Gruppe kombinieren.","Bei Hautausschlag, Blasen oder Schleimhautveränderungen sofort absetzen und ärztlichen Rat einholen.","Starke Sonne meiden und Sonnenschutz verwenden."],"darreichung":["Kapseln","Schmelztabletten"]},"pirtobrutinib":{"wirkmechanismus":"Bremst das Wachstum und Überleben bösartiger B-Lymphozyten, auch wenn andere BTK-Hemmer nicht mehr wirken. Pirtobrutinib hemmt die Bruton-Tyrosinkinase (BTK) reversibel, also ohne feste (kovalente) Bindung. Es wirkt daher auch bei Mutationen an der Bindungsstelle C481, die gegen Ibrutinib, Acalabrutinib oder Zanubrutinib resistent machen.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Anämie, Thrombozytopenie (Mangel an Blutzellen)","Infektionen (Lungenentzündung, obere Atemwege, Harnwege)","Müdigkeit","Durchfall, Übelkeit, Bauchschmerzen","Blutergüsse und Blutungen","Muskel- und Gelenkschmerzen","Husten, Kopfschmerzen","Hautausschlag, periphere Ödeme (Wassereinlagerungen)"],"haeufig":["Vorhofflimmern oder -flattern","Bluthochdruck","Nasenbluten, Blut im Urin","Weisser Hautkrebs (nicht-melanozytärer Hautkrebs) und andere Zweittumoren"],"unbekannt":["Hirnblutung","Reaktivierung einer Hepatitis B"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen müssen während und bis 1 Woche nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 1 Woche nach der letzten Dosis nicht stillen.","hinweise":["Einmal täglich zur gleichen Zeit einnehmen, mit oder ohne Essen; Tabletten ganz schlucken.","Vor Operationen und Zahneingriffen die Behandlung angeben.","Herzklopfen, Blutungen, Fieber oder Infektzeichen sofort ärztlich melden.","Konsequenter Sonnenschutz; regelmässige Blutbildkontrollen."],"darreichung":["Filmtabletten"]},"pitavastatin":{"wirkmechanismus":"Senkt das LDL-Cholesterin, indem es die Cholesterinbildung in der Leber hemmt. Pitavastatin hemmt kompetitiv die HMG-CoA-Reduktase; die Leber bildet dadurch mehr LDL-Rezeptoren und nimmt mehr LDL-Cholesterin aus dem Blut auf. Es wird über den Transporter OATP1B1 in die Leber aufgenommen, kaum über Cytochrom-P450-Enzyme abgebaut und hauptsächlich als Glucuronid ausgeschieden.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Verstopfung, Durchfall","Dyspepsie (Verdauungsbeschwerden), Übelkeit","Myalgie (Muskelschmerzen), Arthralgie (Gelenkschmerzen)"],"gelegentlich":["Anämie (Blutarmut), Appetitlosigkeit","Schlaflosigkeit","Schwindel, Geschmacksstörungen, Schläfrigkeit","Tinnitus (Ohrensausen)","Bauchschmerzen, Mundtrockenheit, Erbrechen","Juckreiz, Hautausschlag","Muskelkrämpfe, häufiges Wasserlassen","Müdigkeit, Schwäche, Ödeme"],"selten":["Verminderte Sehschärfe","Akute Pankreatitis","Gelbsucht durch Gallenstau, Leberfunktionsstörung","Nesselsucht, Hautrötung","Myopathie, Rhabdomyolyse (Muskelzerfall)"],"unbekannt":["Immunvermittelte nekrotisierende Myopathie","Diabetes mellitus","Interstitielle Lungenerkrankung","Depression, Albträume","Gedächtnisstörungen","Myasthenia gravis"]},"schwangerschaft":"Kontraindiziert; Frauen im gebärfähigen Alter müssen zuverlässig verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Einmal täglich zu beliebiger Tageszeit, mit oder ohne Mahlzeit einnehmen.","Ungeklärte Muskelschmerzen, -schwäche oder -krämpfe, besonders mit Fieber oder dunklem Urin, sofort ärztlich melden.","Leberwerte vor Beginn und bei Bedarf kontrollieren."],"darreichung":["Filmtabletten"]},"pitolisant":{"wirkmechanismus":"Fördert die Wachheit, indem es die Aktivität histaminbildender Nervenzellen im Gehirn steigert. Pitolisant blockiert als Antagonist und inverser Agonist die Histamin-H3-Autorezeptoren, die normalerweise die Histaminfreisetzung bremsen. Die vermehrte Histaminausschüttung aktiviert wachheitsfördernde Systeme und steigert in der Hirnrinde auch die Freisetzung von Acetylcholin, Noradrenalin und Dopamin. Ein relevantes Missbrauchspotenzial wurde in Studien nicht beobachtet.","nebenwirkungen":{"haeufig":["Schlaflosigkeit, Schlafstörungen","Angst, Reizbarkeit","Depression","Kopfschmerzen","Schwindel, Zittern","Übelkeit, Erbrechen, Bauchschmerzen","Müdigkeit"],"gelegentlich":["Verlängerte QT-Zeit im EKG","Herzklopfen, Herzrasen","Gewichtszunahme oder -abnahme, Appetitveränderungen"]},"schwangerschaft":"Nur wenn eindeutig erforderlich. Frauen im gebärfähigen Alter müssen während und bis 21 Tage nach der Behandlung zuverlässig verhüten; hormonale Methoden allein genügen nicht.","stillzeit":"Kontraindiziert.","hinweise":["Einmal täglich morgens zum Frühstück einnehmen, nicht später am Tag (Schlafstörungen).","Stimmungsveränderungen oder Suizidgedanken sofort ärztlich melden.","Die volle Wirkung baut sich über einige Wochen auf."],"darreichung":["Filmtabletten"]},"pivmecillinam":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand stört. Pivmecillinam ist eine Vorstufe (Prodrug): Bei der Aufnahme aus dem Darm wird es zum wirksamen Mecillinam gespalten, das sich im Urin stark anreichert. Mecillinam bindet bevorzugt an das Penicillin-bindende Protein 2 (PBP-2) gramnegativer Bakterien wie Escherichia coli, Klebsiellen und Proteus. Gegen Enterokokken und Pseudomonas wirkt es nicht.","nebenwirkungen":{"haeufig":["Durchfall","Übelkeit","Scheidenpilz (vulvovaginale Candidose)"],"gelegentlich":["Erbrechen, Bauchschmerzen, Verdauungsbeschwerden","Kopfschmerzen, Schwindel","Hautausschlag, Nesselsucht, Juckreiz","Müdigkeit"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Speiseröhrenentzündung und -geschwüre","Pseudomembranöse Kolitis (schwere Darmentzündung)","Carnitinmangel","Leberfunktionsstörungen","Thrombozytopenie (Mangel an Blutplättchen)"]},"schwangerschaft":"Kann nach ärztlicher Verordnung angewendet werden: Umfangreiche Erfahrungen zeigen kein erhöhtes Risiko für das Kind.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung möglich. Beim Säugling auf Durchfall oder Pilzbefall achten.","hinweise":["Während oder nach einer Mahlzeit mit mindestens einem halben Glas Wasser im Sitzen oder Stehen einnehmen, nicht unmittelbar vor dem Hinlegen.","Die verordnete Behandlung vollständig durchführen.","Bei Fieber, Flankenschmerzen oder fehlender Besserung nach 2–3 Tagen ärztlich abklären lassen."],"darreichung":["Filmtabletten"]},"plerixafor":{"wirkmechanismus":"Löst blutbildende Stammzellen aus ihrer Verankerung im Knochenmark, sodass sie ins Blut übertreten. Plerixafor blockiert reversibel den Chemokinrezeptor CXCR4 auf den Stammzellen und verhindert dessen Bindung an den Botenstoff SDF-1α (CXCL12), der die Zellen im Knochenmark festhält. Die Zahl der CD34-positiven Stammzellen im Blut steigt innerhalb weniger Stunden an; zusammen mit G-CSF lassen sich so mehr Zellen sammeln.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Übelkeit","Reaktionen an der Injektionsstelle (Rötung, Schmerz, Juckreiz)"],"haeufig":["Kopfschmerzen, Schwindel","Schlaflosigkeit","Bauchschmerzen, Erbrechen, Blähungen, Verdauungsbeschwerden, Verstopfung","Mundtrockenheit, Taubheitsgefühl im Mund","Vermehrtes Schwitzen, Hautrötung","Gelenk- und Muskelschmerzen","Müdigkeit, Unwohlsein"],"gelegentlich":["Allergische Reaktionen, Anaphylaxie bis anaphylaktischer Schock","Abnorme Träume, Albträume"],"unbekannt":["Milzvergrösserung (Splenomegalie) und Milzriss","Kreislaufreaktionen mit Blutdruckabfall und Ohnmacht"]},"schwangerschaft":"Nicht anwenden, ausser wenn unbedingt nötig; im Tierversuch fruchtschädigend. Frauen im gebärfähigen Alter müssen während und bis 1 Woche nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Wird nach mehrtägiger Vorbehandlung mit G-CSF etwa 6–11 Stunden vor der geplanten Stammzellsammlung gespritzt.","Bei Schwindel oder Schwäche nach der Injektion hinlegen und melden.","Schmerzen im linken Oberbauch oder in der linken Schulter sofort ärztlich abklären lassen."],"darreichung":["Injektionslösung (subkutan)"]},"pneumokokken-konjugatimpfstoff":{"wirkmechanismus":"Regt das Immunsystem an, Schutzstoffe gegen die häufigsten krankmachenden Pneumokokken-Typen zu bilden. Der Impfstoff enthält die Zuckerhüllen (Kapselpolysaccharide) von 13, 15 oder 20 Pneumokokken-Serotypen, gekoppelt an das ungiftige Diphtherie-Trägereiweiss CRM197. Die Koppelung führt zu einer starken, T-Zell-abhängigen Immunantwort mit Gedächtniszellen – auch bei Säuglingen, die auf reine Polysaccharid-Impfstoffe kaum ansprechen.","nebenwirkungen":{"sehrHaeufig":["Schmerzen, Rötung, Schwellung oder Verhärtung an der Einstichstelle","Fieber (Kinder)","Kinder: Reizbarkeit, Schläfrigkeit, unruhiger Schlaf, verminderter Appetit","Erwachsene: Kopfschmerzen, Müdigkeit, Muskel- und Gelenkschmerzen"],"haeufig":["Fieber über 39 °C bei Kindern","Erbrechen, Durchfall","Hautausschlag","Schüttelfrost (Erwachsene)"],"gelegentlich":["Krampfanfälle einschliesslich Fieberkrämpfe","Nesselsucht","Anhaltendes Schreien bei Säuglingen"],"selten":["Überempfindlichkeitsreaktionen mit Gesichtsschwellung, Atemnot, Bronchospasmus","Kollaps mit verminderter Ansprechbarkeit (hypoton-hyporesponsive Episode) bei Säuglingen"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Geschwollene Lymphknoten","Atempausen (Apnoe) bei sehr unreifen Frühgeborenen"]},"schwangerschaft":"Daten begrenzt; Impfung in der Schwangerschaft nur bei klarer Indikation nach ärztlicher Abwägung.","stillzeit":"Impfung in der Stillzeit möglich, wenn angezeigt.","hinweise":["Impfschema gemäss Schweizerischem Impfplan: Säuglinge ab 2 Monaten, Erwachsene ab 65 Jahren und Personen mit Risikofaktoren.","Kann gleichzeitig mit anderen Impfungen gegeben werden (an verschiedenen Stellen).","Nach der Impfung etwa 15 Minuten in der Praxis bleiben."],"darreichung":["Injektionssuspension (Fertigspritze, intramuskulär)"]},"pneumokokken-polysaccharidimpfstoff-23-valent":{"wirkmechanismus":"Regt das Immunsystem an, Abwehrstoffe gegen die Kapseln von 23 häufigen Pneumokokken-Typen zu bilden. Der Impfstoff enthält gereinigte Kapsel-Polysaccharide, die B-Zellen ohne Hilfe von T-Zellen aktivieren. Deshalb entsteht kaum ein immunologisches Gedächtnis, und bei Kindern unter 2 Jahren wirkt der Impfstoff nicht zuverlässig. Gegen nicht enthaltene Serotypen schützt er nicht.","nebenwirkungen":{"sehrHaeufig":["Schmerzen, Rötung, Wärme, Schwellung und Verhärtung an der Einstichstelle","Fieber (bis 38,8 °C)"],"selten":["Entzündung des Unterhautgewebes an der Einstichstelle (Cellulitis-ähnliche Reaktion)"],"unbekannt":["Schwäche, Schüttelfrost, Unwohlsein, Kopfschmerzen","Gelenk- und Muskelschmerzen, eingeschränkte Beweglichkeit des Arms","Lymphknotenschwellung","Thrombozytopenie bei Personen mit stabiler ITP, hämolytische Anämie","Allergische Reaktionen bis Anaphylaxie, Angioödem, Nesselsucht","Guillain-Barré-Syndrom, Kribbeln (Parästhesien), Fieberkrämpfe","Übelkeit, Erbrechen","Hautausschlag, Erythema multiforme"]},"schwangerschaft":"Nur bei klarer Notwendigkeit (hohes Erkrankungsrisiko) nach ärztlicher Abwägung impfen.","stillzeit":"Nicht bekannt, ob der Impfstoff in die Muttermilch übergeht; Anwendung nach ärztlicher Abwägung.","hinweise":["Für Risikogruppen werden heute in erster Linie Pneumokokken-Konjugatimpfstoffe empfohlen; den passenden Impfstoff ärztlich klären.","Vor einer geplanten Milzentfernung oder Chemotherapie möglichst mindestens 2 Wochen vorher impfen."],"darreichung":["Injektionslösung in Fertigspritze (intramuskulär oder unter die Haut)"]},"podophyllotoxin":{"wirkmechanismus":"Bringt Feigwarzen zum Absterben, indem es die Zellteilung im Warzengewebe stoppt. Podophyllotoxin ist ein gereinigter Pflanzeninhaltsstoff aus der Wurzel von Podophyllum; er bindet an Tubulin und verhindert den Aufbau des Spindelapparats (Mitosehemmung). Die sich rasch teilenden, virusinfizierten Zellen gehen zugrunde, und die Warzen bilden sich innerhalb einiger Tage zurück. Gegen das Humane Papillomavirus selbst wirkt es nicht.","nebenwirkungen":{"sehrHaeufig":["Örtliche Reizung (Rötung, Brennen, Schmerzen, Juckreiz), meist am 2. bis 3. Behandlungstag","Oberflächliche Hautdefekte (Erosionen) und Schwellung im behandelten Bereich"],"unbekannt":["Blutungen aus den behandelten Stellen","Vorhautentzündung (Balanoposthitis), Vorhautverengung (Phimose)","Allergische Hautreaktionen"]},"schwangerschaft":"Kontraindiziert, da Schäden für das ungeborene Kind nicht ausgeschlossen sind; während der Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Nur genau auf die Warzen auftragen, gesunde Haut nicht benetzen und die Lösung trocknen lassen; danach Hände waschen. Nicht in die Augen bringen.","Behandlungsschema und Höchstdauer genau nach Anweisung einhalten; sind die Warzen nach 4 Behandlungswochen nicht verschwunden, ärztlich neu beurteilen lassen.","Solange die Haut gereizt ist, auf Geschlechtsverkehr verzichten; Partnerin oder Partner ärztlich untersuchen lassen.","Kondome senken das Ansteckungsrisiko, schützen aber nicht vollständig vor HPV."],"darreichung":["Lösung zur Anwendung auf der Haut"]},"polatuzumab-vedotin":{"wirkmechanismus":"Bringt ein Zellgift gezielt in bösartige B-Zellen. Polatuzumab Vedotin besteht aus einem Antikörper gegen CD79b, einen Bestandteil des B-Zell-Rezeptors, und dem daran gekoppelten Zellgift Monomethylauristatin E (MMAE). Nach der Bindung wird das Konjugat in die Zelle aufgenommen; dort wird MMAE freigesetzt, hemmt die Mikrotubuli und stoppt die Zellteilung, worauf die Zelle abstirbt (Apoptose).","nebenwirkungen":{"sehrHaeufig":["Neutropenie, auch mit Fieber (febrile Neutropenie)","Thrombozytopenie, Anämie","Infektionen der oberen Atemwege, Lungenentzündung","Periphere Neuropathie (Kribbeln, Taubheit)","Durchfall, Übelkeit, Verstopfung, Erbrechen","Haarausfall (in Kombination mit Chemotherapie)","Müdigkeit, Fieber, Appetitlosigkeit, Gewichtsabnahme"],"haeufig":["Sepsis (Blutvergiftung)","Herpes- und Zytomegalie-Virusinfektionen","Pneumonitis (Lungenentzündung durch das Medikament)","Schwindel","Erhöhte Leberwerte","Infusionsbedingte Reaktionen, Schüttelfrost","Elektrolytstörungen (Kalium oder Calcium zu tief)"],"unbekannt":["Progressive multifokale Leukenzephalopathie (PML)","Tumorlysesyndrom"]},"schwangerschaft":"Kann das Ungeborene schädigen; in der Schwangerschaft nicht anwenden, ausser der Nutzen überwiegt klar. Frauen verhüten während und mindestens 9 Monate, Männer mindestens 6 Monate nach der letzten Dosis.","stillzeit":"Während und mindestens 3 Monate nach der letzten Dosis nicht stillen.","hinweise":["Fieber über 38 °C, Schüttelfrost oder Husten sofort melden (Infektionsgefahr).","Kribbeln, Taubheit oder Schwäche in Händen und Füssen melden.","Neue Verwirrtheit, Sprach-, Seh- oder Gangstörungen umgehend abklären lassen (PML).","Keine Lebendimpfungen während der Behandlung."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"policresulen":{"wirkmechanismus":"Stillt kleine Blutungen und wirkt desinfizierend. Policresulen ist eine stark saure Substanz, die Eiweisse in geschädigtem und abgestorbenem Gewebe ausfällt (koaguliert) und so kleine Gefässe verschliesst, während gesundes Gewebe weitgehend unberührt bleibt. Zusätzlich wirkt es gegen Bakterien und Pilze und unterstützt die Abheilung.","nebenwirkungen":{"unbekannt":["Lokales Brennen oder Reizgefühl, besonders zu Beginn der Behandlung","Allergische Hautreaktionen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur nach ärztlicher Rücksprache anwenden.","stillzeit":"Nur nach ärztlicher Rücksprache anwenden.","hinweise":["Nach dem Stuhlgang und nach schonender Reinigung der Analregion anwenden.","Bei Blut im Stuhl oder fehlender Besserung nach einer Woche ärztlich abklären lassen."],"darreichung":["Salbe","Zäpfchen"]},"polidocanol":{"wirkmechanismus":"Verklebt und verschliesst die behandelte Vene. Polidocanol ist eine oberflächenaktive Substanz, die nach der Injektion die Innenwand (Endothel) der Vene schädigt; es bildet sich ein Gerinnsel, das die Vene verschliesst und später zu Bindegewebe umgebaut wird. Als Schaum aufbereitet verdrängt es das Blut und eignet sich auch für grössere Venen. Daneben wirkt Polidocanol örtlich betäubend.","nebenwirkungen":{"haeufig":["Blutergüsse (Hämatome) und Schmerzen an der Injektionsstelle","Bräunliche Hautverfärbung (Hyperpigmentierung)","Neue feine Äderchen (Matting)","Kleine Blutgerinnsel in der behandelten Vene"],"gelegentlich":["Oberflächliche Venenentzündung (Thrombophlebitis)","Allergische Hautreaktionen, Rötung","Hautnekrose (Absterben von Haut) an der Injektionsstelle","Verhärtung und Schwellung"],"selten":["Tiefe Venenthrombose","Schmerzen in den Beinen"],"sehrSelten":["Lungenembolie","Schlaganfall oder vorübergehende Durchblutungsstörung des Gehirns","Sehstörungen, Migräne, Kribbeln","Anaphylaxie (schwere allergische Reaktion), Angioödem","Herzrhythmusstörungen, Herzstillstand","Atemnot, Brustenge"]},"schwangerschaft":"Nicht anwenden, ausser es ist eindeutig erforderlich; Verödungen werden in der Regel auf die Zeit nach der Schwangerschaft verschoben.","stillzeit":"Keine Daten; ist eine Verödung nötig, wird eine Stillpause von 2–3 Tagen empfohlen.","hinweise":["Nach der Verödung Kompressionsstrümpfe oder -verband wie verordnet tragen und sich regelmässig bewegen.","In den ersten Tagen langes Stehen, Sauna, heisse Bäder und intensive Sonne meiden.","Bei Sehstörungen, Atemnot, Brustschmerzen, Lähmungen oder Sprachstörungen sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung"]},"poliomyelitis-impfstoff-inaktiviert":{"wirkmechanismus":"Lehrt das Immunsystem, Polioviren zu erkennen und abzuwehren. Der Impfstoff enthält abgetötete (inaktivierte) Polioviren der Typen 1, 2 und 3, die keine Erkrankung auslösen können. Er regt die Bildung neutralisierender Antikörper an, die vor der Lähmungsform der Kinderlähmung schützen. Anders als die früher verwendete Schluckimpfung enthält er keine vermehrungsfähigen Viren.","nebenwirkungen":{"sehrHaeufig":["Schmerzen an der Einstichstelle"],"haeufig":["Rötung an der Einstichstelle","Fieber"],"gelegentlich":["Verhärtung oder Schwellung an der Einstichstelle"],"unbekannt":["Lymphknotenschwellung","Anaphylaxie und andere allergische Reaktionen (Ausschlag, Nesselsucht)","Kopfschmerzen, Kribbeln (Parästhesien)","Krampfanfälle (meist mit Fieber)","Gelenk- und Muskelschmerzen","Unruhe, Schläfrigkeit oder Reizbarkeit bei Kleinkindern"]},"schwangerschaft":"Als Totimpfstoff ist keine Schädigung zu erwarten, die Daten sind aber begrenzt: nur bei klarer Indikation (z. B. unaufschiebbare Reise in ein Risikogebiet) nach ärztlicher Abwägung.","stillzeit":"Anwendung möglich; ein Risiko für den gestillten Säugling ist nicht bekannt.","hinweise":["Säuglinge und Kleinkinder erhalten den Polioschutz in der Schweiz meist mit einem Kombinationsimpfstoff (5- oder 6-fach-Impfstoff).","Vor Reisen in Länder mit Poliorisiko Auffrischimpfung prüfen lassen, wenn die letzte Dosis mehr als 10 Jahre zurückliegt.","Wegen möglicher Ohnmacht nach der Spritze kurz sitzen bleiben."],"darreichung":["Injektionssuspension (Fertigspritze)"]},"polystyrolsulfonat":{"wirkmechanismus":"Bindet im Darm Kalium und sorgt dafür, dass es mit dem Stuhl ausgeschieden statt ins Blut aufgenommen wird. Polystyrolsulfonat ist ein nicht resorbierbares Kationenaustauscherharz, das Natrium- bzw. Calciumionen gegen Kaliumionen austauscht, vor allem im Dickdarm. Die Wirkung setzt erst nach Stunden ein; für die Notfallbehandlung einer lebensbedrohlichen Hyperkaliämie reicht es allein nicht aus.","nebenwirkungen":{"unbekannt":["Hypokaliämie (Kaliummangel) sowie Störungen von Calcium, Magnesium und Natrium","Übelkeit, Erbrechen, Appetitlosigkeit, Magenreizung","Verstopfung, gelegentlich Durchfall","Kotsteine (Bezoare) und Darmverschluss","Darmgeschwüre, ischämische Kolitis, Darmnekrose und Darmdurchbruch","Bronchitis oder Lungenentzündung durch eingeatmetes Pulver","Natriumüberladung mit Ödemen (Natriumsalz) bzw. Hyperkalzämie (Calciumsalz)"]},"schwangerschaft":"Keine ausreichenden Daten; das Harz wird nicht ins Blut aufgenommen. Anwendung nur nach ärztlicher Abwägung.","stillzeit":"Wird nicht ins Blut aufgenommen; Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Pulver in Wasser oder etwas gesüsster Flüssigkeit aufschwemmen – nicht in kaliumreichem Fruchtsaft und nicht mit Sorbitol.","Kalium und weitere Blutsalze regelmässig kontrollieren lassen.","Bei Verstopfung, Bauchschmerzen oder Blut im Stuhl ärztlich melden."],"darreichung":["Pulver zum Einnehmen oder zur rektalen Anwendung (Einlauf)"]},"pomalidomid":{"wirkmechanismus":"Hemmt das Wachstum von Myelomzellen und aktiviert Abwehrzellen. Pomalidomid bindet an das Protein Cereblon und führt zum Abbau der Transkriptionsfaktoren Ikaros und Aiolos. Es wirkt direkt wachstumshemmend auf Myelomzellen, aktiviert T-Zellen und natürliche Killerzellen und hemmt die Gefässneubildung. Mit Dexamethason ergibt sich eine verstärkte Wirkung gegen die Tumorzellen.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Thrombozytopenie, Anämie (Blutbildveränderungen)","Lungenentzündung und andere Atemwegsinfekte","Müdigkeit, Fieber, periphere Ödeme","Atemnot, Husten","Durchfall, Verstopfung, Übelkeit","Appetitlosigkeit","Muskelkrämpfe"],"haeufig":["Febrile Neutropenie (Fieber bei Mangel an weissen Blutkörperchen), Sepsis","Tiefe Venenthrombose, Lungenembolie","Periphere Neuropathie, Schwindel, Zittern","Verwirrtheit, Bewusstseinsminderung","Vorhofflimmern, Herzschwäche","Nierenversagen, Harnverhalt","Hautausschlag, Juckreiz","Herpes zoster (Gürtelrose)"],"gelegentlich":["Tumorlyse-Syndrom","Reaktivierung einer Hepatitis B","Hirnblutung, Schlaganfall","Hepatitis, erhöhte Leberwerte","Weisser Hautkrebs (Basalzell- und Plattenepithelkarzinom)","Angioödem, Nesselsucht"],"unbekannt":["Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Leberversagen","Abstossung transplantierter Organe","Schilddrüsenunterfunktion"]},"schwangerschaft":"Kontraindiziert: Pomalidomid ist mit Thalidomid verwandt und muss als stark fruchtschädigend gelten. Frauen im gebärfähigen Alter müssen von 4 Wochen vor bis 4 Wochen nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung darf nicht gestillt werden.","hinweise":["Strenges Schwangerschaftsverhütungsprogramm: Frauen verhüten von 4 Wochen vor bis 4 Wochen nach der Therapie; Männer verwenden während und bis 7 Tage nach der Therapie Kondome.","Während und bis 7 Tage nach der Behandlung kein Blut und keinen Samen spenden. Kapseln nicht öffnen oder zerkauen und nicht weitergeben.","Bei Fieber, Halsschmerzen, Blutungen, Atemnot oder geschwollenen Beinen sofort ärztliche Hilfe holen.","Regelmässige Blutbildkontrollen sind nötig."],"darreichung":["Kapseln"]},"ponatinib":{"wirkmechanismus":"Blockiert gezielt das krankhafte Enzym, das Leukämiezellen wachsen lässt – auch in seinen resistenten Formen. Ponatinib ist ein BCR-ABL-Hemmer der dritten Generation, der auch die T315I-Mutation hemmt, gegen die ältere Tyrosinkinasehemmer unwirksam sind. Zusätzlich hemmt es weitere Kinasen wie VEGF-, FGF- und PDGF-Rezeptoren, SRC und KIT; dies erklärt Gefäss-Nebenwirkungen wie Bluthochdruck und Gefässverschlüsse.","nebenwirkungen":{"sehrHaeufig":["Bluthochdruck","Hautausschlag, trockene Haut","Bauchschmerzen, Verstopfung, Übelkeit","Kopfschmerzen, Müdigkeit","Gelenk- und Muskelschmerzen","Blutarmut, Mangel an Blutplättchen und weissen Blutkörperchen","Erhöhte Lipase- und Leberwerte","Infekte der oberen Atemwege"],"haeufig":["Arterielle Gefässverschlüsse: Herzinfarkt, Angina pectoris, Schlaganfall, Durchblutungsstörungen der Beine","Herzschwäche, Vorhofflimmern","Venöse Thrombosen und Lungenembolie","Pankreatitis (Bauchspeicheldrüsenentzündung)","Blutungen","Pleuraerguss (Wasser im Brustfell), Atemnot","Erhöhter Blutzucker","Schilddrüsenunterfunktion"],"gelegentlich":["Verschluss von Netzhautgefässen (Sehstörungen)","Leberschädigung bis Leberversagen, Gelbsucht","Tumorlyse-Syndrom","Hypertensive Krise (Blutdruckentgleisung)"],"unbekannt":["Posteriores reversibles Enzephalopathie-Syndrom (PRES: Kopfschmerzen, Verwirrtheit, Sehstörungen, Krampfanfälle)","Reaktivierung einer Hepatitis B","Schwere Hautreaktionen (z. B. Stevens-Johnson-Syndrom)","Aneurysmen und Einrisse der Gefässwand (Arteriendissektion)"]},"schwangerschaft":"Nicht anwenden, ausser es ist zwingend notwendig (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Blutdruck, Herz-Kreislauf-Risikofaktoren und Blutfette vor und während der Behandlung kontrollieren und behandeln.","Brustschmerzen, Lähmungen, Sprach- oder Sehstörungen sowie Schmerzen oder Kälte in den Beinen sofort als Notfall ärztlich abklären lassen.","Einmal täglich unabhängig von den Mahlzeiten einnehmen; keine Grapefruit und kein Johanniskraut.","Blutbild, Lipase und Leberwerte regelmässig kontrollieren."],"darreichung":["Filmtabletten"]},"ponesimod":{"wirkmechanismus":"Hält bestimmte weisse Blutkörperchen in den Lymphknoten zurück, damit sie nicht ins Gehirn und Rückenmark gelangen. Ponesimod bindet selektiv an den Sphingosin-1-Phosphat-Rezeptor 1 (S1P1) auf Lymphozyten und bewirkt dessen Internalisierung; die Lymphozyten können die Lymphknoten nicht mehr verlassen und ihre Zahl im Blut sinkt. Wegen der relativ kurzen Halbwertszeit (etwa 33 Stunden) erholt sich die Lymphozytenzahl nach dem Absetzen meist innerhalb einer Woche.","nebenwirkungen":{"sehrHaeufig":["Nasen-Rachen-Entzündung (Erkältung)","Infektionen der oberen Atemwege","Erhöhte Leberwerte (ALT)"],"haeufig":["Harnwegsinfekte, Bronchitis, Grippe","Gürtelrose (Herpes zoster)","Lymphopenie (Mangel an Lymphozyten)","Depression, Schlafstörungen, Angst","Schwindel, Migräne","Pulsverlangsamung (Bradykardie)","Bluthochdruck","Husten, Atemnot"],"gelegentlich":["Makulaödem (Schwellung der Netzhautmitte)"],"unbekannt":["PML und Kryptokokken-Infektionen","Hautkrebs","PRES (posteriores reversibles Enzephalopathie-Syndrom)","Schwere Verschlechterung der MS nach dem Absetzen"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter müssen während und mindestens 1 Woche nach dem Absetzen zuverlässig verhüten.","stillzeit":"Nicht stillen während der Behandlung.","hinweise":["Einschleichende Dosierung über 14 Tage mit Starterpackung; nach einem Therapieunterbruch (je nach Dauer) erneut einschleichend beginnen.","EKG vor Beginn; Blutbild, Leberwerte und Blutdruck regelmässig kontrollieren.","Nicht eigenmächtig absetzen; bei Sehstörungen, Fieber oder neuen neurologischen Beschwerden ärztlich abklären lassen."],"darreichung":["Filmtabletten"]},"poractant-alfa":{"wirkmechanismus":"Ersetzt den fehlenden Oberflächenfilm der Lungenbläschen, damit diese beim Ausatmen nicht zusammenfallen. Poractant alfa ist ein aus Schweinelungen gewonnenes natürliches Surfactant aus Phospholipiden und den Surfactant-Proteinen SP-B und SP-C. Es senkt die Oberflächenspannung in den Alveolen, stabilisiert sie und verbessert so Gasaustausch und Sauerstoffversorgung. Frühgeborene bilden oft noch zu wenig eigenes Surfactant.","nebenwirkungen":{"gelegentlich":["Sepsis (Blutvergiftung)","Hirnblutung (intraventrikuläre Blutung)","Pneumothorax (Luft im Brustfellraum)"],"selten":["Bradykardie (verlangsamter Herzschlag)","Hypotonie (tiefer Blutdruck)","Bronchopulmonale Dysplasie (chronische Lungenerkrankung)","Lungenblutung","Abfall der Sauerstoffsättigung"],"unbekannt":["Hyperoxie (zu hoher Sauerstoffgehalt im Blut)","Zyanose (Blaufärbung)","Atempausen (Apnoe)","Verlegung des Beatmungstubus","Auffälliges EEG"]},"schwangerschaft":"Nicht zutreffend: Das Mittel wird nur bei Neugeborenen angewendet.","stillzeit":"Nicht zutreffend: Das Mittel wird nur bei Neugeborenen angewendet.","hinweise":["Wird im Spital über den Beatmungsschlauch (Tubus) oder eine dünne Sonde direkt in die Luftröhre gegeben; Herzfrequenz und Sauerstoffsättigung werden laufend überwacht."],"darreichung":["Suspension zur intratrachealen Anwendung"]},"posaconazol":{"wirkmechanismus":"Hemmt die Bildung eines wichtigen Bausteins der Pilzzellwand und stoppt so das Wachstum von Hefe- und Schimmelpilzen. Posaconazol blockiert die pilzeigene Lanosterol-14α-Demethylase; dadurch fehlt Ergosterol in der Zellmembran und toxische Sterolvorstufen reichern sich an. Es wirkt auch gegen viele Mucorales (Jochpilze). Posaconazol ist ein starker Hemmer von CYP3A4 und wird selbst über Glucuronidierung (UGT) und P-Glykoprotein ausgeschieden.","nebenwirkungen":{"haeufig":["Neutropenie (Mangel an weissen Blutkörperchen)","Elektrolytstörungen, Appetitlosigkeit","Kopfschmerzen, Schwindel, Kribbeln, Schläfrigkeit, Geschmacksstörungen","Bluthochdruck","Übelkeit, Erbrechen, Bauchschmerzen, Durchfall, Verdauungsbeschwerden, Mundtrockenheit, Blähungen, Verstopfung","Erhöhte Leberwerte","Hautausschlag, Juckreiz","Fieber, Schwäche, Müdigkeit"],"gelegentlich":["Thrombozytopenie, Leukopenie, Anämie, Eosinophilie","Allergische Reaktionen","Hyperglykämie, Hypoglykämie","Krampfanfälle, Neuropathie, Zittern","Verschwommenes Sehen, Lichtscheu","QT-Verlängerung, Herzklopfen, Bradykardie, Tachykardie","Pankreatitis","Hepatitis, Gelbsucht, Leberschäden","Haarausfall","Akutes Nierenversagen, Niereninsuffizienz","Menstruationsstörungen"],"selten":["Hämolytisch-urämisches Syndrom, thrombotisch-thrombozytopenische Purpura, Panzytopenie","Nebenniereninsuffizienz","Psychose, Depression","Schlaganfall, Enzephalopathie, Ohnmacht","Doppelbilder, Hörstörungen","Torsade de pointes, plötzlicher Herztod, Herzinsuffizienz, Herzinfarkt","Lungenembolie, Thrombose, Pneumonitis","Magen-Darm-Blutung, Darmverschluss","Leberversagen","Stevens-Johnson-Syndrom"],"unbekannt":["Pseudoaldosteronismus (Bluthochdruck mit Kaliummangel)"]},"schwangerschaft":"Nicht anwenden, ausser der Nutzen überwiegt eindeutig das Risiko (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter müssen wirksam verhüten.","stillzeit":"Mit Beginn der Behandlung abstillen.","hinweise":["Suspension immer mit einer Mahlzeit oder einem Nahrungsergänzungsgetränk einnehmen; Tabletten unzerkaut mit einer Mahlzeit schlucken.","Tabletten und Suspension sind nicht 1:1 austauschbar – nur die verordnete Form verwenden.","Vor jedem neuen Medikament die Posaconazol-Behandlung erwähnen: viele Kombinationen sind verboten.","Leberwerte, Elektrolyte und Blutdruck werden regelmässig kontrolliert."],"darreichung":["Magensaftresistente Tabletten","Suspension zum Einnehmen","Konzentrat zur Herstellung einer Infusionslösung"]},"povidon-iod":{"wirkmechanismus":"Tötet Krankheitserreger auf Haut, Schleimhaut und in Wunden ab. Povidon-Iod ist ein Komplex aus dem Trägerstoff Povidon und Iod, der laufend kleine Mengen freies Iod abgibt. Freies Iod oxidiert und iodiert Eiweisse, Enzyme und Membranbestandteile der Mikroorganismen und wirkt so rasch gegen Bakterien, Pilze, viele Viren und Protozoen; Resistenzen sind nicht bekannt. Durch die langsame Freisetzung ist es besser verträglich als alkoholische Iodlösung. Über Wunden und Schleimhäute kann jedoch Iod in den Körper aufgenommen werden.","nebenwirkungen":{"selten":["Überempfindlichkeitsreaktionen der Haut (Kontaktdermatitis mit Rötung, Bläschen, Juckreiz)"],"sehrSelten":["Anaphylaxie, Angioödem (akute allergische Reaktionen)","Schilddrüsenüberfunktion durch Iod bei vorbestehender Schilddrüsenerkrankung"],"unbekannt":["Schilddrüsenunterfunktion nach längerer oder grossflächiger Anwendung","Störungen von Elektrolyt- und Säure-Basen-Haushalt, Nierenfunktionsstörung bis Nierenversagen (nach Anwendung auf grossen Flächen, z. B. Verbrennungen)","Hautreizung bis Verätzung, wenn sich Lösung unter dem Körper ansammelt (z. B. bei Operationen)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung, kurz und kleinflächig: Iod passiert die Plazenta und kann die Schilddrüse des ungeborenen Kindes beeinträchtigen.","stillzeit":"Nur nach strenger Abwägung, kurz und kleinflächig: Iod reichert sich in der Muttermilch an. Nicht auf die Brust auftragen; gegebenenfalls Schilddrüse des Kindes kontrollieren.","hinweise":["Die braune Farbe zeigt die Wirksamkeit an; verblasst sie, ist das Iod verbraucht.","Vor Schilddrüsenuntersuchungen die Anwendung angeben – Iod kann die Ergebnisse verfälschen.","Nicht mit anderen Desinfektionsmitteln mischen.","Flecken auf Textilien lassen sich mit warmem Wasser und Seife entfernen."],"darreichung":["Lösung","Salbe"]},"pramipexol":{"wirkmechanismus":"Ahmt im Gehirn die Wirkung des Botenstoffs Dopamin nach. Pramipexol ist ein nicht-ergoliner Dopaminagonist mit hoher Affinität zu D2- und besonders D3-Rezeptoren und stimuliert die Dopaminrezeptoren im Striatum. Dadurch bessern sich die Bewegungsbeschwerden bei Parkinson sowie Missempfindungen und Bewegungsdrang beim Restless-Legs-Syndrom. Pramipexol wird kaum abgebaut und unverändert über die Niere ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Schläfrigkeit (Somnolenz)","Übelkeit","Dyskinesien (Überbewegungen, bei Parkinson)"],"haeufig":["Impulskontrollstörungen und zwanghaftes Verhalten (z. B. Spielsucht, Kaufsucht, Essattacken, gesteigertes sexuelles Verlangen)","Halluzinationen, Verwirrtheit","Schlaflosigkeit, abnorme Träume","Kopfschmerzen","Sehstörungen (Doppelbilder, verschwommenes Sehen)","Hypotonie (tiefer Blutdruck)","Verstopfung, Erbrechen","Müdigkeit, Beinödeme, Gewichtsabnahme"],"gelegentlich":["Plötzliches Einschlafen","Ohnmacht (Synkope)","Wahnvorstellungen, Paranoia, Delir","Herzinsuffizienz","Lungenentzündung","SIADH (Natriummangel durch zu viel antidiuretisches Hormon)","Überempfindlichkeit, Juckreiz, Ausschlag","Gewichtszunahme"],"selten":["Manie"],"unbekannt":["Dopaminagonisten-Entzugssyndrom (Apathie, Angst, Depression, Schmerzen beim Absetzen)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen. Nur anwenden, wenn der Nutzen das Risiko klar überwiegt.","stillzeit":"Pramipexol hemmt die Milchbildung und geht vermutlich in die Muttermilch über. Nicht stillen.","hinweise":["Mit oder ohne Mahlzeit einnehmen; Retardtabletten ganz schlucken.","Bei Tagesschläfrigkeit oder plötzlichem Einschlafen nicht Auto fahren und keine Maschinen bedienen.","Nicht abrupt absetzen, sondern ärztlich angeleitet ausschleichen.","Angehörige sollten auf Spielsucht, Kaufsucht oder auffälliges Sexualverhalten achten."],"darreichung":["Tabletten","Retardtabletten"]},"prasugrel":{"wirkmechanismus":"Verhindert, dass Blutplättchen verklumpen und Gerinnsel in den Herzkranzgefässen oder im Stent bilden. Prasugrel ist eine Vorstufe (Prodrug), die im Darm und in der Leber (u. a. über CYP3A4 und CYP2B6) rasch und zuverlässig in den aktiven Metaboliten umgewandelt wird. Dieser blockiert den ADP-Rezeptor P2Y12 der Blutplättchen irreversibel. Die Wirkung setzt schneller ein und ist stärker und gleichmässiger als bei Clopidogrel und hält für die Lebensdauer der Plättchen (7–10 Tage) an.","nebenwirkungen":{"haeufig":["Anämie (Blutarmut)","Blutergüsse (Hämatome), Hautblutungen","Nasenbluten","Magen-Darm-Blutungen","Blut im Urin","Blutungen und Blutergüsse an der Gefässpunktionsstelle","Hautausschlag"],"gelegentlich":["Überempfindlichkeitsreaktionen einschliesslich Angioödem","Hirnblutung (besonders nach früherem Schlaganfall oder TIA)","Augenblutungen","Bluthusten","Blutungen aus Zahnfleisch, Enddarm und im hinteren Bauchraum (retroperitoneal)","Nachblutungen nach Eingriffen"],"selten":["Thrombozytopenie (verminderte Blutplättchen)","Subkutane Hämatome (grössere Blutergüsse unter der Haut)"],"unbekannt":["Thrombotisch-thrombozytopenische Purpura (TTP)"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; nur anwenden, wenn der Nutzen das Risiko für das Ungeborene eindeutig überwiegt.","stillzeit":"Unbekannt, ob Prasugrel in die Muttermilch übergeht; Stillen wird nicht empfohlen.","hinweise":["Nicht eigenmächtig absetzen – nach Stent-Einlage drohen Stentverschluss und Herzinfarkt.","Vor Operationen und Zahnbehandlungen die Einnahme angeben; ein Pausieren (meist 7 Tage vorher) nur nach ärztlicher Anordnung.","Täglich etwa zur gleichen Zeit einnehmen, mit oder ohne Mahlzeit.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, starke Blutergüsse) oder plötzlichen neurologischen Ausfällen sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"pravastatin":{"wirkmechanismus":"Senkt das Cholesterin, indem es dessen Herstellung in der Leber bremst. Pravastatin hemmt kompetitiv die HMG-CoA-Reduktase, das Schlüsselenzym der Cholesterinsynthese. Die Leberzellen bilden daraufhin mehr LDL-Rezeptoren und entfernen mehr LDL-Cholesterin aus dem Blut. Pravastatin ist wasserlöslich, wird über den Transporter OATP1B1 in die Leber aufgenommen und kaum über Cytochrom-P450-Enzyme abgebaut – es hat deshalb weniger Wechselwirkungen als Simvastatin oder Atorvastatin.","nebenwirkungen":{"gelegentlich":["Kopfschmerzen, Schwindel","Schlafstörungen, Schlaflosigkeit","Sehstörungen (verschwommenes Sehen, Doppelbilder)","Verdauungsbeschwerden, Sodbrennen, Bauchschmerzen, Übelkeit, Erbrechen, Verstopfung, Durchfall, Blähungen","Juckreiz, Ausschlag, Nesselsucht, Veränderungen von Kopfhaut und Haaren (inkl. Haarausfall)","Störungen beim Wasserlassen (Schmerzen, häufiges oder nächtliches Wasserlassen)","Sexuelle Funktionsstörungen","Müdigkeit"],"sehrSelten":["Rhabdomyolyse (Muskelzerfall), teils mit akutem Nierenversagen; Myopathie, Myositis","Sehnenschäden, teils mit Sehnenriss","Überempfindlichkeitsreaktionen: Anaphylaxie, Angioödem, lupusähnliches Syndrom","Gelbsucht, Hepatitis, fulminante Lebernekrose","Pankreatitis (Bauchspeicheldrüsenentzündung)","Periphere Polyneuropathie, Parästhesien (Kribbeln)"],"unbekannt":["Immunvermittelte nekrotisierende Myopathie (anhaltende Muskelschwäche)","Dermatomyositis","Interstitielle Lungenerkrankung","Depression, Albträume, Gedächtnisverlust","Diabetes mellitus bei Personen mit Risikofaktoren","Myasthenia gravis (Muskelschwäche) oder deren Verschlechterung"]},"schwangerschaft":"Kontraindiziert – Cholesterin ist für die Entwicklung des Ungeborenen nötig. Bei Eintritt einer Schwangerschaft sofort absetzen; Frauen im gebärfähigen Alter sollen zuverlässig verhüten.","stillzeit":"Kontraindiziert – Pravastatin geht in geringen Mengen in die Muttermilch über.","hinweise":["Einmal täglich, vorzugsweise am Abend, mit oder ohne Essen.","Unerklärliche Muskelschmerzen, -schwäche oder -krämpfe, besonders mit Fieber oder dunklem Urin, sofort ärztlich melden.","Bei Colestyramin oder Colestipol zeitlichen Abstand einhalten (Pravastatin 1 Stunde vorher oder 4 Stunden nachher).","Ernährung und Bewegung bleiben wichtig; Blutfette und Leberwerte regelmässig kontrollieren."],"darreichung":["Tabletten"]},"prazepam":{"wirkmechanismus":"Wirkt angstlösend, beruhigend und muskelentspannend. Prazepam ist eine Vorstufe (Prodrug), die in der Leber zum eigentlichen Wirkstoff Nordazepam (Desmethyldiazepam) umgewandelt wird. Nordazepam verstärkt an GABA-A-Rezeptoren die hemmende Wirkung des Botenstoffs GABA. Die Wirkung setzt eher langsam ein; wegen der langen Halbwertszeit von Nordazepam reichert sich der Wirkstoff bei regelmässiger Einnahme an.","nebenwirkungen":{"haeufig":["Müdigkeit, Schläfrigkeit, Benommenheit (auch am nächsten Tag)","Schwindel, Gangunsicherheit (Ataxie)","Verlangsamte Reaktionen, Konzentrationsstörungen","Muskelschwäche"],"unbekannt":["Anterograde Amnesie (Gedächtnislücken)","Paradoxe Reaktionen (Unruhe, Aggressivität, Halluzinationen), v. a. bei älteren Menschen","Atemdämpfung","Abhängigkeit; Entzugssymptome und Rebound-Angst beim Absetzen","Stürze und Knochenbrüche bei älteren Menschen","Hervortreten einer bestehenden Depression","Hautreaktionen und andere Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Einnahme gegen Ende der Schwangerschaft oder in hohen Dosen können beim Neugeborenen Atemprobleme, Muskelschwäche, Unterkühlung (Floppy-Infant-Syndrom) und Entzugssymptome auftreten.","stillzeit":"Geht in die Muttermilch über und kann sich beim Säugling anreichern; nicht stillen.","hinweise":["Kann abhängig machen: so kurz wie möglich anwenden und nach längerer Einnahme nicht abrupt absetzen, sondern ausschleichen.","Keinen Alkohol trinken; Fahrtüchtigkeit ist beeinträchtigt, auch noch am Folgetag.","Ältere Menschen: erhöhte Sturzgefahr, besonders nachts."],"darreichung":["Tabletten"]},"praziquantel":{"wirkmechanismus":"Lähmt und schädigt die Würmer, sodass sie vom Immunsystem beseitigt werden können. Praziquantel erhöht die Durchlässigkeit der Zellmembranen des Wurms für Calcium; es kommt zu einer krampfartigen Lähmung der Muskulatur und zu Schäden an seiner äusseren Hülle (Tegument). Dadurch werden Oberflächenantigene freigelegt, die das Immunsystem angreifen kann. Praziquantel wird nach der Aufnahme stark in der Leber, vor allem über CYP3A4, abgebaut.","nebenwirkungen":{"sehrHaeufig":["Bauchschmerzen, Übelkeit","Kopfschmerzen","Schwindel","Unwohlsein"],"haeufig":["Schläfrigkeit, Müdigkeit","Erbrechen, Appetitlosigkeit, Durchfall","Nesselsucht (Urtikaria)","Muskelschmerzen","Fieber"],"unbekannt":["Allergische Reaktionen bis Anaphylaxie","Krampfanfälle (vor allem bei Neurozystizerkose)","Herzrhythmusstörungen","Blutiger Durchfall"]},"schwangerschaft":"Erfahrungen begrenzt; nur anwenden, wenn der Nutzen das mögliche Risiko überwiegt.","stillzeit":"Geht in die Muttermilch über: am Behandlungstag und während 72 Stunden danach nicht stillen, Milch abpumpen und verwerfen.","hinweise":["Tabletten unzerkaut mit etwas Flüssigkeit während einer Mahlzeit einnehmen (bitterer Geschmack, Brechreiz).","Am Behandlungstag und am folgenden Tag nicht Auto fahren und keine Maschinen bedienen.","Kein Grapefruitsaft während der Behandlung."],"darreichung":["Filmtabletten"]},"prazosin":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Blutgefässe erweitert. Prazosin blockiert selektiv die Alpha-1-Adrenozeptoren in der Gefässwand, sodass Noradrenalin die Gefässe nicht mehr verengen kann. Arterien und Venen erweitern sich, der periphere Widerstand sinkt, meist ohne deutlichen Anstieg der Herzfrequenz. Zusätzlich entspannt es die glatte Muskulatur von Prostata und Blasenhals.","nebenwirkungen":{"haeufig":["Schwindel, Benommenheit","Kopfschmerzen","Müdigkeit, Schwäche","Herzklopfen","Übelkeit","Ödeme (Wassereinlagerungen)","Verstopfte Nase","Verschwommenes Sehen"],"gelegentlich":["Synkope (Ohnmacht), vor allem nach der ersten Dosis","Tachykardie (Herzrasen)","Hautausschlag, Juckreiz","Häufiges Wasserlassen"],"selten":["Priapismus (schmerzhafte Dauererektion)","Harninkontinenz","Potenzstörungen"],"unbekannt":["Intraoperatives Floppy-Iris-Syndrom bei Operation am Grauen Star"]},"schwangerschaft":"Begrenzte Erfahrungen; nur anwenden, wenn der Nutzen das Risiko klar überwiegt.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; nur nach ärztlicher Abwägung.","hinweise":["Erste Dosis abends vor dem Schlafengehen einnehmen; in den ersten Tagen langsam aufstehen.","Schwindel und Benommenheit können besonders zu Beginn die Fahrtüchtigkeit beeinträchtigen.","Vor einer Augenoperation (Grauer Star) die Einnahme angeben."],"darreichung":["Tabletten"]},"prednicarbat":{"wirkmechanismus":"Dämpft Entzündung, Rötung und Juckreiz der Haut. Prednicarbat ist ein nicht halogenierter Doppelester des Prednisolons, der in der Haut zu wirksamen Abbauprodukten gespalten wird; diese binden an Glukokortikoid-Rezeptoren und hemmen die Bildung entzündungsfördernder Botenstoffe. Weil der Wirkstoff in der Haut rasch weiter abgebaut wird, ist das Risiko für Hautverdünnung im Vergleich zu anderen Kortisoncremes ähnlicher Stärke geringer.","nebenwirkungen":{"unbekannt":["Brennen, Juckreiz oder Reizung an der Auftragsstelle","Hautatrophie (Hautverdünnung), Teleangiektasien (erweiterte Äderchen), Dehnungsstreifen (Striae) bei längerer Anwendung","Steroidakne, periorale Dermatitis (Ausschlag um den Mund)","Hellere Hautstellen (Hypopigmentierung), vermehrte Behaarung","Allergische Kontaktdermatitis","Sekundäre Hautinfektionen","Verschwommenes Sehen (z. B. durch Chorioretinopathie)","Bei grossflächiger oder langer Anwendung: Unterdrückung der Nebennierenrinde"]},"schwangerschaft":"Nur nach ärztlicher Abwägung, kleinflächig und kurzzeitig; nicht grossflächig, nicht langfristig und nicht unter luftdichten Verbänden anwenden.","stillzeit":"Kleinflächige, kurzzeitige Anwendung nach ärztlicher Abwägung möglich; nicht im Brustbereich auftragen.","hinweise":["Dünn auftragen und nur so lange wie nötig anwenden; die Grundlage (Creme, Salbe, Fettsalbe) richtet sich nach dem Hautzustand.","Nicht in die Augen bringen; nach dem Auftragen die Hände waschen.","Keine luftdichten Verbände ohne ärztliche Anweisung.","Nach längerer Anwendung nicht abrupt absetzen, sondern schrittweise reduzieren."],"darreichung":["Creme","Salbe","Fettsalbe"]},"prednisolon":{"wirkmechanismus":"Dämpft Entzündungen und überschiessende Reaktionen des Immunsystems. Prednisolon ist ein synthetisches Glukokortikoid, das an den Glukokortikoid-Rezeptor im Zellinneren bindet und im Zellkern die Bildung entzündungsfördernder Botenstoffe (Zytokine, Prostaglandine, Leukotriene) unterdrückt sowie die Aktivität von Abwehrzellen hemmt. Es wirkt etwa 4-mal stärker entzündungshemmend als körpereigenes Cortisol und hat eine geringe salzzurückhaltende (mineralokortikoide) Wirkung. Prednisolon ist zugleich der wirksame Stoff, in den Prednison in der Leber umgewandelt wird.","nebenwirkungen":{"unbekannt":["Erhöhte Infektanfälligkeit und Verschleierung von Infektionen","Erhöhter Blutzucker bis zum Steroiddiabetes","Cushing-Syndrom (Vollmondgesicht, Stammfettsucht), Gewichtszunahme","Osteoporose, Knochennekrose (z. B. Hüftkopf), Muskelschwäche, Sehnenriss","Magen-Darm-Geschwüre und -Blutungen, Pankreatitis","Psychische Störungen (Schlaflosigkeit, Euphorie, Unruhe, Depression, Psychose)","Bluthochdruck, Wassereinlagerungen, Kaliummangel","Nebennierenrindeninsuffizienz nach dem Absetzen, Wachstumshemmung bei Kindern","Dünne Haut, Akne, verzögerte Wundheilung; grauer und grüner Star bei längerer Anwendung, verschwommenes Sehen (z. B. Chorioretinopathie)","Augentropfen: Brennen, verschwommenes Sehen, erhöhter Augeninnendruck, verzögerte Heilung von Hornhautverletzungen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung. Prednisolon wird in der Plazenta zu einem grossen Teil abgebaut; bei längerer Behandlung sind dennoch Wachstumsverzögerung und eine Unterfunktion der Nebennieren beim Neugeborenen möglich.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; bei üblichen Dosen ist Stillen meist möglich. Bei hohen Dosen ärztlich abklären; ein Abstand von einigen Stunden zwischen Einnahme und Stillen vermindert die Menge in der Milch.","hinweise":["Tabletten morgens mit dem Frühstück einnehmen (weniger Magenbeschwerden und Schlafstörungen).","Nach längerer Behandlung nicht abrupt absetzen, sondern nach ärztlichem Schema ausschleichen (Gefahr einer Nebennierenkrise).","Bei längerer Einnahme Blutzucker, Blutdruck, Augeninnendruck und Knochengesundheit kontrollieren lassen; auf ausreichend Calcium und Vitamin D achten.","Augentropfen (Suspension) vor Gebrauch gut schütteln; nur unter augenärztlicher Kontrolle anwenden."],"darreichung":["Tabletten","Augentropfen (Suspension)","Augensalbe"]},"prednison":{"wirkmechanismus":"Dämpft Entzündungen und überschiessende Reaktionen des Immunsystems. Prednison ist eine Vorstufe (Prodrug) und wird in der Leber rasch in den eigentlichen Wirkstoff Prednisolon umgewandelt. Prednisolon bindet an den Glukokortikoid-Rezeptor im Zellinneren und unterdrückt im Zellkern die Bildung entzündungsfördernder Botenstoffe (Zytokine, Prostaglandine, Leukotriene) sowie die Aktivität von Abwehrzellen. Es wirkt etwa 4-mal stärker entzündungshemmend als körpereigenes Cortisol und hat eine geringe salzzurückhaltende Wirkung. Die Form mit verzögerter Freisetzung gibt den Wirkstoff erst rund 4 Stunden nach der Einnahme frei, also in der Nacht, wenn die entzündlichen Botenstoffe ansteigen.","nebenwirkungen":{"unbekannt":["Erhöhte Infektanfälligkeit und Verschleierung von Infektionen","Erhöhter Blutzucker bis zum Steroiddiabetes","Cushing-Syndrom (Vollmondgesicht, Stammfettsucht), Gewichtszunahme","Osteoporose, Knochennekrose (z. B. Hüftkopf), Muskelschwäche, Sehnenriss","Magen-Darm-Geschwüre und -Blutungen, Pankreatitis","Psychische Störungen (Schlaflosigkeit, Euphorie, Unruhe, Depression, Psychose)","Bluthochdruck, Wassereinlagerungen, Kaliummangel","Nebennierenrindeninsuffizienz nach dem Absetzen, Wachstumshemmung bei Kindern","Dünne Haut, Akne, verzögerte Wundheilung; grauer und grüner Star bei längerer Anwendung, verschwommenes Sehen (z. B. Chorioretinopathie)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung. Der Wirkstoff wird in der Plazenta zu einem grossen Teil abgebaut; bei längerer Behandlung sind dennoch Wachstumsverzögerung und eine Unterfunktion der Nebennieren beim Neugeborenen möglich.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; bei üblichen Dosen ist Stillen meist möglich. Bei hohen Dosen ärztlich abklären; ein Abstand von einigen Stunden zwischen Einnahme und Stillen vermindert die Menge in der Milch.","hinweise":["Normale Tabletten morgens mit dem Frühstück einnehmen; Tabletten mit verzögerter Freisetzung (Lodotra) abends mit oder nach dem Abendessen unzerkaut schlucken.","Nach längerer Behandlung nicht abrupt absetzen, sondern nach ärztlichem Schema ausschleichen (Gefahr einer Nebennierenkrise).","Bei längerer Einnahme Blutzucker, Blutdruck, Augeninnendruck und Knochengesundheit kontrollieren lassen; auf ausreichend Calcium und Vitamin D achten.","Bei Fieber, Infektzeichen oder vor Operationen die Kortison-Einnahme angeben."],"darreichung":["Tabletten","Tabletten mit verzögerter Wirkstofffreisetzung"]},"pregabalin":{"wirkmechanismus":"Dämpft die übermässige Aktivität von Nervenzellen und lindert so Nervenschmerzen, Angst und Krampfanfälle. Pregabalin bindet an die Alpha-2-Delta-Untereinheit spannungsabhängiger Calciumkanäle und vermindert dadurch die Freisetzung erregender Botenstoffe wie Glutamat, Noradrenalin und Substanz P. Es wird praktisch nicht verstoffwechselt und unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Schwindel, Schläfrigkeit","Kopfschmerzen"],"haeufig":["Nasen-Rachen-Entzündung, gesteigerter Appetit, Gewichtszunahme","Euphorie, Verwirrtheit, Reizbarkeit, Desorientierung, Schlaflosigkeit, verminderte Libido","Gang- und Koordinationsstörungen, Zittern, Sprechstörungen, Gedächtnis- und Aufmerksamkeitsstörungen, Kribbeln","Verschwommenes Sehen, Doppelbilder, Drehschwindel","Übelkeit, Erbrechen, Verstopfung, Durchfall, Blähungen, Mundtrockenheit","Muskelkrämpfe, Gelenk- und Rückenschmerzen","Erektionsstörungen","Wassereinlagerungen (Ödeme), Stürze, Müdigkeit"],"gelegentlich":["Überempfindlichkeitsreaktionen, Neutropenie (Mangel an weissen Blutkörperchen)","Hypoglykämie (Unterzuckerung), Appetitlosigkeit","Halluzinationen, Panikattacken, Unruhe, Depression","Ohnmacht, Bewusstlosigkeit, Muskelzuckungen (Myoklonien)","Herzrasen, langsamer Puls, AV-Block 1. Grades, Herzinsuffizienz","Blutdruckabfall oder -anstieg, Atemnot, Nasenbluten","Hautausschlag, Nesselsucht, Schwitzen; erhöhte Leberwerte","Schmerzen beim Wasserlassen, Harninkontinenz"],"selten":["Angioödem (Schwellung von Gesicht, Zunge, Rachen)","Krampfanfälle","QT-Verlängerung","Lungenödem","Pankreatitis, Gelbsucht","Stevens-Johnson-Syndrom","Rhabdomyolyse (Muskelzerfall), Nierenversagen, Harnverhalt"],"sehrSelten":["Leberversagen, Hepatitis"],"unbekannt":["Abhängigkeit, Entzugssymptome nach dem Absetzen","Suizidgedanken","Atemdepression"]},"schwangerschaft":"Nicht anwenden, ausser bei eindeutiger Notwendigkeit nach ärztlicher Abwägung; Hinweise auf ein leicht erhöhtes Fehlbildungsrisiko. Frauen im gebärfähigen Alter sollen wirksam verhüten.","stillzeit":"Geht in die Muttermilch über; Stillen wird während der Behandlung nicht empfohlen.","hinweise":["Nicht abrupt absetzen, sondern über mindestens eine Woche ausschleichen (Entzugssymptome wie Schlaflosigkeit, Übelkeit, Angst).","Alkohol meiden; Fahrtüchtigkeit ist besonders zu Beginn eingeschränkt.","Bei Atemproblemen, starker Schläfrigkeit, Schwellungen im Gesicht oder Sehstörungen ärztlich melden.","Nur wie verordnet einnehmen – Pregabalin kann missbraucht werden und abhängig machen."],"darreichung":["Kapseln"]},"prilocain":{"wirkmechanismus":"Betäubt vorübergehend die Nerven im behandelten Gebiet, sodass keine Schmerzen weitergeleitet werden. Prilocain blockiert spannungsabhängige Natriumkanäle der Nervenmembran und verhindert so die Erregungsleitung. Es wird in Leber, Niere und Lunge zu o-Toluidin abgebaut, das den roten Blutfarbstoff zu Methämoglobin oxidieren kann, welches keinen Sauerstoff mehr transportiert. Die hyperbare (schwerere) Spritzenlösung sinkt im Nervenwasser ab und erlaubt eine gezielte Ausbreitung der Spinalanästhesie.","nebenwirkungen":{"haeufig":["Hypotonie (Blutdruckabfall) bei Spinalanästhesie","Übelkeit, Erbrechen","Creme: Blässe, Rötung oder Schwellung der Haut an der Auftragsstelle"],"gelegentlich":["Creme: Brennen, Juckreiz oder Wärmegefühl an der Auftragsstelle"],"selten":["Methämoglobinämie (verminderter Sauerstofftransport, bläuliche Haut)","Allergische Reaktionen bis anaphylaktischer Schock","Krampfanfälle, Herzrhythmusstörungen oder Herzstillstand bei zu hohen Blutspiegeln","Nervenschäden nach Spinalanästhesie"],"unbekannt":["Bradykardie (langsamer Puls)","Kopfschmerzen nach Spinalanästhesie","Rückenschmerzen","Parästhesien (Kribbeln)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; bisher keine Hinweise auf Fehlbildungen. Für Betäubungen unter der Geburt (z. B. Parazervikalblockade) wird Prilocain nicht empfohlen, weil es beim Kind eine Methämoglobinämie auslösen kann.","stillzeit":"Geht nur in geringen Mengen in die Muttermilch über; nach üblicher Anwendung kann weiter gestillt werden.","hinweise":["Betäubungscreme rechtzeitig vor dem Eingriff unter einem Folienverband auftragen; die nötige Einwirkzeit beträgt meist mindestens 1 Stunde.","Bei Säuglingen und Kleinkindern Menge, Fläche und Einwirkzeit der Creme genau einhalten (Gefahr der Methämoglobinämie).","Nach einer Spinalanästhesie erst wieder Auto fahren, wenn die Wirkung vollständig abgeklungen ist."],"darreichung":["Injektionslösung (hyperbar, intrathekal)","Creme (Kombination mit Lidocain)"]},"primidon":{"wirkmechanismus":"Dämpft die Erregbarkeit der Nervenzellen und verhindert so Krampfanfälle; zudem vermindert es Zittern. Primidon wirkt selbst krampfhemmend und wird in der Leber zu zwei ebenfalls wirksamen Stoffen abgebaut: Phenobarbital und Phenylethylmalonamid (PEMA). Phenobarbital verstärkt die hemmende Wirkung von GABA am GABA-A-Rezeptor. Wie Phenobarbital induziert Primidon zahlreiche Leberenzyme (u. a. CYP3A4) und beschleunigt so den Abbau vieler Arzneimittel.","nebenwirkungen":{"haeufig":["Schläfrigkeit, Teilnahmslosigkeit (v. a. zu Behandlungsbeginn)","Übelkeit, Erbrechen","Schwindel, Kopfschmerzen","Gangunsicherheit (Ataxie), Augenzittern (Nystagmus), Sehstörungen"],"unbekannt":["Hautausschlag; schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Megaloblastäre Anämie (Folsäuremangel) und andere Blutbildveränderungen","Knochenerweichung (Osteomalazie) bei Langzeitbehandlung","Verwirrtheit, psychotische Reaktionen, Depression","Lupus-ähnliche Erkrankung, Dupuytren-Kontraktur (Bindegewebsverhärtung der Hand)","Abhängigkeit; Entzugskrampfanfälle beim abrupten Absetzen"]},"schwangerschaft":"Fruchtschädigend (wie Phenobarbital) – nur wenn unverzichtbar, in der niedrigsten wirksamen Dosis und mit Folsäure. Beim Neugeborenen sind Entzugssymptome und eine Blutungsneigung (Vitamin-K-Mangel) möglich.","stillzeit":"Geht in erheblichen Mengen in die Muttermilch über (Schläfrigkeit beim Säugling) – Stillen nur nach ärztlicher Abwägung, Kind beobachten.","hinweise":["Nicht abrupt absetzen – Gefahr von Krampfanfällen und Entzugssymptomen.","Kein Alkohol; die Fahrtüchtigkeit ist besonders zu Beginn deutlich eingeschränkt.","Hormonale Verhütung ist unzuverlässig – nichthormonal verhüten.","Blutbild und Spiegel (Primidon und Phenobarbital) werden regelmässig kontrolliert."],"darreichung":["Tabletten"]},"procain":{"wirkmechanismus":"Betäubt vorübergehend die Nerven an der Injektionsstelle, sodass dort kein Schmerz empfunden wird. Procain blockiert spannungsabhängige Natriumkanäle der Nervenmembran und unterbricht so die Weiterleitung von Nervenimpulsen. Als Ester wird es im Blut durch die Pseudocholinesterase rasch zu para-Aminobenzoesäure (PABA) und Diethylaminoethanol abgebaut; die Wirkung ist deshalb kurz. Es erweitert zudem die Blutgefässe.","nebenwirkungen":{"unbekannt":["Allergische Reaktionen (Hautausschlag, Nesselsucht, Schwellungen, Bronchospasmus) bis Anaphylaxie","Benommenheit, Schwindel, Taubheitsgefühl um den Mund, metallischer Geschmack, Ohrensausen","Zittern, Unruhe und Krampfanfälle bei hohen Blutspiegeln","Blutdruckabfall, Bradykardie, Herzrhythmusstörungen bis Herzstillstand","Atemdepression","Übelkeit, Erbrechen"]},"schwangerschaft":"Keine ausreichenden Daten; nur nach ärztlicher Abwägung anwenden.","stillzeit":"Keine ausreichenden Daten; nur nach ärztlicher Abwägung anwenden.","hinweise":["Bekannte Allergien gegen Lokalanästhetika oder gegen PABA (z. B. aus älteren Sonnenschutzmitteln) angeben – Kreuzallergien möglich.","Bis das Taubheitsgefühl abgeklungen ist, Vorsicht beim Essen und Trinken (Verletzungs- und Verbrühungsgefahr).","Nach grösseren Nervenblockaden erst nach ärztlicher Rücksprache wieder ein Fahrzeug lenken."],"darreichung":["Injektionslösung"]},"procarbazin":{"wirkmechanismus":"Schädigt das Erbgut von Krebszellen und hemmt so ihre Teilung. Procarbazin ist ein Prodrug: Es wird in der Leber über Cytochrom-P450-Enzyme zu reaktiven Azo- und Azoxy-Metaboliten umgewandelt, die die DNA methylieren und die DNA-, RNA- und Eiweisssynthese hemmen. Zusätzlich hemmt Procarbazin schwach die Monoaminoxidase (MAO), was Wechselwirkungen mit tyraminreichen Nahrungsmitteln und Sympathomimetika erklärt.","nebenwirkungen":{"sehrHaeufig":["Appetitlosigkeit, Übelkeit und Erbrechen (v. a. zu Beginn)","Leukopenie und Thrombozytopenie (Mangel an weissen Blutkörperchen und Blutplättchen)"],"unbekannt":["Anämie (Blutarmut)","Müdigkeit, Schläfrigkeit, Depression, Verwirrtheit","Periphere Neuropathie (Kribbeln, Taubheit)","Allergische Hautreaktionen","Interstitielle Pneumonitis (allergische Entzündung des Lungengewebes)","Leberfunktionsstörungen","Unfruchtbarkeit (fehlende Samenzellen, Ausbleiben der Regel)","Zweitkrebs, z. B. akute Leukämie"]},"schwangerschaft":"Kontraindiziert – Procarbazin ist fruchtschädigend. Frauen und Männer müssen während und nach der Behandlung zuverlässig verhüten (Dauer nach ärztlicher Vorgabe).","stillzeit":"Kontraindiziert – während der Behandlung nicht stillen.","hinweise":["Während der Behandlung keinen Alkohol trinken (Unverträglichkeitsreaktion).","Tyraminreiche Lebensmittel meiden (z. B. lange gereifter Käse, Rotwein, Rohwurst, Hefeextrakt, Sojasauce) – Gefahr einer Blutdruckkrise.","Keine rezeptfreien Erkältungs- oder Schnupfenmittel ohne Rücksprache mit Ärztin, Arzt oder Apotheke.","Blutbild regelmässig kontrollieren; Fieber oder Blutungszeichen sofort melden."],"darreichung":["Kapseln"]},"progesteron":{"wirkmechanismus":"Ersetzt das körpereigene Gelbkörperhormon, das die Gebärmutterschleimhaut auf die Einnistung eines Embryos vorbereitet und eine frühe Schwangerschaft erhält. Progesteron bindet an Progesteronrezeptoren und wandelt die durch Östrogen aufgebaute Schleimhaut in eine sekretorische Schleimhaut um. Bei Hormonersatz verhindert es so ein übermässiges Wachstum der Gebärmutterschleimhaut unter Östrogen. Einige Abbauprodukte wirken beruhigend auf das Gehirn (über GABA-A-Rezeptoren), was Müdigkeit und Schwindel nach der Einnahme erklärt.","nebenwirkungen":{"haeufig":["Zyklusveränderungen, Ausbleiben der Regel oder Zwischenblutungen","Kopfschmerzen"],"gelegentlich":["Schläfrigkeit, vorübergehende Benommenheit und Schwindel (vor allem nach Einnahme)","Brustspannen oder Brustschmerzen","Erbrechen, Durchfall, Verstopfung","Juckreiz, Akne","Cholestatische Gelbsucht (Gallenstau)"],"selten":["Übelkeit"],"sehrSelten":["Depression","Nesselsucht (Urtikaria)","Chloasma (bräunliche Pigmentflecken im Gesicht)"],"unbekannt":["Lokale Reizung, Juckreiz oder Ausfluss bei vaginaler Anwendung","Thromboembolische Ereignisse (Thrombose, Lungenembolie)","Schmerzen oder Rötung an der Einstichstelle (Injektion)"]},"schwangerschaft":"Zur Unterstützung der Frühschwangerschaft im Rahmen einer Kinderwunschbehandlung zugelassen; ein schädigender Einfluss auf das Kind ist nicht bekannt. Ausserhalb dieser Indikation keine Anwendung in der Schwangerschaft.","stillzeit":"Progesteron geht in die Muttermilch über; eine Anwendung in der Stillzeit wird nicht empfohlen.","hinweise":["Kapseln zum Einnehmen abends beim Zubettgehen und nicht zusammen mit einer Mahlzeit einnehmen – sie können müde und schwindlig machen.","Bei Müdigkeit oder Schwindel kein Fahrzeug lenken und keine Maschinen bedienen.","Bei vaginaler Anwendung Kapsel bzw. Gel tief in die Scheide einführen.","Bei Zeichen einer Thrombose (geschwollenes, schmerzhaftes Bein, Atemnot), Sehstörungen oder Gelbsucht sofort ärztlichen Rat einholen."],"darreichung":["Weichkapseln (zum Einnehmen oder zur vaginalen Anwendung)","Vaginalgel","Injektionslösung (subkutan)"]},"propafenon":{"wirkmechanismus":"Stabilisiert den Herzrhythmus, indem es die Erregungsleitung im Herzen verlangsamt. Propafenon blockiert als Antiarrhythmikum der Klasse IC die schnellen Natriumkanäle der Herzmuskelzellen; Leitungsgeschwindigkeit und Erregbarkeit nehmen ab (verlängerte PQ- und QRS-Zeit). Zusätzlich wirkt es schwach betablockierend und calciumantagonistisch. Abgebaut wird es vor allem über CYP2D6 zum ebenfalls wirksamen 5-Hydroxypropafenon; bei langsamen CYP2D6-Metabolisierern sind die Spiegel höher.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Erregungsleitungsstörungen des Herzens (z. B. AV-Block, Schenkelblock)","Herzklopfen (Palpitationen)"],"haeufig":["Kopfschmerzen, Geschmacksstörungen","Verschwommenes Sehen","Angst, Schlafstörungen","Langsamer oder schneller Puls, Vorhofflattern","Atemnot (Dyspnoe)","Übelkeit, Erbrechen, Bauchschmerzen, Durchfall, Verstopfung, Mundtrockenheit","Leberfunktionsstörungen","Müdigkeit, Schwäche, Brustschmerzen, Fieber"],"gelegentlich":["Thrombozytopenie (Mangel an Blutplättchen)","Kammertachykardie und andere neue Rhythmusstörungen (proarrhythmische Wirkung)","Hypotonie (tiefer Blutdruck), Ohnmacht (Synkope)","Kribbeln (Parästhesien), Gangunsicherheit","Hautausschlag, Juckreiz","Erektionsstörungen","Appetitlosigkeit, Albträume, Blähungen"],"unbekannt":["Agranulozytose (gefährlicher Mangel an weissen Blutkörperchen)","Kammerflimmern","Verschlechterung einer Herzinsuffizienz","Krampfanfälle, Verwirrtheit","Cholestatische Hepatitis, Gelbsucht","Lupus-ähnliches Syndrom","Verminderte Spermienzahl (rückbildungsfähig)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; Propafenon gelangt zum Ungeborenen. Nur anwenden, wenn der Nutzen das Risiko klar überwiegt.","stillzeit":"Geht in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung und mit Beobachtung des Säuglings.","hinweise":["Tabletten unzerkaut mit Flüssigkeit nach dem Essen einnehmen (bitterer Geschmack, betäubende Wirkung im Mund).","Regelmässige EKG-Kontrollen; bei Ohnmacht, Herzrasen oder Atemnot sofort ärztliche Hilfe holen.","Schwindel und Sehstörungen können die Fahrtüchtigkeit beeinträchtigen.","Bei Fieber, Halsschmerzen oder anderen Infektzeichen Blutbild kontrollieren lassen (Agranulozytose möglich)."],"darreichung":["Filmtabletten"]},"propofol":{"wirkmechanismus":"Lässt innerhalb von Sekunden einschlafen; nach Ende der Zufuhr wacht man rasch und meist klar wieder auf. Propofol verstärkt im Gehirn die hemmende Wirkung des Botenstoffs GABA am GABA-A-Rezeptor. Es wirkt nicht schmerzlindernd und wird deshalb bei Operationen mit Schmerzmitteln kombiniert. Der Abbau erfolgt sehr rasch in der Leber und zusätzlich ausserhalb der Leber.","nebenwirkungen":{"sehrHaeufig":["Schmerzen an der Injektionsstelle"],"haeufig":["Kopfschmerzen beim Aufwachen","Bradykardie (langsamer Puls)","Hypotonie (Blutdruckabfall)","Kurzer Atemstillstand bei der Einleitung","Übelkeit und Erbrechen beim Aufwachen"],"gelegentlich":["Thrombose und Venenentzündung an der Injektionsstelle"],"selten":["Krampfanfall-ähnliche Bewegungen, Muskelzuckungen"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Lungenödem","Pankreatitis (Bauchspeicheldrüsenentzündung)","Verfärbung des Urins bei langer Anwendung","Sexuelle Enthemmung","Fieber nach der Operation"],"unbekannt":["Propofol-Infusionssyndrom (Übersäuerung, Muskelzerfall, Herz- und Nierenversagen) bei hohen Dosen über lange Zeit","Atemdepression (dosisabhängig)","Hyperkaliämie, erhöhte Blutfette","Herzrhythmusstörungen, Herzversagen","Euphorie, Missbrauch und Abhängigkeit","Hepatitis","Priapismus (schmerzhafte Dauererektion)"]},"schwangerschaft":"Nur wenn eindeutig erforderlich. Propofol passiert die Plazenta und kann beim Neugeborenen dämpfend wirken; hohe Dosen beim Kaiserschnitt vermeiden.","stillzeit":"Geringe Mengen gehen in die Muttermilch über. Laut Fachinformation 24 Stunden nach der Anwendung nicht stillen und die in dieser Zeit gebildete Milch verwerfen.","hinweise":["Nach Narkose oder Sedierung mindestens 24 Stunden nicht Auto fahren und nicht allein nach Hause gehen; kein Alkohol.","Eine Soja- oder Erdnussallergie vor der Anwendung melden.","Wird nur von in Anästhesie oder Intensivmedizin geschultem Personal unter Überwachung von Atmung und Kreislauf angewendet."],"darreichung":["Emulsion zur Injektion oder Infusion"]},"propranolol":{"wirkmechanismus":"Senkt Puls und Blutdruck, indem es die Wirkung der Stresshormone Adrenalin und Noradrenalin am Herzen und an den Gefässen abschwächt. Propranolol blockiert ohne Unterschied die Beta-1-Rezeptoren (Herz, Niere) und die Beta-2-Rezeptoren (Bronchien, Gefässe, Leber). Dadurch schlägt das Herz langsamer und weniger kräftig, braucht weniger Sauerstoff, und die Freisetzung von Renin aus der Niere sinkt. Die Blockade der Beta-2-Rezeptoren kann die Atemwege verengen und die Erholung aus einer Unterzuckerung verzögern. Bei infantilen Hämangiomen wirkt es unter anderem über eine Gefässverengung und eine Hemmung des Gefässwachstums.","nebenwirkungen":{"sehrHaeufig":["Bei Säuglingen (Hemangiol): Schlafstörungen, Bronchitis, Durchfall, Erbrechen"],"haeufig":["Müdigkeit, Erschöpfung","Bradykardie (langsamer Puls)","Kalte Hände und Füsse, Raynaud-Syndrom","Schlafstörungen, Albträume"],"gelegentlich":["Magen-Darm-Beschwerden wie Übelkeit, Erbrechen, Durchfall"],"selten":["Verschlechterung einer Herzinsuffizienz, AV-Block","Blutdruckabfall beim Aufstehen, Ohnmacht","Bronchospasmus (Verkrampfung der Atemwege), besonders bei Asthma","Schwindel, Verwirrtheit, Stimmungsschwankungen, Halluzinationen, Psychosen","Thrombozytopenie (Mangel an Blutplättchen), Purpura","Haarausfall, psoriasisartige Hautreaktionen, Verschlechterung einer Psoriasis","Sehstörungen, trockene Augen","Kribbeln (Parästhesien), Verschlechterung einer Schaufensterkrankheit"],"sehrSelten":["Auslösung oder Verschlechterung einer Myasthenia gravis"],"unbekannt":["Hypoglykämie (Unterzuckerung), besonders bei Kindern und nach Fasten, selten mit Krampfanfällen","Depression","Bindehautentzündung"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung: Propranolol kann das Wachstum des Kindes vermindern und beim Neugeborenen langsamen Puls, Unterzuckerung und Atemprobleme verursachen; Neugeborene in den ersten Lebenstagen überwachen.","stillzeit":"Geht in die Muttermilch über; laut Fachinformation wird Stillen nicht empfohlen. Wird dennoch gestillt, den Säugling auf langsamen Puls und Unterzuckerung beobachten.","hinweise":["Nicht abrupt absetzen, sondern schrittweise über 1–2 Wochen ausschleichen (Gefahr von Angina-pectoris-Anfällen, Herzinfarkt oder Blutdruckanstieg).","Kann die Reaktionsfähigkeit beeinträchtigen, besonders zu Beginn und zusammen mit Alkohol.","Diabetes: Unterzuckerungen können ohne Herzklopfen und Zittern verlaufen – Blutzucker häufiger messen.","Hemangiol: während oder direkt nach einer Mahlzeit geben; bei Nahrungsverweigerung, Erbrechen oder einem Atemwegsinfekt mit Atemnot die Gabe aussetzen und ärztlichen Rat einholen."],"darreichung":["Tabletten","Lösung zum Einnehmen"]},"propyphenazon":{"wirkmechanismus":"Lindert Schmerzen und senkt Fieber. Propyphenazon ist ein Pyrazolon-Derivat (verwandt mit Metamizol und Phenazon) und hemmt die Bildung von Prostaglandinen über die Cyclooxygenase vor allem im zentralen Nervensystem; die entzündungshemmende Wirkung ist gering. Es wirkt rasch und kurz (Halbwertszeit etwa 1–2 Stunden). Im Kombinationspräparat ergänzt es Paracetamol, Coffein soll die Schmerzlinderung verstärken.","nebenwirkungen":{"unbekannt":["Allergische Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht)","Magen-Darm-Beschwerden, Übelkeit","Anaphylaktischer Schock (schwere allergische Reaktion)","Agranulozytose (starker Mangel an weissen Blutkörperchen), Thrombozytopenie","Asthmaanfall bei Analgetika-Asthma","Schwere Hautreaktionen (z. B. Stevens-Johnson-Syndrom)","Unruhe, Schlafstörungen, Herzklopfen (Coffein)","Leberschäden bei Überdosierung (Paracetamol)"]},"schwangerschaft":"Nicht empfohlen; für Propyphenazon fehlen ausreichende Erfahrungen. Als Schmerzmittel in der Schwangerschaft eignet sich Paracetamol allein besser.","stillzeit":"Nicht empfohlen, da Propyphenazon und Coffein in die Muttermilch übergehen.","hinweise":["Ohne ärztlichen Rat nur wenige Tage einnehmen; häufige Einnahme kann selbst Kopfschmerzen auslösen.","Keine weiteren paracetamolhaltigen Mittel gleichzeitig einnehmen und die Höchstdosis einhalten.","Bei Fieber, Halsschmerzen oder Mundgeschwüren während der Einnahme sofort ärztlich abklären (mögliche Blutbildstörung).","Alkohol meiden und coffeinhaltige Getränke einschränken."],"darreichung":["Tabletten (Kombination mit Paracetamol und Coffein)"]},"protamin":{"wirkmechanismus":"Bindet Heparin im Blut und hebt so dessen gerinnungshemmende Wirkung innerhalb von Minuten auf. Protamin ist ein stark basisches, positiv geladenes Eiweiss, das ursprünglich aus Fischsperma gewonnen wurde. Es bildet mit dem stark sauren, negativ geladenen Heparin einen stabilen, unwirksamen Komplex. Bei niedermolekularen Heparinen bleibt ein Teil der Anti-Faktor-Xa-Wirkung bestehen.","nebenwirkungen":{"unbekannt":["Blutdruckabfall, langsamer Puls (Bradykardie)","Hitzegefühl, Gesichtsrötung","Übelkeit, Erbrechen, Müdigkeit","Atemnot, Bronchospasmus, akuter Lungenhochdruck","Anaphylaxie (schwere allergische Reaktion)","Nicht herzbedingtes Lungenödem","Blutungen bei Überdosierung"]},"schwangerschaft":"Keine ausreichenden Daten; nur anwenden, wenn eindeutig notwendig.","stillzeit":"Keine Daten; Anwendung nach ärztlicher Abwägung.","hinweise":["Wird nur im Spital unter Überwachung von Kreislauf und Gerinnung verabreicht.","Allergien (besonders Fischallergie) und eine frühere Behandlung mit NPH-Insulin vorher angeben."],"darreichung":["Injektionslösung"]},"protein-c-human":{"wirkmechanismus":"Ersetzt ein körpereigenes Eiweiss, das die Blutgerinnung bremst. Protein C wird an der Gefässwand durch den Thrombin-Thrombomodulin-Komplex zu aktiviertem Protein C umgewandelt. Dieses baut zusammen mit Protein S die Gerinnungsfaktoren Va und VIIIa ab, hemmt so die weitere Thrombinbildung und fördert zudem die Auflösung von Gerinnseln. Bei einem schweren angeborenen Mangel entstehen ohne Ersatz lebensbedrohliche Gerinnsel.","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz, Hitzegefühl) bis Anaphylaxie","Schwindel","Fieber","Blutungen, vor allem bei gleichzeitiger Gerinnungshemmung","Heparininduzierte Thrombozytopenie durch Heparinspuren"]},"schwangerschaft":"Nur begrenzte Erfahrungen; nur anwenden, wenn eindeutig notwendig.","stillzeit":"Nur anwenden, wenn eindeutig notwendig.","hinweise":["Bei Anzeichen einer allergischen Reaktion (Ausschlag, Atemnot, Schwindel) die Injektion sofort stoppen und ärztliche Hilfe holen.","Bei jeder Gabe werden Name und Chargennummer dokumentiert (Plasmaprodukt)."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"prothrombinkomplex-ppsb":{"wirkmechanismus":"Ersetzt fehlende Gerinnungsfaktoren und bringt die Blutgerinnung innert Minuten wieder in Gang. PPSB ist ein aus menschlichem Spenderplasma gewonnenes Konzentrat der Vitamin-K-abhängigen Gerinnungsfaktoren II (Prothrombin), VII, IX und X sowie der gerinnungshemmenden Proteine C und S. Nach der Infusion normalisieren sich INR bzw. Quick-Wert rasch. Weil die zugeführten Faktoren nur eine begrenzte Zeit wirken, wird bei Vitamin-K-Antagonisten zusätzlich Vitamin K gegeben.","nebenwirkungen":{"haeufig":["Thromboembolische Ereignisse (Thrombosen, Embolien)","Kopfschmerzen"],"unbekannt":["Überempfindlichkeitsreaktionen bis anaphylaktischer Schock","Verbrauchskoagulopathie (disseminierte intravasale Gerinnung)","Heparininduzierte Thrombozytopenie (HIT)","Bildung von Antikörpern gegen einzelne Gerinnungsfaktoren","Fieber"]},"schwangerschaft":"Keine kontrollierten Erfahrungen; nur bei eindeutiger Notwendigkeit anwenden.","stillzeit":"Keine Daten; nur bei eindeutiger Notwendigkeit anwenden.","hinweise":["Wird im Spital als langsame intravenöse Injektion gegeben; bei Vitamin-K-Antagonisten wird zusätzlich Vitamin K verabreicht.","Nach der Gabe auf Zeichen einer Thrombose (Beinschwellung, Brustschmerz, Atemnot) oder einer allergischen Reaktion achten.","Bei regelmässiger Behandlung mit Plasmapräparaten werden Impfungen gegen Hepatitis A und B empfohlen."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"prucaloprid":{"wirkmechanismus":"Regt die natürliche Darmbewegung an. Prucaloprid aktiviert selektiv und mit hoher Affinität Serotonin-5-HT4-Rezeptoren im Nervensystem der Darmwand. Dadurch werden die vorwärtstreibenden (propulsiven) Kontraktionen des Dickdarms verstärkt und die Darmpassage beschleunigt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Übelkeit","Durchfall","Bauchschmerzen"],"haeufig":["Verminderter Appetit","Schwindel","Erbrechen","Dyspepsie (Verdauungsbeschwerden)","Blähungen","Abnorme Darmgeräusche","Häufiges Wasserlassen (Pollakisurie)","Müdigkeit"],"gelegentlich":["Zittern (Tremor)","Herzklopfen (Palpitationen)","Blutung aus dem Enddarm","Fieber","Unwohlsein"]},"schwangerschaft":"Nicht empfohlen; Frauen im gebärfähigen Alter sollen während der Behandlung zuverlässig verhüten.","stillzeit":"Prucaloprid geht in die Muttermilch über; während der Stillzeit nicht anwenden.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten, zu einer beliebigen Tageszeit einnehmen.","Kopfschmerzen und Magen-Darm-Beschwerden treten meist am ersten Behandlungstag auf und klingen in der Regel rasch ab.","Tritt nach 4 Wochen keine Besserung ein, die Behandlung ärztlich überprüfen lassen.","Schwindel und Müdigkeit können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"pseudoephedrin":{"wirkmechanismus":"Lässt die geschwollenen Schleimhäute in Nase und Nebenhöhlen abschwellen. Pseudoephedrin setzt Noradrenalin aus Nervenendigungen frei und stimuliert zusätzlich direkt Alpha- und Beta-Adrenozeptoren; über die Alpha-Rezeptoren verengen sich die Blutgefässe der Schleimhaut. Weil es im ganzen Körper wirkt, kann es auch Blutdruck und Puls erhöhen und anregend auf das Nervensystem wirken. Es wird grösstenteils unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Schlaflosigkeit, Nervosität","Mundtrockenheit","Übelkeit"],"unbekannt":["Herzklopfen, Herzrasen, Blutdruckanstieg","Angst, Unruhe, Halluzinationen (besonders bei Kindern)","Erschwertes Wasserlassen (Harnverhalt)","Hautausschlag, akute generalisierte exanthematische Pustulose (AGEP)","Ischämische Kolitis (Durchblutungsstörung des Darms)","PRES und RCVS (seltene Durchblutungsstörungen des Gehirns)","Herzinfarkt, Schlaganfall","Ischämische Optikusneuropathie (Schädigung des Sehnervs)"]},"schwangerschaft":"Nicht empfohlen, besonders im ersten Drittel meiden; nur nach ärztlicher Abwägung.","stillzeit":"Geht in die Muttermilch über und kann die Milchbildung vermindern – in der Stillzeit nicht anwenden.","hinweise":["Ohne ärztlichen Rat nicht länger als 7 Tage einnehmen und nicht mit anderen abschwellenden Erkältungsmitteln kombinieren.","Bei plötzlichen starken Kopfschmerzen, Sehstörungen oder Bauchschmerzen mit Blut im Stuhl sofort absetzen und ärztliche Hilfe holen.","Leistungssport: Pseudoephedrin ist im Wettkampf verboten (Dopingliste)."],"darreichung":["Retardkapseln","Retardtabletten","Granulat"]},"pyrantel":{"wirkmechanismus":"Lähmt die Würmer, die dann mit dem Stuhl ausgeschieden werden. Pyrantel wirkt an den nikotinischen Acetylcholinrezeptoren der Wurmmuskulatur als depolarisierender Blocker und löst eine spastische Lähmung aus. Aus dem Darm wird es nur in geringen Mengen aufgenommen, deshalb sind Nebenwirkungen im übrigen Körper selten.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (Appetitlosigkeit, Übelkeit, Erbrechen, Bauchkrämpfe, Durchfall)","Kopfschmerzen, Schwindel, Schläfrigkeit oder Schlaflosigkeit","Hautausschlag und andere Überempfindlichkeitsreaktionen","Vorübergehend erhöhte Leberwerte"]},"schwangerschaft":"Die Erfahrungen sind begrenzt. Im ersten Schwangerschaftsdrittel nicht und danach nur nach ärztlicher Abwägung anwenden.","stillzeit":"Es ist nicht bekannt, ob Pyrantel in die Muttermilch übergeht; nur nach ärztlicher Rücksprache anwenden.","hinweise":["Einmalige Einnahme unabhängig von den Mahlzeiten; Fasten oder Abführmittel sind nicht nötig. Suspension vor Gebrauch schütteln.","Alle Familienmitglieder mitbehandeln und die Behandlung nach 2–3 Wochen wiederholen.","Hygiene: Hände waschen, Fingernägel kurz halten, Unterwäsche und Bettwäsche heiss waschen."],"darreichung":["Kautabletten","Suspension zum Einnehmen"]},"pyrazinamid":{"wirkmechanismus":"Tötet Tuberkulosebakterien ab, die in saurer Umgebung – etwa in Fresszellen oder abgestorbenem Gewebe – nur langsam wachsen und für andere Mittel schwer erreichbar sind. Pyrazinamid ist eine Vorstufe (Prodrug): Das bakterielle Enzym Pyrazinamidase wandelt es in die wirksame Pyrazinsäure um, die sich im sauren Milieu in den Bakterien anreichert und deren Energiehaushalt und Stoffwechsel stört. Dank dieser «sterilisierenden» Wirkung lässt sich die Standardbehandlung der Tuberkulose auf sechs Monate verkürzen.","nebenwirkungen":{"unbekannt":["Hyperurikämie (erhöhte Harnsäure im Blut), Gichtanfall","Gelenkschmerzen (Arthralgie)","Übelkeit, Erbrechen, Appetitlosigkeit","Erhöhte Leberwerte, Hepatitis bis Leberversagen, Gelbsucht","Lichtempfindlichkeit der Haut (Photosensibilisierung), Ausschlag, Juckreiz","Thrombozytopenie, sideroblastische Anämie","Interstitielle Nephritis, Beschwerden beim Wasserlassen","Fieber, Unwohlsein"]},"schwangerschaft":"Erfahrungen begrenzt; nur nach strenger ärztlicher Abwägung, wenn eine Tuberkulosebehandlung nötig ist.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach ärztlicher Abwägung, Kind beobachten.","hinweise":["Leberwerte und Harnsäure werden vor und während der Behandlung kontrolliert; bei Gelbsucht, dunklem Urin oder Oberbauchschmerzen sofort ärztlich abklären.","Auf Alkohol verzichten (Leberschäden).","Haut vor starker Sonne schützen.","Tuberkulosemittel regelmässig und so lange wie verordnet einnehmen (Resistenzgefahr)."],"darreichung":["Tabletten"]},"pyridostigmin":{"wirkmechanismus":"Verbessert die Muskelkraft bei Myasthenia gravis, indem es den Abbau des Botenstoffs Acetylcholin verlangsamt. Pyridostigmin hemmt reversibel die Acetylcholinesterase; an der motorischen Endplatte steht dadurch mehr Acetylcholin zur Verfügung, um die durch Autoantikörper verminderten Nikotinrezeptoren zu aktivieren. Als quaternäres Amin passiert es die Blut-Hirn-Schranke kaum. Die Wirkung hält länger an als bei Neostigmin.","nebenwirkungen":{"unbekannt":["Übelkeit, Erbrechen, Durchfall, Bauchkrämpfe","Vermehrter Speichelfluss und Bronchialschleim, Schwitzen","Muskelzuckungen (Faszikulationen), Muskelkrämpfe","Zunehmende Muskelschwäche bei Überdosierung (cholinerge Krise)","Langsamer Puls (Bradykardie), Blutdruckabfall","Pupillenverengung (Miosis), vermehrter Tränenfluss","Häufiger Harndrang","Hautausschlag (meist durch Bromid)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; eine bestehende Myasthenie-Behandlung nicht eigenmächtig absetzen.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; der Säugling soll beobachtet werden.","hinweise":["Retardtabletten ganz schlucken, nicht zerkauen oder teilen.","Zeichen einer Überdosierung (starker Speichelfluss, Schwitzen, Bauchkrämpfe, zunehmende Muskelschwäche) sofort ärztlich melden – schwer von einer Verschlechterung der Myasthenie zu unterscheiden.","Vor Operationen und bei neuen Medikamenten auf die Myasthenie und die Behandlung hinweisen."],"darreichung":["Dragées (überzogene Tabletten)","Retardtabletten"]},"pyridoxin-vitamin-b6":{"wirkmechanismus":"Vitamin B6 wird für den Eiweiss- und Aminosäurestoffwechsel, die Blutbildung und die Bildung von Botenstoffen im Nervensystem benötigt. Pyridoxin wird im Körper zu Pyridoxal-5'-phosphat umgewandelt, dem Coenzym von über 100 Enzymen, u. a. von Transaminasen und Decarboxylasen (z. B. bei der Bildung von Serotonin, Dopamin und GABA). Bestimmte Arzneimittel wie Isoniazid binden oder hemmen Vitamin B6 und können so einen Mangel auslösen.","nebenwirkungen":{"unbekannt":["Periphere sensorische Neuropathie (Kribbeln, Taubheit, Gangunsicherheit) bei langdauernder Einnahme hoher Dosen","Überempfindlichkeitsreaktionen der Haut","Magen-Darm-Beschwerden (Übelkeit)"]},"schwangerschaft":"Dosen im Bereich des Tagesbedarfs sind unbedenklich. Hohe Dosen nur nach ärztlicher Abwägung.","stillzeit":"Geht in die Muttermilch über; übliche Dosen sind unbedenklich. Sehr hohe Dosen können die Milchbildung hemmen und sollen vermieden werden.","hinweise":["Hohe Dosen nicht über längere Zeit ohne ärztliche Kontrolle einnehmen; bei Kribbeln oder Taubheit in Händen oder Füssen absetzen und ärztlich abklären lassen.","Auf weitere Vitamin-B6-haltige Präparate (z. B. Vitamin-B-Komplex, Magnesiumpräparate mit B6) achten, um eine Überdosierung zu vermeiden."],"darreichung":["Tabletten"]}});
